// Small things far away (a pebble, a flower, a cup on a table across the island) take up
// less than a few pixels on screen but still cost a whole draw each. Just for the main
// view, anything that small is skipped; it comes back long before it is big enough to
// see. Picking, the map, photos and shadows still see everything, because the skip is
// only switched on around the main render.
import * as THREE from "three";

const HIDE_PX = 2.4; // smaller than this across (in CSS pixels): skipped
const SHOW_PX = 3.2; // back again once it is this big (a gap, so nothing flickers)
const MAX_R = 1.5; // only small things: never a building, a tree or the ground
const EVERY = 0.25; // seconds between looks

export class DetailCull {
  constructor(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.hidden = new Set();
    this.timer = 0;
    this._s = new THREE.Sphere();
    this._last = new THREE.Vector3(1e9, 0, 0);
  }

  update(dt, viewHeight) {
    const cam = this.camera;
    this.timer -= dt;
    // a jump across the island (the map, a respawn) looks again straight away
    if (this.timer > 0 && cam.position.distanceToSquared(this._last) < 400) return;
    this.timer = EVERY;
    this._last.copy(cam.position);
    const pxPerUnit = viewHeight / (2 * Math.tan((cam.fov * Math.PI) / 360));
    const cp = cam.position;
    const s = this._s;
    const next = new Set();
    const walk = (o) => {
      if (!o.visible) return;
      if (o.isMesh && !o.isInstancedMesh && !o.isSkinnedMesh && o.frustumCulled && o.layers.isEnabled(0) && !o.userData.keepDetail) {
        const g = o.geometry;
        if (!g.boundingSphere) g.computeBoundingSphere();
        s.copy(g.boundingSphere).applyMatrix4(o.matrixWorld);
        if (s.radius < MAX_R) {
          const dist = s.center.distanceTo(cp) - s.radius;
          if (dist > 1) {
            const px = ((2 * s.radius) / dist) * pxPerUnit;
            if (px < (this.hidden.has(o) ? SHOW_PX : HIDE_PX)) next.add(o);
          }
        }
      }
      const kids = o.children;
      for (let i = 0; i < kids.length; i++) walk(kids[i]);
    };
    walk(this.scene);
    this.hidden = next;
  }

  // around the main render only
  hide() {
    for (const o of this.hidden) o.layers.disable(0);
  }
  show() {
    for (const o of this.hidden) o.layers.enable(0);
  }

  clear() {
    this.hidden.clear();
  }
}
