// Our photo wall: a big shared album near the willow. Each of us carries a
// mini camera (poses, selfies, couple poses) and there's a tripod with a
// timer for pictures together. Photos are saved here and shared live.
import * as THREE from "three";
import { std, glow } from "./world.js";
import { texture, textCanvas, FONT, isImageData } from "./textures.js";
import { getShared, setShared, onShared } from "./shared.js";

const STORE = "tdd3d.album";

const SOLO_POSES = [
  { id: "peace", emoji: "✌️", label: "peace" },
  { id: "hearthands", emoji: "🫶", label: "heart hands" },
  { id: "blowkiss", emoji: "😘", label: "blow a kiss" },
  { id: "shy", emoji: "🙈", label: "shy" },
  { id: "cheer", emoji: "🙌", label: "yay" },
  { id: "crossed", emoji: "😎", label: "cool" },
];
// couple poses: what I do, what you do, and where you stand
const COUPLE_POSES = [
  { id: "cuddle", emoji: "💞", label: "cuddle", mine: "cuddle", theirs: "cuddle", place: "front" },
  { id: "kiss", emoji: "💋", label: "kiss", mine: "kiss", theirs: "kiss", place: "front" },
  { id: "heart", emoji: "💗", label: "make a heart", mine: "halfR", theirs: "halfL", place: "right" },
  { id: "back", emoji: "😎", label: "back to back", mine: "crossed", theirs: "crossed", place: "back" },
];

export class Album {
  constructor(ctx) {
    this.ctx = ctx;
    // our photos are kept in the database (shared.js), for both of us
    const read = (v) => {
      try {
        return (JSON.parse(v || "[]") || []).filter((it) => isImageData(it?.src));
      } catch {
        return [];
      }
    };
    this.items = read(getShared(STORE));
    onShared((key, value) => {
      if (key !== STORE) return;
      this.items = read(value);
      this.drawWall();
    });
    this.mode = null; // null | "camera"
    this.selfie = false;
    this.timer = 0;
    this.pose = null;
    // a camera you can fly around to frame the shot
    this.free = { on: false, pos: new THREE.Vector3(), vel: new THREE.Vector3() };
    // where the tripod stands is shared: each move counts up, and whoever has
    // the newest move wins, so both of you always end up with the same tripod
    this.tripodVer = 0;
    this.tripodBy = "";
    this.buildWall(ctx.pos);
    this.buildUI();
    this.drawWall();
  }

  // ---- the wall ----------------------------------------------------------------
  buildWall(pos) {
    const { scene, world } = this.ctx;
    const g = new THREE.Group();
    g.position.copy(pos);
    // face the middle of the island
    g.rotation.y = Math.atan2(-pos.x, -pos.z + 4);
    scene.add(g);
    this.group = g;
    const wood = std("#ffffff", { map: texture("wood", ["#c9a27e", "#a07a58"]) });
    const W = 6.6;
    const H = 3.2;
    const box = (w, h, d, m, x, y, z) => {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      g.add(mesh);
      return mesh;
    };
    for (const s of [-1, 1]) box(0.22, 4.4, 0.22, wood, s * (W / 2 + 0.05), 2.2, 0);
    box(W + 0.5, H + 0.3, 0.16, wood, 0, 0.6 + H / 2 + 0.15, -0.1);
    box(W + 0.9, 0.18, 0.5, std("#e2557f"), 0, 0.6 + H + 0.4, -0.05);
    // the photo board
    this.wallCanvas = textCanvas(2048, Math.round((2048 * (H - 0.2)) / (W - 0.2)));
    const board = new THREE.Mesh(new THREE.PlaneGeometry(W - 0.2, H - 0.2), new THREE.MeshBasicMaterial({ map: this.wallCanvas.tex, toneMapped: false }));
    board.position.set(0, 0.6 + H / 2 + 0.15, 0.0);
    g.add(board);
    this.board = board;
    // string lights along the top, front and back
    for (const side of [1, -1]) {
      for (let k = 0; k <= 16; k++) {
        const t = k / 16;
        const b = new THREE.Mesh(new THREE.IcosahedronGeometry(0.06, 0), k % 2 ? glow.warm : glow.pink);
        b.position.set(-W / 2 + W * t, 0.6 + H + 0.12 - Math.sin(t * Math.PI) * 0.18, side > 0 ? 0.12 : -0.32);
        g.add(b);
      }
    }
    // the back isn't bare planks: a painted mural for whoever walks round behind
    const mural = new THREE.Mesh(new THREE.PlaneGeometry(W + 0.3, H + 0.1), new THREE.MeshStandardMaterial({ map: muralTex(), roughness: 0.9 }));
    mural.position.set(0, 0.6 + H / 2 + 0.15, -0.185);
    mural.rotation.y = Math.PI;
    mural.receiveShadow = true;
    g.add(mural);
    // the posing spot (a star on the grass) and a tripod with a camera
    const star = new THREE.Shape();
    for (let k = 0; k < 10; k++) {
      const r = k % 2 ? 0.35 : 0.8;
      const a = (k / 10) * Math.PI * 2;
      k ? star.lineTo(Math.sin(a) * r, Math.cos(a) * r) : star.moveTo(Math.sin(a) * r, Math.cos(a) * r);
    }
    const starMesh = new THREE.Mesh(new THREE.ShapeGeometry(star), new THREE.MeshBasicMaterial({ color: "#ffd166", transparent: true, opacity: 0.8, depthWrite: false }));
    starMesh.rotation.x = -Math.PI / 2;
    starMesh.position.set(0, 0.03, 4.6);
    g.add(starMesh);
    const tri = new THREE.Group();
    scene.add(tri);
    const dark = std("#2b2633");
    const legs = new THREE.Group();
    tri.add(legs);
    for (let k = 0; k < 3; k++) {
      const a = (k / 3) * Math.PI * 2;
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 1.5, 4), dark);
      leg.position.set(Math.sin(a) * 0.22, 0.72, Math.cos(a) * 0.22);
      leg.rotation.set(Math.cos(a) * 0.3, 0, -Math.sin(a) * 0.3);
      legs.add(leg);
    }
    const cam = new THREE.Group();
    cam.position.y = 1.5;
    tri.add(cam);
    this.tri = { group: tri, legs, cam };
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.24, 0.18), std("#ff8fb1"));
    cam.add(body);
    const lens = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.09, 0.12, 12), dark);
    lens.rotation.x = Math.PI / 2;
    lens.position.z = -0.14;
    cam.add(lens);
    const light = new THREE.Mesh(new THREE.SphereGeometry(0.03, 6, 4), new THREE.MeshBasicMaterial({ color: "#ff3b5c" }));
    light.position.set(0.12, 0.08, -0.09);
    cam.add(light);
    this.recLight = light;
    g.updateMatrixWorld(true);
    const toW = (x, y, z) => new THREE.Vector3(x, y, z).applyMatrix4(g.matrixWorld);
    this.spot = toW(0, 0, 4.6);
    // the tripod starts by the wall, a little to one side, looking out over the star: you
    // pose with our willow, its heart garland and the starry sky behind you, the island's
    // lights twinkling far off (world.js keeps that view clear of bushes)
    this.tripodHome = { cam: toW(-1.7, 1.6, 1.1), look: toW(0.3, 1.35, 4.6) };
    this.tripodCamera = new THREE.PerspectiveCamera(50, 7 / 6, 0.1, 900);
    for (const s of [-1, 1]) {
      const p = toW(s * (W / 2 + 0.05), 0, 0);
      world.circles.push({ x: p.x, z: p.z, r: 0.2 });
    }
    const a = toW(-W / 2, 0, -0.1);
    const b = toW(W / 2, 0, -0.1);
    world.segments.push({ ax: a.x, az: a.z, bx: b.x, bz: b.z, h: 4, room: "" });
    this.triCircle = { x: 0, z: 0, r: 0.3 };
    world.circles.push(this.triCircle);
    // interactables (screens are handled by us, not the widget code)
    const room = this.ctx.room;
    const wallItem = { id: "album", label: "look at our photos 📸", pos: toW(0, 0, 1.4), radius: 2.4, action: { type: "album" }, room: room?.def.id, hits: [board] };
    board.userData.item = wallItem;
    const triItem = { id: "tripod", label: "take a photo together ⏱", pos: toW(0, 0, 7.9), radius: 1.5, action: { type: "tripod" }, room: room?.def.id, hits: [body] };
    body.userData.item = triItem;
    this.triItem = triItem;
    world.interactables.push(wallItem, triItem);
    this.moveTripod(this.tripodHome.cam, this.tripodHome.look, 0);
  }

  // stand the tripod so its camera is at cam, looking at look
  moveTripod(cam, look, ground) {
    const { group, legs, cam: head } = this.tri;
    const h = THREE.MathUtils.clamp(cam.y - ground, 0.5, 4);
    group.position.set(cam.x, cam.y - h, cam.z);
    group.rotation.y = Math.atan2(-(look.x - cam.x), -(look.z - cam.z));
    legs.scale.y = h / 1.5;
    head.position.y = h;
    this.tripodCam = cam.clone();
    this.tripodLook = look.clone();
    this.triCircle.x = cam.x;
    this.triCircle.z = cam.z;
    if (this.triItem) {
      const back = new THREE.Vector3(cam.x - look.x, 0, cam.z - look.z).normalize();
      this.triItem.pos = new THREE.Vector3(cam.x + back.x * 0.7, ground, cam.z + back.z * 0.7);
    }
    const tc = this.tripodCamera;
    tc.position.copy(cam);
    tc.lookAt(look);
  }

  drawWall() {
    const shown = this.items;
    const ticket = (this.wallTicket = (this.wallTicket || 0) + 1);
    return Promise.all(shown.map((it) => loadImg(it.src).catch(() => null))).then((imgs) => {
      if (ticket === this.wallTicket) this.paintWall(shown, imgs);
    });
  }

  paintWall(shown, imgs) {
    const { ctx, tex } = this.wallCanvas;
    const CW = ctx.canvas.width;
    const CH = ctx.canvas.height;
    // a soft blush felt board with a faint scatter of little hearts
    const bg = ctx.createLinearGradient(0, 0, 0, CH);
    bg.addColorStop(0, "#f7d9e6");
    bg.addColorStop(1, "#eec3d6");
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, CW, CH);
    for (let i = 0; i < 1600; i++) {
      ctx.fillStyle = i % 3 ? "rgba(190,110,150,0.08)" : "rgba(255,255,255,0.18)";
      ctx.fillRect((i * 977) % CW, (i * 613) % CH, 3, 3);
    }
    ctx.fillStyle = "rgba(226,85,127,0.12)";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.font = `40px ${FONT}`;
    for (let y = 60, r = 0; y < CH; y += 150, r++) for (let x = r % 2 ? 150 : 60; x < CW; x += 180) ctx.fillText("♡", x, y);
    // twelve fit at full size; after that every new photo squeezes the grid a little so
    // they all still fit, however many there are (whichever grid keeps them biggest)
    const n = shown.length;
    const fit = (cols, rows) => Math.min((CW / cols) * 0.8 / 600, (CH / rows) * 0.9 / 700);
    let cols = 6;
    let rows = 2;
    if (n > 12) {
      let best = 0;
      for (let r = 2; r <= n; r++) {
        const c = Math.ceil(n / r);
        if (fit(c, r) > best) [best, cols, rows] = [fit(c, r), c, r];
      }
    }
    const cw = CW / cols;
    const rh = CH / rows;
    const scale = fit(cols, rows);
    if (!n) {
      ctx.fillStyle = "#8a3f63";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.font = `700 64px ${FONT}`;
      ctx.fillText("˚₊‧ our photo wall ‧₊˚", CW / 2, CH / 2 - 40);
      ctx.font = `500 40px ${FONT}`;
      ctx.fillText("take a picture with your camera 📷 or the tripod ⏱", CW / 2, CH / 2 + 40);
    }
    shown.forEach((it, i) => {
      const img = imgs[i];
      if (!img) return;
      const c = i % cols;
      const r = Math.floor(i / cols);
      // a part-filled last row sits in the middle (only once the grid has had to grow)
      const inRow = n > 12 && r === rows - 1 ? n - r * cols : cols;
      const x = (c + (cols - inRow) / 2) * cw + cw / 2;
      const y = r * rh + rh / 2;
      const rot = (((i * 37) % 11) - 5) * 0.012;
      const k = scale / fit(6, 2);
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(rot);
      ctx.shadowColor = "rgba(60,30,20,0.35)";
      ctx.shadowBlur = 16 * k;
      ctx.shadowOffsetY = 6 * k;
      ctx.drawImage(img, (-600 * scale) / 2, (-700 * scale) / 2, 600 * scale, 700 * scale);
      ctx.shadowColor = "transparent";
      ctx.fillStyle = ["#e2557f", "#7b5cd6", "#ffd166", "#6fa8e8"][i % 4];
      ctx.beginPath();
      ctx.arc(0, (-700 * scale) / 2 + 12 * k, 13 * k, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    });
    tex.needsUpdate = true;
  }

  // ---- storage and sharing -----------------------------------------------------------
  save() {
    if (this.ctx.isGuest) return; // a visitor only sees what we hand them
    setShared(STORE, JSON.stringify(this.items));
  }
  addItem(item, send = true) {
    if (!item?.id || !isImageData(item.src) || this.items.some((x) => x.id === item.id)) return false;
    this.items.unshift(item);
    this.items.sort((a, b) => b.at - a.at);
    this.save();
    this.drawWall();
    if (send) this.ctx.net.send("photo", { item });
    return true;
  }
  removeItem(id, send = true) {
    const before = this.items.length;
    this.items = this.items.filter((x) => x.id !== id);
    if (this.items.length === before) return;
    this.save();
    this.drawWall();
    if (send) this.ctx.net.send("unphoto", { id });
  }
  // when your person arrives, hand them the photos they're missing
  shareWith(key) {
    this.items.forEach((item, i) => setTimeout(() => this.ctx.net.send("photo", { item, sync: true }, key), 400 + i * 350));
  }
  onRemote(p, who) {
    if (p.t === "photo") {
      if (this.addItem(p.item, false) && !p.sync) this.ctx.toast(`${who || "your person"} pinned a new photo 📸`);
    } else if (p.t === "unphoto") this.removeItem(p.id, false);
    else if (p.t === "pose") this.onCouplePose(p, who);
    else if (p.t === "timer") this.ctx.toast(`📸 ${who || "your person"} set the timer: stand on the star ⭐`);
    else if (p.t === "tripod") this.onRemoteTripod(p, who, p.key);
    else if (p.t === "tsnap" && this.tripodOn && this.mode === "camera" && !this.counting) {
      this.ctx.toast(`📸 ${who || "your person"} pressed the shutter: get in the shot!`);
      this.countdown(5, () => this.capture());
    }
  }

  // ---- UI ---------------------------------------------------------------------------------
  buildUI() {
    const { h } = this.ctx;
    // camera mode: a viewfinder and a pose bar
    this.poseRow = h("div", { class: "g3d-cam-poses" });
    this.countEl = h("div", { class: "g3d-cam-count", hidden: true });
    this.shutter = h("button", { class: "g3d-cam-shutter", type: "button", "aria-label": "take the photo", onclick: () => this.snap() });
    this.selfieBtn = h("button", { class: "g3d-cbtn", type: "button", title: "selfie", "aria-label": "selfie", onclick: () => this.toggleSelfie() }, "🤳");
    this.timerBtn = h("button", { class: "g3d-cpill", type: "button", title: "3 second timer", onclick: () => this.toggleTimer() }, "⏱ off");
    this.tripodBtn = h("button", { class: "g3d-cbtn", type: "button", title: "put the tripod here", "aria-label": "put the tripod here", onclick: () => this.placeTripodHere() }, "📍");
    this.freeBtn = h("button", { class: "g3d-cbtn", type: "button", title: "move the camera freely", "aria-label": "move the camera", onclick: () => this.toggleFree() }, "🎥");
    this.zoomEl = h("input", { class: "g3d-cam-zoom", type: "range", min: "0", max: "1", step: "0.01", value: "0.5", "aria-label": "zoom" });
    this.zoomEl.addEventListener("input", () => this.setZoom(+this.zoomEl.value));
    this.zoomBy = { view: 0.5, selfie: 0.4, tripod: 0.4 };
    this.frameEl = h("div", { class: "g3d-cam-frame" }, h("span"), h("span"), h("span"), h("span"));
    this.pipEl = h("div", { class: "g3d-cam-pip", hidden: true },
      h("small", {}, "⏱ tripod"),
      h("button", { class: "g3d-cam-pipx", type: "button", title: "stop using the tripod", "aria-label": "stop using the tripod", onclick: () => this.leaveTripod() }, "✕"),
    );
    this.barEl = h("div", { class: "g3d-cam-bar" },
      this.poseRow,
      h("label", { class: "g3d-cam-zoomrow" }, h("span", {}, "🔍"), this.zoomEl),
      h("div", { class: "g3d-cam-row" },
        h("button", { class: "g3d-cbtn", type: "button", title: "put the camera away", "aria-label": "close camera", onclick: () => this.closeCamera() }, "✕"),
        this.timerBtn,
        this.selfieBtn,
        this.shutter,
        this.freeBtn,
        this.tripodBtn,
        h("button", { class: "g3d-cbtn", type: "button", title: "our photo wall", "aria-label": "our photo wall", onclick: () => this.openWall() }, "🖼️"),
      ),
    );
    this.camUI = h("div", { class: "g3d-cam", hidden: true }, this.frameEl, this.pipEl, this.countEl, this.barEl);
    this.onResize = () => this.layoutFrame();
    window.addEventListener("resize", this.onResize);
    this.flash = h("div", { class: "g3d-cam-flash" });
    // after the photo: post it?
    this.previewImg = h("img", { class: "g3d-gallery-img g3d-photo-img", alt: "" });
    this.previewActions = h("div", { class: "g3d-gallery-actions" });
    this.preview = h("div", { class: "g3d-overlay g3d-photo-preview", hidden: true, role: "dialog", "aria-label": "your photo" },
      h("div", { class: "g3d-sheet" },
        h("header", { class: "g3d-panel-head" }, h("h2", { class: "g3d-sheet-title" }, "˚₊‧ cute! ‧₊˚"), h("button", { class: "g3d-close", type: "button", "aria-label": "close", onclick: () => (this.preview.hidden = true) }, "✕")),
        h("div", { class: "g3d-help-body g3d-gallery-body" }, this.previewImg, this.previewActions),
      ),
    );
    // the album: every photo, tap one to see it big
    this.grid = h("div", { class: "g3d-album-grid" });
    this.viewer = h("div", { class: "g3d-album-viewer", hidden: true });
    this.wallView = h("div", { class: "g3d-overlay g3d-album", hidden: true, role: "dialog", "aria-label": "our photo wall" },
      h("div", { class: "g3d-sheet g3d-album-sheet" },
        h("header", { class: "g3d-panel-head" }, h("h2", { class: "g3d-sheet-title" }, "˚₊‧ our photo wall ‧₊˚"), h("button", { class: "g3d-close", type: "button", "aria-label": "close", onclick: () => this.closeWall() }, "✕")),
        this.grid,
        this.viewer,
      ),
    );
    for (const el of [this.camUI, this.preview, this.wallView]) {
      for (const type of ["touchstart", "touchmove", "touchend"]) el.addEventListener(type, (e) => e.stopPropagation(), { passive: true });
    }
    document.body.append(this.camUI, this.flash, this.preview, this.wallView);
    this.renderPoses();
  }

  renderPoses() {
    const { h } = this.ctx;
    const chip = (p, couple) =>
      h("button", { class: `g3d-pose ${this.pose === p.id ? "on" : ""}`, type: "button", title: p.label, onclick: () => (couple ? this.couplePose(p) : this.setPose(p.id)) }, h("span", {}, p.emoji), h("small", {}, p.label));
    this.poseRow.replaceChildren(
      h("div", { class: "g3d-pose-group" }, h("span", { class: "g3d-cinema-label" }, "poses"), ...SOLO_POSES.map((p) => chip(p, false))),
      h("div", { class: "g3d-pose-group" }, h("span", { class: "g3d-cinema-label" }, "together"), ...COUPLE_POSES.map((p) => chip(p, true))),
    );
  }

  setPose(id, quiet = false) {
    this.pose = this.pose === id ? null : id;
    this.ctx.avatar.pose = this.pose;
    if (!quiet) this.ctx.audio.sfx("pop");
    this.renderPoses();
  }

  couplePose(p) {
    const { net, player, toast } = this.ctx;
    const near = net.nearest(player.pos, 10);
    if (!near) {
      toast("couple poses need your person close by ♡");
      return;
    }
    // tap it again to let go (for both of you)
    if (this.pose === p.id) {
      this.clearPose();
      return;
    }
    this.pose = p.id;
    this.ctx.avatar.pose = p.mine;
    this.renderPoses();
    // where the photo is taken from: face it for side-by-side poses,
    // face each other for cuddles and kisses
    const cam = this.tripodOn ? this.tripodCam : this.ctx.camera.position;
    const toCam = Math.atan2(cam.x - player.pos.x, cam.z - player.pos.z);
    // cuddles and kisses: side on to the camera, so it sees you both in profile
    if (p.place === "front") player.facing = toCam + (Math.sin(Math.atan2(near.pos.x - player.pos.x, near.pos.z - player.pos.z) - toCam) >= 0 ? Math.PI / 2 : -Math.PI / 2);
    else if (p.place === "right") player.facing = toCam;
    else player.facing = toCam + Math.PI / 2; // back to back: side on to the camera
    player.speed = 0;
    this.partnerKey = near.key;
    net.send("pose", { pose: p.id, x: player.pos.x, z: player.pos.z, f: player.facing, cy: toCam }, near.key);
    this.ctx.audio.sfx("pop");
  }

  // your person asked for a couple pose: step in and do your half
  onCouplePose(p, who) {
    const def = COUPLE_POSES.find((c) => c.id === p.pose);
    const { player, collide, toast } = this.ctx;
    if (!p.pose) {
      // they let go
      if (COUPLE_POSES.some((c) => c.id === this.pose)) this.clearPose(false);
      return;
    }
    if (!def) return;
    if (Math.hypot(player.pos.x - p.x, player.pos.z - p.z) > 12) return;
    const f = p.f;
    const fwd = [Math.sin(f), Math.cos(f)];
    const right = [-Math.cos(f), Math.sin(f)];
    let x = p.x;
    let z = p.z;
    let face = f + Math.PI;
    if (def.place === "front") {
      // far enough apart that faces meet without going through each other
      const gap = def.id === "kiss" ? 1.02 : 0.74;
      x += fwd[0] * gap;
      z += fwd[1] * gap;
    } else if (def.place === "right") {
      // shoulder to shoulder on their right, both facing the camera
      x += right[0] * 0.7;
      z += right[1] * 0.7;
      face = f;
    } else if (def.place === "back") {
      // backs touching, looking the other way
      x -= fwd[0] * 0.5;
      z -= fwd[1] * 0.5;
    }
    this.partnerKey = p.key;
    // swing your camera round to the front too, so you see the pose
    if (Number.isFinite(p.cy) && this.ctx.controls) {
      this.ctx.controls.yaw = p.cy;
      this.ctx.controls.pitch = 0.15;
    }
    player.pos.x = x;
    player.pos.z = z;
    collide?.(player.pos);
    player.facing = face;
    player.speed = 0;
    this.ctx.avatar.pose = def.theirs;
    this.pose = def.id;
    this.renderPoses();
    toast(`${who || "your person"} wants a ${def.label} photo ${def.emoji}`);
    clearTimeout(this.poseTimer);
    // let go after a while (or when they let go, or you move)
    this.poseTimer = setTimeout(() => {
      if (this.pose === def.id) this.clearPose(false);
    }, 25000);
  }

  // a glowing heart between your hands while you make one together
  updateHeart(t) {
    const r = this.partnerKey ? this.ctx.net.remotes.get(this.partnerKey) : null;
    const on = this.pose === "heart" && r;
    if (!on) {
      if (this.heartSprite) this.heartSprite.visible = false;
      return;
    }
    if (!this.heartSprite) {
      const { ctx, tex } = textCanvas(128, 128);
      ctx.font = "104px serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("💗", 64, 70);
      tex.needsUpdate = true;
      this.heartSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
      this.ctx.scene.add(this.heartSprite);
    }
    const p = this.ctx.player.pos;
    const h = this.ctx.avatar.dims.height;
    this.heartSprite.visible = true;
    this.heartSprite.position.set((p.x + r.pos.x) / 2, Math.max(p.y, r.pos.y) + h + 0.25, (p.z + r.pos.z) / 2);
    this.heartSprite.scale.setScalar(0.62 + Math.sin(t * 4) * 0.05);
  }

  clearPose(tell = true) {
    const wasCouple = COUPLE_POSES.some((c) => c.id === this.pose);
    this.pose = null;
    this.ctx.avatar.pose = null;
    this.renderPoses();
    if (tell && wasCouple && this.partnerKey) this.ctx.net.send("pose", { pose: null }, this.partnerKey);
    this.partnerKey = null;
  }

  // walking away breaks a couple pose
  checkMoved() {
    if (this.pose && COUPLE_POSES.some((c) => c.id === this.pose) && this.ctx.player.speed > 1.2) this.clearPose();
  }

  openCamera() {
    this.ctx.closeOthers?.();
    this.mode = "camera";
    this.camUI.hidden = false;
    this.ctx.root.classList.add("in-camera");
    this.ctx.audio.sfx("equip");
    this.syncZoom();
    this.layoutFrame();
    requestAnimationFrame(() => this.layoutFrame());
  }
  closeCamera() {
    this.mode = null;
    this.selfie = false;
    this.selfieBtn.classList.remove("on");
    this.setFree(false);
    // putting your camera away leaves the tripod standing where it is
    this.setTripodOn(false);
    this.camUI.hidden = true;
    this.centerView();
    this.ctx.root.classList.remove("in-camera");
    this.clearPose();
  }
  toggleSelfie() {
    this.selfie = !this.selfie;
    this.selfieBtn.classList.toggle("on", this.selfie);
    if (this.selfie) {
      this.setTripodOn(false);
      this.setFree(false);
    }
    this.syncZoom();
  }

  // ---- the free camera: WASD or the stick flies it where you look, drag to look round ----
  get freeCam() {
    return this.mode === "camera" && this.free.on;
  }
  setFree(on) {
    if (on && !this.free.on) {
      this.free.pos.copy(this.ctx.camera.position);
      this.free.vel.set(0, 0, 0);
    }
    this.free.on = on;
    if (this.ctx.controls) this.ctx.controls.lookScale = on ? 0.55 : 1;
    this.freeBtn.classList.toggle("on", on);
    this.freeBtn.title = on ? "back to following you" : "move the camera freely";
  }
  toggleFree() {
    const on = !this.free.on;
    if (on) {
      this.selfie = false;
      this.selfieBtn.classList.remove("on");
    }
    this.setFree(on);
    this.ctx.audio.sfx("pop");
    if (on) this.ctx.toast(this.ctx.isTouch ? "move the camera with the stick, drag to look ⋆ then 📍 to leave the tripod there" : "WASD flies the camera where you look, drag to look round ⋆ 📍 leaves the tripod there");
  }
  lookDir() {
    const { controls } = this.ctx;
    const cp = Math.cos(controls.pitch);
    return new THREE.Vector3(-Math.sin(controls.yaw) * cp, -Math.sin(controls.pitch), -Math.cos(controls.yaw) * cp);
  }
  // called every frame with the move input while the free camera is on
  moveFree(mv, dt) {
    const { player } = this.ctx;
    const f = this.free.pos;
    const v = this.free.vel;
    // the stick slides the camera mostly level (forward is where you face, rising
    // or sinking gently with your look), so framing a shot never dives it
    const dir = this.lookDir();
    const fwd = new THREE.Vector3(dir.x, 0, dir.z);
    if (fwd.lengthSq() < 1e-6) fwd.set(0, 0, -1);
    fwd.normalize();
    const right = new THREE.Vector3(-fwd.z, 0, fwd.x);
    const speed = mv.run ? 8 : 4;
    const want = fwd.multiplyScalar(mv.y * speed).addScaledVector(right, mv.x * speed);
    want.y = dir.y * mv.y * speed * 0.6;
    // glide: ease into and out of moving instead of starting and stopping dead
    v.lerp(want, 1 - Math.exp(-dt * 7));
    f.addScaledVector(v, dt);
    // keep it near you and above the grass
    const off = f.clone().sub(player.pos);
    if (off.length() > 40) f.copy(player.pos).addScaledVector(off.normalize(), 40);
    f.y = Math.max(player.pos.y + 0.25, Math.min(player.pos.y + 25, f.y));
  }

  // ---- zoom: the view, the selfie arm or the tripod's lens -------------------------------
  zoomMode() {
    return this.tripodOn ? "tripod" : this.selfie ? "selfie" : "view";
  }
  setZoom(v) {
    const m = this.zoomMode();
    this.zoomBy[m] = v;
    if (m === "view" && this.ctx.controls) this.ctx.controls.dist = THREE.MathUtils.lerp(14, 3.2, v);
    if (m === "tripod") {
      this.tripodCamera.fov = THREE.MathUtils.lerp(72, 20, v);
      this.tripodCamera.updateProjectionMatrix();
    }
  }
  syncZoom() {
    const m = this.zoomMode();
    if (m === "view" && this.ctx.controls) this.zoomBy.view = THREE.MathUtils.clamp((14 - this.ctx.controls.dist) / 10.8, 0, 1);
    this.zoomEl.value = String(this.zoomBy[m]);
    this.setZoom(this.zoomBy[m]);
  }

  // ---- the tripod: set it up anywhere, see what it sees, then get in the shot -----------
  // the viewfinder shows exactly what the photo will be: a 7:6 box above the bar
  layoutFrame() {
    if (this.camUI.hidden) return;
    const bar = this.barEl.getBoundingClientRect();
    const top = 64;
    const bottom = (bar.top || innerHeight) - 12;
    const availH = Math.max(80, bottom - top);
    const availW = innerWidth - 24;
    let w = availW;
    let hh = (w * 6) / 7;
    if (hh > availH) {
      hh = availH;
      w = (hh * 7) / 6;
    }
    Object.assign(this.frameEl.style, { left: (innerWidth - w) / 2 + "px", top: top + (availH - hh) / 2 + "px", width: w + "px", height: hh + "px", right: "auto", bottom: "auto" });
    this.centerView();
  }
  // the view is nudged up so you are in the middle of the viewfinder, not low in it
  centerView() {
    const { camera, renderer } = this.ctx;
    const on = this.mode === "camera" && !this.camUI.hidden && !this.tripodOn;
    if (!on) {
      if (camera.view?.enabled) {
        camera.clearViewOffset();
        camera.updateProjectionMatrix();
      }
      return;
    }
    const size = renderer.getSize(new THREE.Vector2());
    const view = renderer.domElement.getBoundingClientRect();
    const f = this.frameEl.getBoundingClientRect();
    const dy = Math.round(size.y / 2 - (f.top + f.height / 2 - view.top));
    camera.setViewOffset(size.x, size.y, 0, dy, size.x, size.y);
    camera.updateProjectionMatrix();
  }
  // looking through the tripod is just for you; where it stands is shared
  setTripodOn(on) {
    this.tripodOn = on;
    this.pipEl.hidden = !on;
    this.frameEl.hidden = on;
    this.centerView();
    this.tripodBtn.classList.toggle("on", on);
    this.tripodBtn.title = on ? "move the tripod here" : "put the tripod here";
    this.tripodBtn.setAttribute("aria-label", this.tripodBtn.title);
    if (on) {
      this.selfie = false;
      this.selfieBtn.classList.remove("on");
    }
  }
  leaveTripod() {
    this.setTripodOn(false);
    this.syncZoom();
    this.ctx.audio.sfx("pop");
  }
  tripodState() {
    const r2 = (v) => v.toArray().map((n) => +n.toFixed(2));
    return { v: this.tripodVer, by: this.tripodBy, cam: r2(this.tripodCam), look: r2(this.tripodLook), ground: +this.tri.group.position.y.toFixed(2) };
  }
  // sent with your state every couple of seconds, so a missed message, a reload
  // or your person arriving late still ends with the tripod in the same place
  tripodSync() {
    return this.tripodVer ? this.tripodState() : null;
  }
  // a tripod position from your person: use it if it's newer than ours
  applyTripod(p, from) {
    const vec = (a) => (Array.isArray(a) && a.length === 3 && a.every(Number.isFinite) ? new THREE.Vector3(...a) : null);
    const cam = vec(p?.cam);
    const look = vec(p?.look);
    if (!cam || !look) return false;
    // an older island sends no count: its move is always the newest
    const v = Number.isFinite(p.v) ? p.v : this.tripodVer + 1;
    const by = typeof p.by === "string" ? p.by : String(from || "");
    if (v < this.tripodVer || (v === this.tripodVer && by <= this.tripodBy)) return false;
    this.tripodVer = v;
    this.tripodBy = by;
    this.moveTripod(cam, look, Number.isFinite(p.ground) ? p.ground : cam.y - 1.5);
    return true;
  }
  isCurrentTripod(p) {
    return p.v === this.tripodVer && p.by === this.tripodBy;
  }
  // put the tripod where you're looking from right now (tap again to move it)
  placeTripodHere() {
    const { camera, player, net } = this.ctx;
    const dir = new THREE.Vector3();
    camera.getWorldDirection(dir);
    const look = camera.position.clone().addScaledVector(dir, 6);
    this.moveTripod(camera.position.clone(), look, player.pos.y);
    this.tripodVer += 1;
    this.tripodBy = net.myKey || "";
    // done framing: you walk again, and the little window shows the tripod's view
    this.setFree(false);
    this.setTripodOn(true);
    this.syncZoom();
    net.send("tripod", { ...this.tripodState(), call: 1 });
    this.ctx.audio.sfx("equip");
    this.ctx.toast("tripod's up ⏱ get in the shot and press the shutter · 📍 again moves it");
  }
  // drawn after the world: a little window showing what the tripod sees
  renderExtra(renderer) {
    if (!this.tripodOn || this.camUI.hidden) return;
    const r = this.pipEl.getBoundingClientRect();
    if (!r.width) return;
    const size = renderer.getSize(new THREE.Vector2());
    const tc = this.tripodCamera;
    tc.aspect = r.width / r.height;
    tc.updateProjectionMatrix();
    renderer.setScissorTest(true);
    renderer.setScissor(r.left, size.y - r.bottom, r.width, r.height);
    renderer.setViewport(r.left, size.y - r.bottom, r.width, r.height);
    renderer.render(this.ctx.scene, tc);
    renderer.setScissorTest(false);
    renderer.setViewport(0, 0, size.x, size.y);
  }
  toggleTimer() {
    this.useTimer = !this.useTimer;
    this.timerBtn.textContent = this.useTimer ? "⏱ 3s" : "⏱ off";
    this.timerBtn.classList.toggle("on", this.useTimer);
  }

  // your person moved the tripod: it moves for you too, and if they're calling
  // you over (and you're close), your camera opens on it
  onRemoteTripod(p, who, from) {
    // older islands also said when they stopped looking through it: that's theirs alone
    if (p.off) return;
    const moved = this.applyTripod(p, from);
    if (!p.call && Number.isFinite(p.v)) return;
    if (!moved && !this.isCurrentTripod(p)) return;
    if (this.tripodCam.distanceTo(this.ctx.player.pos) > 45) return;
    if (this.mode !== "camera") this.openCamera();
    this.setFree(false);
    this.setTripodOn(true);
    this.syncZoom();
    this.ctx.toast(`📸 ${who || "your person"} ${moved ? "set up the tripod" : "is at the tripod"}: get in the shot ♡`);
  }
  // the same, from your person's regular updates (never opens your camera)
  onTripodSync(p, from) {
    this.applyTripod(p, from);
  }

  // the tripod (by the wall, or wherever it was left): open the camera on it
  startTripod() {
    if (this.mode !== "camera") this.openCamera();
    this.setFree(false);
    this.setTripodOn(true);
    this.syncZoom();
    // and call your person over to it
    this.ctx.net.send("tripod", { ...this.tripodState(), call: 1 });
    this.ctx.toast("the tripod's ready ⏱ get in the shot, then press the shutter");
  }
  // you turn to the tripod while it counts down (unless you're walking or posing together)
  faceTripod() {
    const { player } = this.ctx;
    if (!this.tripodOn || player.speed > 0.3 || player.sitting || COUPLE_POSES.some((c) => c.id === this.pose)) return;
    player.facing = Math.atan2(this.tripodCam.x - player.pos.x, this.tripodCam.z - player.pos.z);
  }

  snap() {
    if (this.counting) return;
    if (this.tripodOn) {
      // time to run into the picture (your person's camera counts down and snaps too)
      this.ctx.net.send("tsnap", {});
      this.countdown(5, () => this.capture());
    } else if (this.useTimer) this.countdown(3, () => this.capture());
    else this.capture();
  }

  countdown(n, done) {
    this.counting = true;
    this.countEl.hidden = false;
    document.body.append(this.countEl);
    const tick = () => {
      if (n <= 0) {
        this.countEl.hidden = true;
        this.counting = false;
        done();
        return;
      }
      this.faceTripod();
      this.countEl.textContent = String(n);
      this.countEl.classList.remove("pop");
      void this.countEl.offsetWidth;
      this.countEl.classList.add("pop");
      this.ctx.audio.sfx("tick");
      n--;
      setTimeout(tick, 1000);
    };
    tick();
  }

  // where the camera goes while you take pictures (or null for the normal view)
  cameraOverride(out, target) {
    const { player, avatar } = this.ctx;
    if (this.freeCam) {
      out.copy(this.free.pos);
      target.copy(this.free.pos).add(this.lookDir());
      return true;
    }
    if (this.mode === "camera" && this.selfie) {
      const f = player.facing;
      const h = avatar.dims.height;
      const d = THREE.MathUtils.lerp(3.6, 1.1, this.zoomBy.selfie);
      out.set(player.pos.x + Math.sin(f) * d + Math.cos(f) * 0.25, player.pos.y + h * 0.9, player.pos.z + Math.cos(f) * d - Math.sin(f) * 0.25);
      target.set(player.pos.x, player.pos.y + h * 0.62, player.pos.z);
      return true;
    }
    return false;
  }

  capture() {
    const { renderer, scene, camera, hideTags, audio, myName } = this.ctx;
    hideTags(true);
    const src = renderer.domElement;
    const sw = src.width;
    const sh = src.height;
    let cx;
    let cy;
    let cw;
    let ch;
    if (this.tripodOn) {
      // from the tripod: a 7:6 crop from the middle, like its little window
      const tc = this.tripodCamera;
      tc.aspect = sw / sh;
      tc.updateProjectionMatrix();
      renderer.render(scene, tc);
      cw = sw;
      ch = (sw * 480) / 560;
      if (ch > sh) {
        ch = sh;
        cw = (sh * 560) / 480;
      }
      cx = (sw - cw) / 2;
      cy = (sh - ch) / 2;
    } else {
      // exactly the box in the viewfinder
      renderer.render(scene, camera);
      const view = src.getBoundingClientRect();
      const f = this.frameEl.getBoundingClientRect();
      const k = sw / (view.width || 1);
      cx = Math.max(0, (f.left - view.left) * k);
      cy = Math.max(0, (f.top - view.top) * k);
      cw = Math.min(sw - cx, f.width * k);
      ch = Math.min(sh - cy, f.height * k);
    }
    const pol = document.createElement("canvas");
    pol.width = 600;
    pol.height = 700;
    const x = pol.getContext("2d");
    x.fillStyle = "#fffdf8";
    x.fillRect(0, 0, 600, 700);
    try {
      x.drawImage(src, cx, cy, cw, ch, 20, 20, 560, 480);
    } catch {}
    hideTags(false);
    const date = new Date();
    x.fillStyle = "#5b3a55";
    x.textAlign = "center";
    x.font = `700 38px ${FONT}`;
    x.fillText("toto & dodo ♡", 300, 572);
    x.font = `500 26px ${FONT}`;
    x.fillStyle = "#a07c96";
    x.fillText(date.toLocaleDateString(undefined, { day: "numeric", month: "long", year: "numeric" }), 300, 620);
    x.font = `500 22px ${FONT}`;
    x.fillText(`📷 ${myName()}`, 300, 660);
    const dataUrl = pol.toDataURL("image/jpeg", 0.8);
    // flash + shutter sound
    this.flash.classList.remove("on");
    void this.flash.offsetWidth;
    this.flash.classList.add("on");
    audio.sfx("shutter");
    this.showPreview({ id: `${date.getTime().toString(36)}${Math.random().toString(36).slice(2, 6)}`, src: dataUrl, by: myName(), at: date.getTime() });
  }

  showPreview(item) {
    const { h, isGuest, toast, confetti } = this.ctx;
    this.previewImg.src = item.src;
    const actions = [];
    if (!isGuest) {
      actions.push(
        h("button", { class: "g3d-big-btn", type: "button", onclick: () => {
          this.addItem(item);
          this.preview.hidden = true;
          confetti?.();
          toast("pinned to our photo wall 📌");
        } }, "📌 pin it to our wall"),
        h("button", { class: "g3d-big-btn g3d-big-btn-soft", type: "button", onclick: () => {
          const a = document.createElement("a");
          a.href = item.src;
          a.download = `toto-dodo-${item.at}.jpg`;
          a.click();
        } }, "save to my device"),
      );
    } else actions.push(h("p", { class: "g3d-invite-note" }, "visitors can take photos but can't keep or post them ♡"));
    actions.push(h("button", { class: "g3d-big-btn g3d-big-btn-soft", type: "button", onclick: () => (this.preview.hidden = true) }, "retake"));
    this.previewActions.replaceChildren(...actions);
    this.preview.hidden = false;
  }

  openWall() {
    const { h, isGuest } = this.ctx;
    this.ctx.closeOthers?.();
    this.viewer.hidden = true;
    this.grid.hidden = false;
    this.grid.replaceChildren(
      ...(this.items.length
        ? this.items.map((it) => h("button", { class: "g3d-album-thumb", type: "button", onclick: () => this.showBig(it) }, h("img", { src: it.src, alt: `photo by ${it.by}`, loading: "lazy" })))
        : [h("p", { class: "g3d-invite-note" }, isGuest ? "no photos here yet ♡" : "no photos yet. use the 📷 camera or the tripod ⏱ ♡")]),
    );
    this.wallView.hidden = false;
    this.ctx.setControls(false);
  }
  showBig(it) {
    const { h, isGuest, toast } = this.ctx;
    this.grid.hidden = true;
    this.viewer.hidden = false;
    this.viewer.replaceChildren(
      h("img", { class: "g3d-gallery-img g3d-photo-img", src: it.src, alt: "" }),
      h("p", { class: "g3d-invite-note" }, `taken by ${it.by || "one of you"} · ${new Date(it.at).toLocaleDateString()}`),
      h("div", { class: "g3d-gallery-actions" },
        h("button", { class: "g3d-big-btn g3d-big-btn-soft", type: "button", onclick: () => this.openWall() }, "← all photos"),
        isGuest
          ? null
          : h("button", { class: "g3d-big-btn g3d-big-btn-soft", type: "button", onclick: () => {
              this.removeItem(it.id);
              toast("taken down ♡");
              this.openWall();
            } }, "take it down"),
      ),
    );
  }
  closeWall() {
    this.wallView.hidden = true;
    this.ctx.setControls(true);
  }

  isOpen() {
    return !this.wallView.hidden || !this.preview.hidden;
  }
  closeOverlays() {
    this.wallView.hidden = true;
    this.preview.hidden = true;
  }

  update(t) {
    this.updateHeart(t);
    this.checkMoved();
    // pinch or wheel zoom moves the slider too
    if (this.mode === "camera" && this.zoomMode() === "view" && this.ctx.controls && document.activeElement !== this.zoomEl) {
      const v = THREE.MathUtils.clamp((14 - this.ctx.controls.dist) / 10.8, 0, 1);
      if (Math.abs(v - this.zoomBy.view) > 0.01) {
        this.zoomBy.view = v;
        this.zoomEl.value = String(v);
      }
    }
    if (this.recLight) this.recLight.material.color.set(this.counting && Math.floor(t * 4) % 2 ? "#ff3b5c" : this.counting ? "#5a1020" : "#ff3b5c");
  }

  destroy() {
    window.removeEventListener("resize", this.onResize);
    for (const el of [this.camUI, this.flash, this.preview, this.wallView, this.countEl]) el.remove();
  }
}

const imgCache = new Map();
function loadImg(src) {
  if (!imgCache.has(src)) {
    imgCache.set(
      src,
      new Promise((res, rej) => {
        const img = new Image();
        img.onload = () => res(img);
        img.onerror = rej;
        img.src = src;
      }),
    );
  }
  return imgCache.get(src);
}

// the painted back of the photo wall: a pastel sky, clouds, hearts, a few painted
// polaroids and our names in the middle
function muralTex() {
  const c = document.createElement("canvas");
  c.width = 1024;
  c.height = 512;
  const x = c.getContext("2d");
  const sky = x.createLinearGradient(0, 0, 0, 512);
  sky.addColorStop(0, "#ffd6e7");
  sky.addColorStop(0.6, "#efdcff");
  sky.addColorStop(1, "#d9f0ff");
  x.fillStyle = sky;
  x.fillRect(0, 0, 1024, 512);
  // soft clouds
  x.fillStyle = "rgba(255,255,255,0.85)";
  for (const [cx, cy, s] of [[130, 90, 1], [870, 70, 1.2], [560, 40, 0.7], [300, 430, 0.8], [780, 440, 1]]) {
    for (const [dx, dy, r] of [[0, 0, 34], [36, -14, 30], [70, 0, 32], [34, 12, 30]]) {
      x.beginPath();
      x.arc(cx + dx * s, cy + dy * s, r * s, 0, Math.PI * 2);
      x.fill();
    }
  }
  // hearts and sparkles scattered about
  const heart = (hx, hy, sz, col, rot = 0) => {
    x.save();
    x.translate(hx, hy);
    x.rotate(rot);
    x.scale(sz / 20, sz / 20);
    x.fillStyle = col;
    x.beginPath();
    x.moveTo(0, 6);
    x.bezierCurveTo(-14, -4, -8, -16, 0, -8);
    x.bezierCurveTo(8, -16, 14, -4, 0, 6);
    x.fill();
    x.restore();
  };
  const cols = ["#ff8fb1", "#e2557f", "#b79be8", "#ffb3cf", "#8fd3f0"];
  for (let i = 0; i < 26; i++) heart(40 + ((i * 397) % 950), 40 + ((i * 211) % 440), 14 + (i % 4) * 7, cols[i % cols.length], ((i % 5) - 2) * 0.2);
  x.fillStyle = "#ffffff";
  for (let i = 0; i < 30; i++) {
    const sx = (i * 331) % 1024;
    const sy = (i * 157) % 512;
    x.beginPath();
    x.moveTo(sx, sy - 6);
    x.lineTo(sx + 2, sy - 2);
    x.lineTo(sx + 6, sy);
    x.lineTo(sx + 2, sy + 2);
    x.lineTo(sx, sy + 6);
    x.lineTo(sx - 2, sy + 2);
    x.lineTo(sx - 6, sy);
    x.lineTo(sx - 2, sy - 2);
    x.fill();
  }
  // painted polaroids, a little crooked
  const polaroid = (px, py, rot, a, b, doodle) => {
    x.save();
    x.translate(px, py);
    x.rotate(rot);
    x.shadowColor = "rgba(90, 50, 80, 0.25)";
    x.shadowBlur = 10;
    x.shadowOffsetY = 4;
    x.fillStyle = "#fffaf6";
    x.fillRect(-62, -70, 124, 146);
    x.shadowColor = "transparent";
    const g = x.createLinearGradient(0, -60, 0, 50);
    g.addColorStop(0, a);
    g.addColorStop(1, b);
    x.fillStyle = g;
    x.fillRect(-52, -60, 104, 104);
    x.font = `700 64px ${FONT}`;
    x.fillStyle = "rgba(255, 255, 255, 0.9)";
    x.textAlign = "center";
    x.textBaseline = "middle";
    x.fillText(doodle, 0, -8);
    // tape
    x.fillStyle = "rgba(255, 214, 231, 0.85)";
    x.fillRect(-22, -80, 44, 18);
    x.restore();
  };
  polaroid(150, 280, -0.12, "#ffd166", "#ff8fb1", "☀");
  polaroid(880, 270, 0.1, "#8fd3f0", "#b79be8", "☾");
  polaroid(745, 330, -0.06, "#9be0b0", "#8fd3f0", "✿");
  polaroid(285, 345, 0.08, "#ffb3cf", "#ffd6e7", "♡");
  // our names in the middle, in a big soft heart
  heart(512, 230, 260, "rgba(255, 255, 255, 0.75)");
  x.fillStyle = "#e2557f";
  x.textAlign = "center";
  x.textBaseline = "middle";
  x.font = `700 72px ${FONT}`;
  x.fillText("toto ♡ dodo", 512, 200);
  x.font = `600 26px ${FONT}`;
  x.fillStyle = "#7b5cd6";
  x.fillText("˚₊‧ every photo round the front is a little forever ‧₊˚", 512, 262);
  // a row of painted flowers along the bottom
  for (let i = 0; i < 22; i++) {
    const fx = 24 + i * 47;
    const fy = 488 - (i % 3) * 6;
    x.strokeStyle = "#7fc98a";
    x.lineWidth = 4;
    x.beginPath();
    x.moveTo(fx, 512);
    x.lineTo(fx, fy);
    x.stroke();
    x.fillStyle = cols[i % cols.length];
    for (let k = 0; k < 5; k++) {
      x.beginPath();
      x.arc(fx + Math.cos((k / 5) * Math.PI * 2) * 7, fy + Math.sin((k / 5) * Math.PI * 2) * 7, 6, 0, Math.PI * 2);
      x.fill();
    }
    x.fillStyle = "#ffd166";
    x.beginPath();
    x.arc(fx, fy, 4, 0, Math.PI * 2);
    x.fill();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}
