// The balloon ride: a hot-air balloon that waits at its little station until someone hops
// in, leaves ten seconds later, floats once round the whole island and comes gently back
// down. A trip is just the moment it started (shared over the network by whoever is aboard),
// so it is in the same place in the sky for both of us. Left empty mid-trip (everyone
// jumped out with a parachute), it glides straight home and lands.
import * as THREE from "three";

const BOARD = 10; // it leaves this long after the first person gets in
const LIFT = 12; // rising straight up off the station
const TOUR = 133; // the loop round the island
const LAND = 15; // coming down
const TRIP = BOARD + LIFT + TOUR + LAND;
const ALT = 30; // how high it floats on the way round
const HOME_SPEED = 7; // gliding home empty

const ease = (u) => (u < 0.5 ? 2 * u * u : 1 - (-2 * u + 2) ** 2 / 2);
// a smooth start and stop with an even pace in between (no long crawl at either end)
const cruise = (u, e = 0.08) => {
  const v = 1 / (1 - e);
  if (u < e) return (v * u * u) / (2 * e);
  if (u > 1 - e) return 1 - (v * (1 - u) ** 2) / (2 * e);
  return v * (u - e / 2);
};
// a smooth clock in shared (wall-clock) seconds: Date.now() alone ticks in coarse steps on
// some browsers, which made the balloon stutter along; performance.now() is smooth, so it
// runs the clock and Date.now() only sets (and now and then re-syncs) where it starts
let base = Date.now() / 1000 - performance.now() / 1000;
let synced = performance.now();
export const clock = () => {
  const p = performance.now();
  if (p - synced > 30000) {
    // ease toward the wall clock (e.g. after the device slept) without a visible jump
    const drift = Date.now() / 1000 - p / 1000 - base;
    base += Math.abs(drift) > 5 ? drift : drift * 0.2;
    synced = p;
  }
  return base + p / 1000;
};

// the way round: out from the station, a wide loop over the island at gently varying heights
// (higher over the middle, lower over the shore), and back over the station
// dock: which way the basket faces at the station (its seats look out to the steps)
export function makeRoute(station, rooms, dock = 0) {
  const s = new THREE.Vector3(station.x, ALT, station.z);
  const a0 = Math.atan2(station.x, station.z);
  const pts = [s.clone()];
  const N = 11;
  for (let k = 1; k <= N; k++) {
    const a = a0 + (k / (N + 1)) * Math.PI * 2;
    const r = k % 3 === 0 ? 26 : k % 3 === 1 ? 50 : 40;
    pts.push(new THREE.Vector3(Math.sin(a) * r, ALT + (k % 2 ? 6 : 3) + (r < 30 ? 4 : 0), Math.cos(a) * r));
  }
  pts.push(s.clone());
  const curve = new THREE.CatmullRomCurve3(pts, false, "centripetal", 0.5);
  curve.arcLengthDivisions = 2000; // an even speed all the way round
  // rooms: what it floats over (asked when needed: not every place is built yet)
  return { curve, station: new THREE.Vector3(station.x, station.y, station.z), rooms, dock };
}

// where the basket is at time t (its floor's middle), which way it's heading, how hard the
// burner is going, and the stage it's at. trip: null (waiting at the station), or { t0 }
// and, gliding home empty, ret: { t, from, dur }
const _a = new THREE.Vector3();
const _b = new THREE.Vector3();
export function balloonPose(route, trip, t = clock(), out = {}) {
  out.pos = out.pos || new THREE.Vector3();
  const st = route.station;
  out.heading = out.heading ?? 0;
  const sway = Math.sin(t * 0.7) * 0.04;
  const docked = (until) => {
    out.stage = "docked";
    out.heading = route.dock; // (always the same way round at the station, whichever way it came home)
    out.pos.copy(st);
    out.pos.y += Math.sin(t * 1.3) * 0.015;
    out.burner = until != null && until < 4 ? 1 : 0.15;
    out.until = until;
    out.tilt = 0;
    return out;
  };
  const landing = (v, until) => {
    const u = ease(v);
    out.stage = "land";
    out.heading = route.dock;
    out.pos.set(st.x, ALT + (st.y - ALT) * u, st.z);
    out.burner = 0.2;
    out.until = until;
    out.tilt = sway * (1 - u);
    return out;
  };
  if (!trip) return docked(null);
  if (trip.ret) {
    // home: straight back over the station, then down
    const r = trip.ret;
    const k = t - r.t;
    if (k < r.dur) {
      const u = ease(k / r.dur);
      out.pos.set(r.from.x + (st.x - r.from.x) * u, r.from.y + (ALT - r.from.y) * u, r.from.z + (st.z - r.from.z) * u);
      if (Math.hypot(st.x - r.from.x, st.z - r.from.z) > 1) out.heading = Math.atan2(st.x - r.from.x, st.z - r.from.z);
      out.stage = "home";
      out.burner = 0.3;
      out.until = r.dur - k + LAND;
      out.tilt = sway;
      return out;
    }
    if (k < r.dur + LAND) return landing((k - r.dur) / LAND, r.dur + LAND - k);
    return docked(null);
  }
  const e = t - trip.t0;
  if (e < BOARD) return docked(BOARD - e);
  if (e < BOARD + LIFT) {
    const u = ease((e - BOARD) / LIFT);
    out.stage = "lift";
    out.pos.set(st.x, st.y + (ALT - st.y) * u, st.z);
    out.burner = 1;
    out.until = TRIP - e;
    out.tilt = sway * u; // (the sway eases in as it rises, not all at once)
    return out;
  }
  if (e < BOARD + LIFT + TOUR) {
    const u = cruise((e - BOARD - LIFT) / TOUR);
    route.curve.getPointAt(u, out.pos);
    route.curve.getPointAt(Math.min(1, u + 0.012), _a);
    route.curve.getPointAt(Math.max(0, u - 0.012), _b);
    if (_a.distanceToSquared(_b) > 1e-4) out.heading = Math.atan2(_a.x - _b.x, _a.z - _b.z);
    // a gentle bob, faded in and out so it meets the lift and the landing smoothly
    out.pos.y += Math.sin(t * 0.5) * 0.4 * Math.min(1, u * 8, (1 - u) * 8);
    out.stage = "tour";
    out.burner = _a.y > _b.y + 0.02 ? 0.8 : 0.25 + Math.max(0, Math.sin(t * 0.9)) * 0.3;
    out.until = TRIP - e;
    out.tilt = sway;
    return out;
  }
  if (e < TRIP) return landing((e - BOARD - LIFT - TOUR) / LAND, TRIP - e);
  return docked(null);
}
// a trip that has run its course (landed, or home again)
export function tripOver(trip, t = clock()) {
  if (!trip) return false;
  if (trip.ret) return t - trip.ret.t > trip.ret.dur + LAND;
  return t - trip.t0 >= TRIP;
}
// left empty mid-air: glide home from wherever it is now
export function sendHome(trip, pose, route, t = clock()) {
  const from = pose.pos.clone();
  const d = Math.hypot(route.station.x - from.x, route.station.z - from.z);
  trip.ret = { t, from, dur: Math.max(6, d / HOME_SPEED) };
}

// the two seats in the basket: on either side, facing out over the rim
const SEATS = [-0.34, 0.34];
export function seatPose(pose, i, out = new THREE.Vector3()) {
  const x = SEATS[i] || 0;
  const c = Math.cos(pose.heading), s = Math.sin(pose.heading);
  return out.set(pose.pos.x + x * c, pose.pos.y, pose.pos.z - x * s);
}

// the name of the place it's floating over right now
export function over(route, pose) {
  let best = null;
  let bd = 14;
  for (const r of route.rooms()) {
    if (r.def.id === "plaza" || r.def.id === "balloon") continue;
    const d = Math.hypot(r.def.pos.x - pose.pos.x, r.def.pos.z - pose.pos.z);
    if (d < bd) {
      bd = d;
      best = r.def.name;
    }
  }
  return best;
}
