const RETIRED_HAIR = { short: "messy", buzz: "wolfcut", quiff: "wolfcut", sidepart: "wolfcut", curtains: "flow", fade: "wolfcut", undercut: "wolfcut", cornrows: "twists" };
export function loadAvatar() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || "null");
    if (saved && typeof saved === "object") return { ...DEFAULT_AVATAR, ...saved, hair: RETIRED_HAIR[saved.hair] || saved.hair || DEFAULT_AVATAR.hair };
  } catch {}
  return { ...DEFAULT_AVATAR };
}

export function saveAvatar(config) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
  } catch {}
}

