const matCache = new Map();
function mat(color, extra = {}) {
  const key = color + JSON.stringify(extra);
  if (!matCache.has(key)) {
    matCache.set(
      key,
      new THREE.MeshStandardMaterial({ color, flatShading: true, roughness: 0.82, metalness: 0, ...extra }),
    );
  }
  return matCache.get(key);
}

// a checked flannel pattern in the picked colour
const plaidCache = new Map();
function plaidMat(color) {
  if (!plaidCache.has(color)) {
    const cv = document.createElement("canvas");
    cv.width = cv.height = 64;
    const x = cv.getContext("2d");
    x.fillStyle = color;
    x.fillRect(0, 0, 64, 64);
    x.fillStyle = shadeHex(color, 0.45);
    x.globalAlpha = 0.6;
    x.fillRect(0, 18, 64, 16);
    x.fillRect(18, 0, 16, 64);
    x.globalAlpha = 0.85;
    x.fillStyle = "#fff7f2";
    x.fillRect(0, 50, 64, 3);
    x.fillRect(50, 0, 3, 64);
    x.globalAlpha = 0.4;
    x.fillStyle = shadeHex(color, 0.3);
    x.fillRect(0, 4, 64, 4);
    x.fillRect(4, 0, 4, 64);
    const tex = new THREE.CanvasTexture(cv);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(3, 2);
    tex.colorSpace = THREE.SRGBColorSpace;
    plaidCache.set(color, new THREE.MeshStandardMaterial({ map: tex, flatShading: true, roughness: 0.9, metalness: 0 }));
  }
  return plaidCache.get(color);
}

const twoCache = new Map();
function twoSided(m) {
  if (!twoCache.has(m)) {
    const c = m.clone();
    c.side = THREE.DoubleSide;
    twoCache.set(m, c);
  }
  return twoCache.get(m);
}

const capsule = (r, len) => new THREE.CapsuleGeometry(r, len, 2, 7);

function mesh(geo, material, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, material);
  m.position.set(x, y, z);
  m.castShadow = true;
  return m;
}

// ---- hair builders --------------------------------------------------------
function hairCap(r, m, coverage = 0.56) {
  const cap = mesh(new THREE.SphereGeometry(r * 1.07, 14, 9, 0, Math.PI * 2, 0, Math.PI * coverage), m);
  cap.rotation.x = -0.32;
  cap.position.y = r * 0.04;
  cap.scale.x = 1.04;
  return cap;
}

// a point on (or off) the head: t from the crown down, az round from the face (+z)
function onHead(t, az, R) {
  return [Math.sin(t) * Math.sin(az) * R * 1.04, Math.cos(t) * R, Math.sin(t) * Math.cos(az) * R];
}
// a strand that follows the head's curve from t0 down to t1, flaring out from R0 to R1
function arcLock(g, m, r, az, t0, t1, R0, R1, rad, segs = 3) {
  segs = Math.max(segs, Math.ceil(Math.abs(t1 - t0) / 0.3));
  let prev = onHead(t0, az, R0);
  for (let i = 1; i <= segs; i++) {
    const k = i / segs;
    const next = onHead(t0 + (t1 - t0) * k, az, R0 + (R1 - R0) * k * k);
    lock(g, m, r, prev, next, rad * (1 - k * 0.35));
    prev = next;
  }
  return prev;
}
// a pointed tip at the end of a strand, pointing down and out
function tipAt(g, m, r, p, az, len, rad, out = 0.5) {
  const dir = new THREE.Vector3(Math.sin(az) * out, -1, Math.cos(az) * out).normalize();
  const c = mesh(new THREE.ConeGeometry(rad * r, len * r, 5), m);
  c.position.set(...p).multiplyScalar(r).addScaledVector(dir, len * r * 0.4);
  c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  c.scale.set(1.4, 1, 0.55);
  g.add(c);
}
// a flat pointed spike from p (head radii) along dir, flattened so it lies with the head
function spike(g, m, r, p, dir, len, rad) {
  const P = new THREE.Vector3(...p);
  const d = dir.clone().normalize();
  const out = P.clone().addScaledVector(d, -P.dot(d));
  if (out.lengthSq() < 1e-4) out.set(0, 0, 1);
  out.normalize();
  const side = new THREE.Vector3().crossVectors(d, out);
  const c = mesh(new THREE.ConeGeometry(rad * r, len * r, 5), m);
  c.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(side, d, out));
  c.position.copy(P).multiplyScalar(r).addScaledVector(d, len * r * 0.42);
  c.scale.set(1.35, 1, 0.5);
  g.add(c);
  return c;
}
// a cap whose front edge sits high on the forehead
function highCap(r, m, size = 1.07, coverage = 0.52) {
  const cap = mesh(new THREE.SphereGeometry(r * Math.max(size, 1.05), 16, 10, 0, Math.PI * 2, 0, Math.PI * coverage), m);
  cap.rotation.x = -0.45;
  cap.position.y = r * 0.02;
  cap.scale.x = 1.04;
  return cap;
}
// a strand of hair from one point to another (in head radii)
// flat: a wide ribbon lying on the head instead of a round tube
function lock(g, m, r, from, to, rad, flat = true) {
  const A = new THREE.Vector3(...from).multiplyScalar(r);
  const B = new THREE.Vector3(...to).multiplyScalar(r);
  const d = B.clone().sub(A);
  const c = mesh(new THREE.CapsuleGeometry(rad * r, d.length(), 2, 6), m);
  c.position.copy(A).add(B).multiplyScalar(0.5);
  d.normalize();
  if (flat) {
    const out = c.position.clone().addScaledVector(d, -c.position.dot(d)).normalize();
    const side = new THREE.Vector3().crossVectors(d, out);
    c.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(side, d, out));
    c.scale.set(1.5, 1, 0.5);
  } else c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d);
  g.add(c);
  return c;
}

const HAIR = {
  bald() {},
  bob(g, r, m) {
    const open = Math.PI * 2 * 0.3;
    const shell = mesh(
      new THREE.SphereGeometry(r * 1.13, 10, 7, Math.PI / 2 + open / 2, Math.PI * 2 - open, 0, Math.PI * 0.7),
      m,
    );
    shell.position.y = r * 0.02;
    shell.material = twoSided(m);
    g.add(shell, hairCap(r, m, 0.5));
    // a straight fringe
    const fringe = mesh(new THREE.SphereGeometry(r * 1.1, 10, 4, Math.PI * 0.2, Math.PI * 0.6, Math.PI * 0.18, Math.PI * 0.22), twoSided(m));
    g.add(fringe);
  },
  long(g, r, m) {
    g.add(hairCap(r, m));
    const curtain = mesh(new THREE.CylinderGeometry(r * 1.06, r * 1.22, r * 1.9, 14, 1, true, Math.PI * 0.42, Math.PI * 1.16), twoSided(m), 0, -r * 0.6, -r * 0.05);
    g.add(curtain);
    // soft wavy ends
    for (let i = 0; i < 7; i++) {
      const a = Math.PI * 0.45 + (i / 6) * Math.PI * 1.1;
      g.add(mesh(new THREE.IcosahedronGeometry(r * 0.26, 1), m, Math.sin(a) * r * 1.1, -r * 1.5, Math.cos(a) * r * 1.1 - r * 0.05));
    }
    for (const s of [-1, 1]) {
      const lock = mesh(new THREE.CapsuleGeometry(r * 0.17, r * 1.0, 2, 8), m, s * r * 0.95, -r * 0.55, r * 0.22);
      lock.rotation.z = s * 0.06;
      g.add(lock);
    }
  },
  bun(g, r, m) {
    g.add(hairCap(r, m));
    g.add(mesh(new THREE.IcosahedronGeometry(r * 0.42, 1), m, 0, r * 0.92, -r * 0.42));
  },
  ponytail(g, r, m) {
    g.add(hairCap(r, m));
    // a band high at the back, then a tail that swings out and hangs down
    const tie = mesh(new THREE.TorusGeometry(r * 0.17, r * 0.06, 5, 10), mat(shadeHex("#" + m.color.getHexString(), 0.6)), 0, r * 0.5, -r * 1.02);
    tie.rotation.x = -0.6;
    g.add(tie, mesh(new THREE.IcosahedronGeometry(r * 0.22, 1), m, 0, r * 0.5, -r * 1.08));
    const tail = mesh(new THREE.CapsuleGeometry(r * 0.2, r * 1.0, 3, 8), m, 0, -r * 0.15, -r * 1.3);
    tail.rotation.x = 0.35;
    const tip = mesh(new THREE.ConeGeometry(r * 0.2, r * 0.4, 7), m, 0, -r * 0.82, -r * 1.48);
    tip.rotation.x = Math.PI + 0.35;
    g.add(tail, tip);
  },
  // a full head of curls: curls everywhere the hair grows (no smooth cap showing), a row
  // of small ones along the hairline, more volume on top, a few loose ringlets by the ears
  curly(g, r, m) {
    const base = shadeHex("#" + m.color.getHexString(), 0.78);
    g.add(highCap(r, mat(base), 1.05, 0.5));
    const geos = [0.21, 0.18, 0.15].map((k) => new THREE.IcosahedronGeometry(r * k, 1));
    const light = mat(shadeHex("#" + m.color.getHexString(), 1.14));
    const deep = mat(base);
    const tilt = new THREE.Euler(0.45, 0, 0); // into the cap's own frame
    const n = 150;
    for (let i = 0; i < n; i++) {
      const y = 1 - (i / (n - 1)) * 1.7;
      const rad = Math.sqrt(Math.max(0, 1 - y * y));
      const a = i * 2.399;
      const v = new THREE.Vector3(Math.cos(a) * rad, y, Math.sin(a) * rad);
      // where the hair grows: inside the cap, and down to the nape at the back
      const polar = Math.acos(v.clone().applyEuler(tilt).y);
      const back = v.z < -0.15;
      if (polar > Math.PI * (back ? 0.66 : 0.52)) continue;
      const top = Math.max(0, v.y);
      const R = 1.08 + top * 0.12 + ((i * 7) % 5) * 0.012;
      const jitter = ((i * 13) % 7) / 7 - 0.5;
      const curl = mesh(geos[i % 3], i % 5 === 0 ? light : i % 7 === 0 ? deep : m, v.x * r * R * 1.04, v.y * r * R + r * 0.03, v.z * r * R);
      curl.rotation.set(i, i * 0.7, jitter);
      g.add(curl);
    }
    // the hairline: small curls along the cap's front edge
    for (let k = 0; k <= 10; k++) {
      const az = -1.35 + (k / 10) * 2.7;
      const v = new THREE.Vector3(Math.sin(az), 0, Math.cos(az)).multiplyScalar(Math.sin(Math.PI * 0.5)).setY(Math.cos(Math.PI * 0.5));
      v.applyEuler(new THREE.Euler(-0.45, 0, 0));
      const c = mesh(geos[2], k % 3 ? m : light, v.x * r * 1.1 * 1.04, v.y * r * 1.1 + r * 0.03, v.z * r * 1.1);
      c.rotation.set(k, k * 1.3, 0);
      g.add(c);
    }
    // loose ringlets behind the ears
    for (const [az, k] of [[1.55, 3], [-1.55, 3], [2.3, 3], [-2.3, 3]]) {
      const p = new THREE.Vector3(...onHead(0.55 * Math.PI, az, 1.16));
      for (let j = 0; j < k; j++) g.add(mesh(geos[2], j % 2 ? light : m, p.x * r + Math.sin(j * 2.1) * r * 0.03, p.y * r - j * r * 0.17, p.z * r));
    }
  },
  messy(g, r, m) {
    g.add(hairCap(r, m));
    const geo = new THREE.IcosahedronGeometry(r * 0.24, 0);
    const spots = [[0, 1, 0.2], [0.4, 0.9, 0.35], [-0.4, 0.9, 0.3], [0.2, 0.95, -0.25], [-0.25, 0.92, -0.2], [0.55, 0.7, 0.1], [-0.55, 0.72, 0.05], [0, 0.8, 0.6]];
    for (const [x, y, z] of spots) {
      const c = mesh(geo, m, x * r, y * r, z * r);
      c.rotation.set(x * 2, y * 3, z * 2);
      g.add(c);
    }
  },
  mohawk(g, r, m) {
    // shaved sides: a thin shadow of hair, close to the head
    g.add(highCap(r, mat(shadeHex("#" + m.color.getHexString(), 0.5)), 1.012, 0.52));
    // a strip down the middle that the crest grows out of
    for (let i = 0; i < 4; i++) {
      const t0 = -0.55 + i * 0.6;
      lock(g, m, r, [0, Math.cos(t0) * 1.03, Math.sin(-t0) * 1.03], [0, Math.cos(t0 + 0.6) * 1.03, -Math.sin(t0 + 0.6) * 1.03], 0.11, false);
    }
    // the crest: tall flat spikes swept back, tallest just behind the forehead
    const n = 11;
    for (let i = 0; i < n; i++) {
      const t = -0.62 + (i / (n - 1)) * 2.3; // from above the forehead over to the back
      const p = new THREE.Vector3(0, Math.cos(t), -Math.sin(t));
      const h = 1.05 - i * 0.055;
      const dir = p.clone().add(new THREE.Vector3(0, 0.35, -0.55)).normalize();
      const c = mesh(new THREE.ConeGeometry(r * 0.26, r * h, 6), m);
      c.position.copy(p).multiplyScalar(r * 1.04).addScaledVector(dir, r * h * 0.42);
      c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
      c.scale.set(0.38, 1, 1.35);
      g.add(c);
    }
  },
  manbun(g, r, m) {
    g.add(highCap(r, m, 1.07, 0.54));
    const tie = mesh(new THREE.TorusGeometry(r * 0.2, r * 0.06, 5, 10), mat("#2b2633"), 0, r * 0.92, -r * 0.66);
    tie.rotation.x = -0.9;
    g.add(tie, mesh(new THREE.IcosahedronGeometry(r * 0.36, 1), m, 0, r * 1.08, -r * 0.82));
    // a couple of loose strands at the front
    for (const s of [-1, 1]) lock(g, m, r, [s * 0.35, 0.82, 0.72], [s * 0.62, 0.3, 0.84], 0.07, false);
  },
  // chin-length waves from a middle part, tucked back off the face, the ends flicking out
  flow(g, r, m) {
    g.add(highCap(r, m, 1.06, 0.55));
    const light = mat(shadeHex("#" + m.color.getHexString(), 1.15));
    const n = 16;
    for (let i = 0; i < n; i++) {
      const az = (i / n) * Math.PI * 2 + Math.PI / n;
      const front = Math.cos(az);
      if (front > 0.8) continue; // the face stays open
      const end = arcLock(g, i % 3 === 0 ? light : m, r, az, 0.1, (front > 0.3 ? 0.62 : 0.72) * Math.PI, 1.07, 1.26, 0.24);
      tipAt(g, m, r, end, az, 0.3, 0.16, 1.6);
    }
    // the middle part: two thick sweeps off the forehead to the sides
    for (const s of [-1, 1]) {
      const a = [s * 0.06, 1.02, 0.42];
      const mid = new THREE.Vector3(s * 0.55, 0.72, 0.68).normalize().multiplyScalar(1.13).toArray();
      const end = new THREE.Vector3(s * 0.95, 0.2, 0.35).normalize().multiplyScalar(1.18).toArray();
      lock(g, m, r, a, mid, 0.24);
      lock(g, m, r, mid, end, 0.21);
      tipAt(g, m, r, end, s * 1.4, 0.3, 0.15, 0.9);
    }
  },
  afro(g, r, m) {
    g.add(highCap(r, m, 1.07, 0.55));
    // big round fluffy clumps all round, the face left open
    const geo = new THREE.IcosahedronGeometry(r * 0.44, 1);
    const n = 46;
    for (let i = 0; i < n; i++) {
      const y = 1 - (i / (n - 1)) * 1.55;
      const rad = Math.sqrt(Math.max(0, 1 - y * y));
      const a = i * 2.399;
      const v = new THREE.Vector3(Math.cos(a) * rad, y, Math.sin(a) * rad);
      const p = v.multiplyScalar(r * 1.12).add(new THREE.Vector3(0, r * 0.32, -r * 0.12));
      if (p.z > r * 0.2 && p.y < r * 0.78) continue;
      if (p.y < -r * 0.25) continue;
      if (p.y < r * 0.1 && p.z > -r * 0.3) continue; // nothing under the chin
      g.add(mesh(geo, m, p.x, p.y, p.z));
    }
  },
  twists(g, r, m) {
    g.add(highCap(r, mat(shadeHex("#" + m.color.getHexString(), 0.8)), 1.03, 0.55));
    const bead = new THREE.IcosahedronGeometry(r * 0.11, 0);
    const n = 120;
    const down = new THREE.Vector3(0, -1, 0);
    for (let i = 0; i < n; i++) {
      const y = 1 - (i / (n - 1)) * 1.3;
      const rad = Math.sqrt(Math.max(0, 1 - y * y));
      const a = i * 2.399;
      const v = new THREE.Vector3(Math.cos(a) * rad, y, Math.sin(a) * rad);
      if (v.z > 0.3 && v.y < 0.42) continue; // the face
      if (v.y < -0.3) continue;
      // standing up on top, falling down the sides; the front ones lean up off the forehead
      const dir = v.clone().multiplyScalar(0.75).addScaledVector(down, v.z > 0.3 ? -0.3 : Math.max(0, 0.85 - v.y) * 0.9).normalize();
      const len = 3 + (i % 3);
      for (let k = 0; k < len; k++) {
        const b = mesh(bead, m);
        b.position.copy(v).multiplyScalar(r * 1.02).addScaledVector(dir, r * (0.04 + k * 0.13));
        b.rotation.set(k * 0.8 + i, k * 1.3, 0);
        b.scale.setScalar(1 - k * 0.08);
        g.add(b);
      }
    }
  },
  // a layered shag: choppy layers round the face, flicking out at the neck, messy on top
  wolfcut(g, r, m) {
    g.add(highCap(r, m, 1.05, 0.54));
    const dark = mat(shadeHex("#" + m.color.getHexString(), 0.82));
    const n = 18;
    for (let i = 0; i < n; i++) {
      const az = (i / n) * Math.PI * 2;
      const front = Math.cos(az); // 1 at the face
      const jag = (i % 3) * 0.05;
      if (front > 0.72) {
        // choppy bangs down to the brows
        const end = arcLock(g, m, r, az, 0.12, 0.36 * Math.PI + jag, 1.07, 1.13, 0.15, 2);
        tipAt(g, m, r, end, az, 0.26, 0.12, 0.35);
      } else if (front > 0.25) {
        // longer bits framing the face, to the cheekbones
        const end = arcLock(g, m, r, az, 0.12, 0.55 * Math.PI + jag, 1.07, 1.2, 0.17);
        tipAt(g, m, r, end, az, 0.32, 0.13, 0.7);
      } else {
        // the mullet-ish back: long layers flicking out at the neck
        const end = arcLock(g, m, r, az, 0.12, 0.74 * Math.PI + jag, 1.07, 1.32, 0.19);
        tipAt(g, m, r, end, az, 0.38, 0.14, 1.1);
        // a shorter layer on top of it for volume
        arcLock(g, i % 2 ? dark : m, r, az + 0.17, 0.2, 0.5 * Math.PI, 1.1, 1.22, 0.16, 2);
      }
    }
    // tousled crown
    const tuft = new THREE.ConeGeometry(r * 0.17, r * 0.4, 5);
    for (const [t, az] of [[0.25, 0.4], [0.3, -0.5], [0.35, 2.6], [0.3, -2.4], [0.15, 1.6], [0.2, -1.4]]) {
      const p = new THREE.Vector3(...onHead(t, az, 1.08));
      const c = mesh(tuft, m);
      c.position.copy(p).multiplyScalar(r);
      c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), p.clone().normalize().add(new THREE.Vector3(Math.sin(az), 0.2, Math.cos(az)).multiplyScalar(0.6)).normalize());
      c.scale.set(1.3, 1, 0.6);
      g.add(c);
    }
  },
  // a long swept fringe across the face, over one eye, and choppy layers down to the neck
  emo(g, r, m) {
    g.add(highCap(r, m, 1.05, 0.55));
    // sides and back: straight-ish layers to the neck, pointed ends
    const n = 16;
    for (let i = 0; i < n; i++) {
      const az = (i / n) * Math.PI * 2;
      if (Math.cos(az) > 0.35) continue;
      const end = arcLock(g, m, r, az, 0.12, 0.66 * Math.PI + (i % 2) * 0.08, 1.07, 1.16, 0.18);
      tipAt(g, m, r, end, az, 0.34, 0.13, 0.25);
    }
    // crown spikes at the back
    const sp = new THREE.ConeGeometry(r * 0.16, r * 0.42, 5);
    for (const az of [2.7, 3.14, 3.6]) {
      const p = new THREE.Vector3(...onHead(0.55, az, 1.06));
      const c = mesh(sp, m);
      c.position.copy(p).multiplyScalar(r);
      c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), p.clone().normalize().add(new THREE.Vector3(0, 0.5, 0)).normalize());
      c.scale.set(1.2, 1, 0.5);
      g.add(c);
    }
    // the fringe: several layered sweeps from the part, across the forehead and down over one eye
    for (const [ax, sx, ex, ey, rad] of [[-0.55, 0.05, 0.42, 0.02, 0.2], [-0.45, 0.2, 0.55, 0.2, 0.19], [-0.6, -0.1, 0.25, -0.05, 0.17], [-0.35, 0.35, 0.68, 0.4, 0.16]]) {
      const a = [ax, 0.95, 0.45];
      const mid = new THREE.Vector3(sx, 0.7, 0.75).normalize().multiplyScalar(1.13).toArray();
      const end = new THREE.Vector3(ex, ey, 0.92).normalize().multiplyScalar(1.1).toArray();
      lock(g, m, r, a, mid, rad);
      lock(g, m, r, mid, end, rad * 0.8);
      tipAt(g, m, r, end, 0.6, 0.28, rad * 0.6, 0.6);
    }
  },
  // short and soft, a side-swept fringe
  pixie(g, r, m) {
    g.add(highCap(r, m, 1.08, 0.56));
    lock(g, m, r, [0.35, 1.05, 0.5], [-0.2, 0.68, 0.9], 0.22);
    lock(g, m, r, [-0.2, 0.68, 0.9], [-0.7, 0.42, 0.72], 0.17);
    for (const s of [-1, 1]) lock(g, m, r, [s * 1.0, 0.35, 0.42], [s * 1.02, -0.12, 0.48], 0.1);
  },
  // long and straight, blunt bangs and front locks (hime cut)
  hime(g, r, m) {
    g.add(hairCap(r, m));
    const curtain = mesh(new THREE.CylinderGeometry(r * 1.07, r * 1.12, r * 2.0, 16, 1, true, Math.PI * 0.4, Math.PI * 1.2), twoSided(m), 0, -r * 0.65, -r * 0.04);
    g.add(curtain);
    const fringe = mesh(new THREE.CylinderGeometry(r * 1.06, r * 1.1, r * 0.42, 16, 1, true, -Math.PI * 0.32, Math.PI * 0.64), twoSided(m), 0, r * 0.42, 0);
    g.add(fringe);
    for (const s of [-1, 1]) {
      const side = mesh(new THREE.BoxGeometry(r * 0.22, r * 1.05, r * 0.2), m, s * r * 0.86, -r * 0.2, r * 0.48);
      side.rotation.y = s * 0.5;
      g.add(side);
    }
  },
  pigtails(g, r, m) {
    g.add(hairCap(r, m));
    const tieM = mat(shadeHex("#" + m.color.getHexString(), 0.55));
    for (const s of [-1, 1]) {
      const tie = mesh(new THREE.TorusGeometry(r * 0.13, r * 0.05, 5, 10), tieM, s * r * 0.98, r * 0.1, -r * 0.35);
      tie.rotation.y = Math.PI / 2;
      g.add(tie, mesh(new THREE.IcosahedronGeometry(r * 0.18, 1), m, s * r * 1.05, r * 0.1, -r * 0.35));
      lock(g, m, r, [s * 1.15, 0.0, -0.38], [s * 1.28, -0.85, -0.3], 0.19, false);
      const tip = mesh(new THREE.ConeGeometry(r * 0.19, r * 0.4, 7), m, s * r * 1.3, -r * 1.25, -r * 0.3);
      tip.rotation.z = Math.PI;
      g.add(tip);
    }
  },
  braid(g, r, m) {
    g.add(hairCap(r, m));
    // one thick plait down the back
    const knot = new THREE.IcosahedronGeometry(r * 0.21, 1);
    for (let i = 0; i < 7; i++) {
      const k = mesh(knot, m, (i % 2 ? 1 : -1) * r * 0.05, r * (0.15 - i * 0.24), -r * (1.05 + i * 0.03));
      k.scale.setScalar(1 - i * 0.06);
      g.add(k);
    }
    const tie = mesh(new THREE.TorusGeometry(r * 0.1, r * 0.04, 5, 10), mat(shadeHex("#" + m.color.getHexString(), 0.55)), 0, -r * 1.55, -r * 1.25);
    tie.rotation.x = Math.PI / 2;
    const end = mesh(new THREE.ConeGeometry(r * 0.13, r * 0.32, 7), m, 0, -r * 1.72, -r * 1.26);
    end.rotation.x = Math.PI;
    g.add(tie, end);
  },
  spacebuns(g, r, m) {
    g.add(hairCap(r, m));
    for (const s of [-1, 1]) {
      g.add(mesh(new THREE.IcosahedronGeometry(r * 0.34, 1), m, s * r * 0.58, r * 0.9, -r * 0.12));
      const tie = mesh(new THREE.TorusGeometry(r * 0.22, r * 0.05, 5, 10), mat(shadeHex("#" + m.color.getHexString(), 0.55)), s * r * 0.5, r * 0.74, -r * 0.1);
      tie.rotation.set(Math.PI / 2, s * 0.6, 0);
      g.add(tie);
    }
  },
  // big swept anime spikes all round, a few falling over the forehead
  spiky(g, r, m) {
    g.add(highCap(r, m, 1.06, 0.56));
    const up = new THREE.Vector3(0, 1, 0);
    // round the sides and back: spikes pointing out, back and a little up
    for (let i = 0; i < 12; i++) {
      const az = Math.PI * 0.42 + (i / 11) * Math.PI * 1.16;
      const p = onHead(0.38 * Math.PI + (i % 2) * 0.1, az, 1.0);
      const out = new THREE.Vector3(Math.sin(az) * 0.8, 0.35 + (i % 2) * 0.2, Math.cos(az) - 0.6);
      spike(g, m, r, p, out, 0.6 + (i % 3) * 0.1, 0.2);
    }
    // the crown: tall spikes swept up and back
    for (const [t, az, len] of [[0.12, 0, 0.85], [0.3, 0.9, 0.75], [0.3, -0.9, 0.75], [0.35, 2.2, 0.7], [0.35, -2.2, 0.7], [0.4, 3.14, 0.7], [0.2, 1.8, 0.65], [0.2, -1.8, 0.65]]) {
      const p = onHead(t, az, 1.0);
      const d = new THREE.Vector3(...p).normalize().add(new THREE.Vector3(Math.sin(az) * 0.3, 0.5, -0.55)).normalize();
      spike(g, m, r, p, d, len, 0.23);
    }
    // bangs: spikes falling forward over the forehead
    for (const [az, len] of [[-0.45, 0.45], [0, 0.55], [0.45, 0.45], [0.85, 0.4], [-0.85, 0.4]]) {
      const p = onHead(0.3 * Math.PI, az, 1.02);
      spike(g, m, r, p, new THREE.Vector3(Math.sin(az) * 0.4, -1, 0.55), len, 0.17);
    }
  },
};

// ---- accessory builders ---------------------------------------------------
// the arm of a pair of glasses: from the frame's outer edge round to the side of the head,
// then straight back to the ear, always just outside the head
function armTo(head, m, r, s, w) {
  const hinge = mesh(new THREE.BoxGeometry(w * r, w * r, r * 0.58), m, s * r * 0.78, r * 0.06, r * 0.845);
  hinge.rotation.y = Math.atan2(s * 0.52, -0.25);
  const arm = mesh(new THREE.BoxGeometry(w * r, w * r, r * 0.8), m, s * r * 1.07, r * 0.06, r * 0.32);
  head.add(hinge, arm);
}
