// each pet has its own look: { kind, cat: {...}, bunny: {...} }
const LOOK_KEYS = ["name", "fur", "accent", "collar", "hat", "size", "pattern", "ears", "tail", "coat", "eyes", "eyes2"];
const DEFAULT_LOOKS = {
  cat: { name: "", fur: "#f4a259", accent: "#fff1e0", collar: "#e2557f", hat: "none", size: "regular", pattern: "solid", ears: "pointy", tail: "long", coat: "short", eyes: "#2b1d24", eyes2: "" },
  bunny: { name: "", fur: "#fff7f0", accent: "#ffffff", collar: "#e2557f", hat: "none", size: "regular", pattern: "solid", ears: "pointy", tail: "long", coat: "short", eyes: "#2b1d24", eyes2: "" },
};
const lookOf = (src, species) => {
  const out = { ...DEFAULT_LOOKS[species] };
  if (src && typeof src === "object") for (const k of LOOK_KEYS) if (typeof src[k] === "string") out[k] = src[k];
  return out;
};
// any saved or received pet settings, old (one shared set) or new, as one look per pet
function normalizePet(p) {
  const raw = p && typeof p === "object" ? p : {};
  // the puppy was retired: it becomes a kitty
  const kind = raw.kind === "bunny" || raw.kind === "both" ? raw.kind : "cat";
  if (raw.cat || raw.bunny) return { kind, cat: lookOf(raw.cat, "cat"), bunny: lookOf(raw.bunny, "bunny") };
  // before each pet had its own options: the main look was shared, fur2/name2 were the bunny's in "both"
  const shared = { accent: raw.accent, collar: raw.collar, hat: raw.hat, size: raw.size };
  const bunnyFirst = kind === "bunny";
  return {
    kind,
    cat: lookOf({ ...raw, ...(bunnyFirst ? { fur: undefined, name: undefined } : {}) }, "cat"),
    bunny: lookOf({ ...shared, fur: bunnyFirst ? raw.fur : raw.fur2, name: bunnyFirst ? raw.name : raw.name2 }, "bunny"),
  };
}
const petSpecies = (cfg) => (cfg.kind === "both" ? ["cat", "bunny"] : [cfg.kind]);
function loadPet() {
  try {
    return normalizePet(JSON.parse(localStorage.getItem(PET_KEY) || "null"));
  } catch {}
  return normalizePet(null);
}
export function savePet(p) {
  try {
    localStorage.setItem(PET_KEY, JSON.stringify(p));
  } catch {}
}

function petHat(head, kind, y, collar) {
  const g = new THREE.Group();
  g.position.set(0, y, 0);
  head.add(g);
  // clips go on the front of the head beside an ear, not inside it
  const r = y / 0.92;
  const clip = (side) => g.position.set(side * r * 0.67, r * 0.67, r * 0.47);
  if (kind === "bow") {
    clip(1);
    for (const s of [-1, 1]) part(g, new THREE.ConeGeometry(0.045, 0.08, 4), collar, s * 0.04, 0, 0).rotation.z = s * Math.PI / 2;
    part(g, new THREE.SphereGeometry(0.02, 5, 4), collar);
  } else if (kind === "flower") {
    clip(-1);
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2;
      part(g, new THREE.SphereGeometry(0.025, 5, 4), "#ff8fb1", Math.cos(a) * 0.03, Math.sin(a) * 0.03, 0.02);
    }
    part(g, new THREE.SphereGeometry(0.02, 5, 4), "#ffd166", 0, 0, 0.03);
  } else if (kind === "crown") {
    const gold = new THREE.MeshStandardMaterial({ color: "#ffd166", metalness: 0.5, roughness: 0.35, emissive: "#5a3a00", emissiveIntensity: 0.3, side: THREE.DoubleSide });
    part(g, new THREE.CylinderGeometry(0.06, 0.065, 0.04, 8, 1, true), gold);
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2;
      part(g, new THREE.ConeGeometry(0.015, 0.04, 4), gold, Math.cos(a) * 0.06, 0.04, Math.sin(a) * 0.06);
    }
  } else if (kind === "party") {
    const hat = part(g, new THREE.ConeGeometry(0.06, 0.16, 10), collar, 0, 0.06, 0);
    hat.rotation.z = 0.2;
    part(g, new THREE.SphereGeometry(0.022, 6, 4), "#fff7f2", -0.016, 0.15, 0);
  } else if (kind === "witch") {
    part(g, new THREE.CylinderGeometry(0.11, 0.11, 0.012, 14), "#2b2633", 0, 0.005, 0);
    const cone = part(g, new THREE.ConeGeometry(0.06, 0.17, 10), "#2b2633", 0, 0.09, -0.01);
    cone.rotation.x = -0.25;
    part(g, new THREE.CylinderGeometry(0.062, 0.062, 0.02, 10), collar, 0, 0.022, 0);
  } else if (kind === "halo") {
    const ring = part(g, new THREE.TorusGeometry(0.075, 0.012, 4, 16), new THREE.MeshStandardMaterial({ color: "#fff2b0", emissive: "#ffe27a", emissiveIntensity: 1.2 }), 0, 0.09, 0);
    ring.rotation.x = Math.PI / 2;
  } else if (kind === "star") {
    clip(1);
    const st = part(g, new THREE.OctahedronGeometry(0.04, 0), "#ffd166", 0, 0, 0.02);
    st.scale.set(1, 1, 0.45);
    st.rotation.z = Math.PI / 4;
  }
}

function petTag(text) {
  const { ctx, tex } = textCanvas(256, 64);
  ctx.font = `700 30px ${FONT}`;
  const w = Math.min(250, ctx.measureText(text).width + 34);
  ctx.fillStyle = "rgba(226,85,127,0.8)";
  ctx.beginPath();
  ctx.roundRect((256 - w) / 2, 8, w, 48, 24);
  ctx.fill();
  ctx.fillStyle = "#fff";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(text, 128, 33);
  tex.needsUpdate = true;
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
  s.scale.set(1.0, 0.25, 1);
  s.renderOrder = 6;
  return s;
}

const CAT_COLORS = [
  ["#f4a259", "#fff1e0"], ["#9a9aa8", "#e8e8f0"], ["#2b2633", "#ffffff"], ["#fff7f0", "#f7c6d9"], ["#c98a5a", "#2b2633"],
];
const BUNNY_COLORS = ["#fffaf6", "#b08968", "#d9d4dc", "#f3d9b1", "#8a7a70"];

const shade = (hex, k) => {
  const c = new THREE.Color(hex);
  return "#" + c.multiplyScalar(k).getHexString();
};
// a soft puff of fur, half sunk into the body and a little drawn out along dir
const UP = new THREE.Vector3(0, 1, 0);
const puffGeo = new THREE.IcosahedronGeometry(1, 1);
function tuft(parent, color, pos, dir, r, h) {
  const m = part(parent, puffGeo, color, ...pos);
  m.quaternion.setFromUnitVectors(UP, new THREE.Vector3(...dir).normalize());
  m.scale.set(r * 1.25, h * 0.6, r * 1.25);
  return m;
}
// a flat patch of colour lying on an ellipsoid body (semi-axes a, b, c; c = 0 for a
// long capsule), so patterns read as fur markings rather than lumps
const patchGeo = new THREE.SphereGeometry(1, 10, 5);
function furPatch(parent, color, a, b, c, phi, z, r) {
  const k = c ? Math.sqrt(Math.max(0, 1 - (z / c) ** 2)) : 1;
  const p = new THREE.Vector3(a * k * Math.sin(phi), b * k * Math.cos(phi), z);
  const n = new THREE.Vector3(p.x / (a * a), p.y / (b * b), c ? z / (c * c) : 0).normalize();
  const m = part(parent, patchGeo, color, p.x - n.x * 0.002, p.y - n.y * 0.002, p.z - n.z * 0.002);
  m.quaternion.setFromUnitVectors(UP, n);
  m.scale.set(r, 0.01, r * 1.25);
  return m;
}
const patchColors = (fur, accent) => [accent && accent !== fur ? accent : "#f4a259", fur === "#2b2633" ? "#fff7f0" : "#2b2633"];
const pickOf = (arr) => arr[Math.floor(Math.random() * arr.length)].id;

function makeCat(colors, look = {}) {
  const [fur, accent] = colors;
  const { pattern = "solid", ears = "pointy", tail: tailKind = "long", coat = "short", eyes = "#2b1d24", eyes2 = "" } = look;
  const point = pattern === "siamese" ? "#4a3528" : null;
  const paw = pattern === "tuxedo" || pattern === "socks" ? "#ffffff" : point;
  const stripe = shade(fur, fur === "#2b2633" ? 1.8 : 0.62);
  const root = new THREE.Group();
  const body = new THREE.Group();
  body.position.y = 0.3;
  root.add(body);
  const torso = part(body, new THREE.CapsuleGeometry(0.15, 0.34, 2, 7), fur, 0, 0, 0);
  torso.rotation.x = Math.PI / 2;
  const bib = pattern === "tuxedo" ? "#ffffff" : accent;
  part(body, new THREE.SphereGeometry(0.11, 7, 5), bib, 0, -0.06, 0.12).scale.set(pattern === "tuxedo" ? 1.25 : 1, 0.7, 1.2);
  // the tummy, for showing off on her back
  part(body, new THREE.SphereGeometry(0.12, 8, 5), bib, 0, -0.07, -0.02).scale.set(1.05, 0.62, 1.7);
  if (pattern === "tabby") {
    for (const z of [-0.18, -0.08, 0.02, 0.12]) {
      const band = part(body, new THREE.TorusGeometry(0.152, 0.016, 3, 10, Math.PI * 0.8), stripe, 0, 0, z);
      band.rotation.z = Math.PI * 0.1;
    }
  }
  if (pattern === "calico") {
    const [c1, c2] = patchColors(fur, accent);
    const sx = coat === "fluffy" ? 1.16 : 1;
    const sy = coat === "fluffy" ? 1.04 : 1;
    for (const [phi, z, col, r] of [[0.5, 0.06, c1, 0.07], [-0.7, -0.08, c2, 0.065], [0.9, -0.14, c1, 0.06], [-0.3, 0.14, c2, 0.05]]) furPatch(body, col, 0.15 * sx, 0.15 * sy, 0, phi, z, r);
  }
  if (coat === "fluffy") {
    // a fuller body covered in little tufts that break up the outline, and a puffed-out chest
    torso.scale.set(1.16, 1.12, 1.04);
    // soft rolls of fur down the flanks and over the hips
    // fluffy "trousers" on the back legs
    for (const s of [-1, 1]) part(body, puffGeo, fur, s * 0.085, -0.08, -0.15).scale.set(0.07, 0.09, 0.09);
    part(body, new THREE.IcosahedronGeometry(0.105, 1), bib, 0, 0.0, 0.25).scale.set(1.05, 1, 0.75);
    for (const [x, y] of [[-0.04, -0.03], [0.04, -0.03], [0, -0.07]]) tuft(body, bib, [x, y, 0.3], [x * 4, -0.8, 0.6], 0.03, 0.09);
  }
  const head = new THREE.Group();
  head.position.set(0, 0.16, 0.3);
  body.add(head);
  part(head, new THREE.SphereGeometry(0.15, 9, 7), fur).scale.set(1.1, 0.95, 0.95);
  if (coat === "fluffy") {
    // big fluffy cheeks: a fan of tufts on each side, and a tuft on top
    // a soft ruff under the face that puffs the cheeks out
    const mane = shade(fur, fur === "#2b2633" ? 1.25 : 1.06);
    const ruff = part(head, new THREE.IcosahedronGeometry(0.15, 1), mane, 0, -0.075, -0.02);
    ruff.scale.set(1.32, 0.62, 0.85);
    for (const sd of [-1, 1]) {
      const cheek = part(head, new THREE.IcosahedronGeometry(0.06, 0), mane, sd * 0.165, -0.06, 0.02);
      cheek.scale.set(0.9, 0.75, 1);
      cheek.rotation.z = sd * 0.5;
    }
  }
  if (point || pattern === "tuxedo") part(head, new THREE.SphereGeometry(0.07, 7, 5), point || "#ffffff", 0, -0.045, 0.1).scale.set(1.3, 0.8, 0.8);
  if (pattern === "tabby") for (const x of [-0.035, 0, 0.035]) part(head, new THREE.BoxGeometry(0.014, 0.05, 0.01), stripe, x, 0.1, 0.12).rotation.x = -0.6;
  if (pattern === "calico") furPatch(head, patchColors(fur, accent)[0], 0.165, 0.1425, 0.1425, 0.7, 0.02, 0.06);
  const earCol = point || fur;
  for (const s of [-1, 1]) {
    if (ears === "fold") {
      const ear = part(head, new THREE.ConeGeometry(0.055, 0.08, 4), earCol, s * 0.08, 0.12, 0.02);
      ear.rotation.set(1.1, 0, -s * 0.4);
    } else {
      const ear = part(head, new THREE.ConeGeometry(0.06, 0.12, 4), earCol, s * 0.08, 0.14, -0.01);
      ear.rotation.z = -s * 0.25;
      part(head, new THREE.ConeGeometry(0.035, 0.07, 4), "#f7a8c4", s * 0.08, 0.13, 0.02).rotation.z = -s * 0.25;
      if (ears === "tufts") part(head, new THREE.ConeGeometry(0.012, 0.07, 3), shade(earCol, 0.4), s * 0.095, 0.22, -0.01).rotation.z = -s * 0.25;
    }
    // eyes: coloured iris, dark pupil, a little shine
    const iris = s === 1 && eyes2 ? eyes2 : eyes;
    part(head, new THREE.SphereGeometry(0.028, 7, 5), iris, s * 0.06, 0.02, 0.126).scale.set(1, 1.25, 0.7);
    if (iris !== "#2b1d24") part(head, new THREE.SphereGeometry(0.012, 5, 4), "#1a1216", s * 0.06, 0.02, 0.144).scale.set(0.6, 1.7, 0.5);
    part(head, new THREE.SphereGeometry(0.007, 4, 3), new THREE.MeshBasicMaterial({ color: "#ffffff" }), s * 0.068, 0.034, 0.147);
    for (const w of [-1, 1]) {
      const whisker = part(head, new THREE.BoxGeometry(0.12, 0.004, 0.004), "#ffffff", s * 0.12, -0.03 + w * 0.012, 0.11);
      whisker.rotation.z = s * w * 0.15;
    }
  }
  part(head, new THREE.SphereGeometry(0.02, 5, 4), "#ff8fb1", 0, -0.02, 0.15);
  const legs = [];
  for (const [x, z] of [[0.08, 0.14], [-0.08, 0.14], [0.08, -0.14], [-0.08, -0.14]]) {
    const l = leg(body, 0.035, 0.26, fur, x, -0.04, z);
    if (paw) part(l, new THREE.CylinderGeometry(0.036, 0.034, 0.08, 5), paw, 0, -0.22, 0);
    legs.push(l);
  }
  // tail: a chain that sways
  const tail = [];
  let parent = body;
  let pos = [0, 0.05, -0.24];
  const segs = tailKind === "stubby" ? 1 : 4;
  for (let i = 0; i < segs; i++) {
    const seg = new THREE.Group();
    seg.position.set(...pos);
    parent.add(seg);
    const tip = i === segs - 1;
    const col = tip ? point || (pattern === "tabby" ? stripe : accent) : pattern === "tabby" && i % 2 ? stripe : fur;
    if (tailKind === "stubby") part(seg, new THREE.SphereGeometry(0.05, 6, 4), col, 0, 0.03, 0);
    else if (tailKind === "fluffy") {
      // one smooth bottle-brush: thick in the middle, soft round tip, each piece
      // overlapping the next so it reads as a single tail
      const r = [0.045, 0.058, 0.06, 0.048][i];
      part(seg, new THREE.CapsuleGeometry(r, 0.09, 4, 8), col, 0, 0.06, 0);
    }
    else part(seg, new THREE.CylinderGeometry(0.03 - i * 0.004, 0.034 - i * 0.004, 0.12, 5), col, 0, 0.06, 0);
    seg.rotation.x = i === 0 ? -0.9 : -0.25;
    tail.push(seg);
    parent = seg;
    pos = [0, 0.12, 0];
  }
  return { root, body, head, legs, tail };
}

function makeBunny(colors, look = {}) {
  const [fur, accent = "#ffffff"] = Array.isArray(colors) ? colors : [colors];
  const { pattern = "solid", ears: earKind = "pointy", tail: tailKind = "long", coat = "short", eyes = "#2b1d24", eyes2 = "" } = look;
  const point = pattern === "siamese" ? "#4a3528" : null;
  const paw = pattern === "tuxedo" || pattern === "socks" ? "#ffffff" : point || fur;
  const stripe = shade(fur, fur === "#2b2633" ? 1.8 : 0.62);
  const root = new THREE.Group();
  const body = new THREE.Group();
  body.position.y = 0.18;
  root.add(body);
  const torso = part(body, new THREE.SphereGeometry(0.17, 9, 7), fur);
  torso.scale.set(1, 0.92, 1.18);
  const bib = pattern === "tuxedo" ? "#ffffff" : accent;
  // a pale chest, and the tummy for flopping over
  part(body, new THREE.SphereGeometry(0.1, 9, 7), bib, 0, -0.03, 0.12).scale.set(pattern === "tuxedo" ? 1.2 : 0.95, 0.85, 0.8);
  part(body, new THREE.SphereGeometry(0.12, 8, 5), bib, 0, -0.09, 0.0).scale.set(0.95, 0.6, 1.3);
  if (pattern === "tabby") {
    for (const z of [-0.11, -0.04, 0.03]) {
      const r = 0.172 * Math.sqrt(1 - (z / 0.2) ** 2);
      const band = part(body, new THREE.TorusGeometry(r, 0.016, 3, 10, Math.PI * 0.8), stripe, 0, 0, z);
      band.rotation.z = Math.PI * 0.1;
      band.scale.y = 0.92;
    }
  }
  if (pattern === "calico") {
    const [c1, c2] = patchColors(fur, accent);
    const f = coat === "fluffy";
    for (const [phi, z, col, r] of [[0.55, 0.03, c1, 0.07], [-0.7, -0.08, c2, 0.065], [0.8, -0.13, c1, 0.055]]) furPatch(body, col, 0.17 * (f ? 1.12 : 1), 0.17 * (f ? 1.02 : 0.92), 0.17 * (f ? 1.26 : 1.18), phi, z, r);
  }
  if (coat === "fluffy") {
    torso.scale.set(1.12, 1.02, 1.26);
    part(body, new THREE.IcosahedronGeometry(0.1, 1), bib, 0, 0.0, 0.15).scale.set(1.05, 1, 0.75);
    for (const [x, y] of [[-0.04, -0.03], [0.04, -0.03], [0, -0.07]]) tuft(body, bib, [x, y, 0.19], [x * 4, -0.8, 0.6], 0.03, 0.08);
  }
  const head = new THREE.Group();
  head.position.set(0, 0.16, 0.15);
  body.add(head);
  part(head, new THREE.SphereGeometry(0.11, 9, 7), fur);
  // a soft muzzle
  part(head, new THREE.SphereGeometry(0.05, 7, 5), pattern === "tuxedo" ? "#ffffff" : accent, 0, -0.035, 0.075).scale.set(1.25, 0.8, 0.8);
  if (point) part(head, new THREE.SphereGeometry(0.034, 7, 5), point, 0, -0.012, 0.092).scale.set(1.2, 0.9, 0.7);
  if (pattern === "tuxedo") part(head, new THREE.BoxGeometry(0.03, 0.08, 0.02), "#ffffff", 0, 0.03, 0.1).rotation.x = -0.4;
  if (pattern === "tabby") for (const x of [-0.025, 0, 0.025]) part(head, new THREE.BoxGeometry(0.012, 0.04, 0.01), stripe, x, 0.075, 0.078).rotation.x = -0.7;
  if (pattern === "calico") furPatch(head, patchColors(fur, accent)[0], 0.11, 0.11, 0.11, 0.7, 0.02, 0.045);
  if (coat === "fluffy") {
    // a lionhead mane around the face
    const mane = shade(fur, fur === "#2b2633" ? 1.25 : 1.06);
    part(head, new THREE.IcosahedronGeometry(0.12, 1), mane, 0, -0.03, -0.03).scale.set(1.3, 1.05, 0.9);
    for (const sd of [-1, 1]) {
      const cheek = part(head, new THREE.IcosahedronGeometry(0.05, 0), mane, sd * 0.11, -0.04, 0.02);
      cheek.rotation.z = sd * 0.5;
    }
    part(head, new THREE.IcosahedronGeometry(0.045, 0), mane, 0, 0.1, 0.0);
  }
  const lop = earKind === "fold";
  const earCol = point || fur;
  const ears = [];
  for (const s of [-1, 1]) {
    const ear = new THREE.Group();
    ear.position.set(s * (lop ? 0.08 : 0.045), lop ? 0.06 : 0.08, -0.02);
    ear.rotation.z = lop ? -s * (Math.PI - 0.3) : -s * 0.15;
    head.add(ear);
    part(ear, new THREE.CapsuleGeometry(0.032, 0.14, 2, 6), earCol, 0, 0.1, 0).scale.z = 0.6;
    part(ear, new THREE.CapsuleGeometry(0.018, 0.1, 2, 5), "#f7a8c4", 0, 0.1, 0.012).scale.z = 0.5;
    if (earKind === "tufts") part(ear, new THREE.ConeGeometry(0.014, 0.06, 3), shade(earCol, 0.4), 0, 0.22, 0);
    ears.push(ear);
    // eyes: coloured iris, dark pupil, a little shine
    const iris = s === 1 && eyes2 ? eyes2 : eyes;
    part(head, new THREE.SphereGeometry(0.021, 7, 5), iris, s * 0.055, 0.02, 0.085).scale.set(1, 1.15, 0.8);
    if (iris !== "#2b1d24") part(head, new THREE.SphereGeometry(0.01, 5, 4), "#1a1216", s * 0.058, 0.02, 0.1).scale.set(0.8, 1.4, 0.5);
    part(head, new THREE.SphereGeometry(0.006, 4, 3), new THREE.MeshBasicMaterial({ color: "#ffffff" }), s * 0.064, 0.03, 0.102);
  }
  const nose = part(head, new THREE.SphereGeometry(0.016, 5, 4), "#ff8fb1", 0, -0.015, 0.11);
  // tail
  const tailR = tailKind === "fluffy" ? 0.085 : tailKind === "stubby" ? 0.04 : 0.06;
  const tail = part(body, new THREE.SphereGeometry(tailR, 7, 5), point || accent, 0, 0.03, -0.19 - tailR * 0.2);
  if (tailKind === "fluffy") for (const [x, y] of [[0.04, 0.03], [-0.04, 0.03], [0, -0.03]]) tuft(tail, point || accent, [x, y, -0.03], [x * 10, y * 10, -1], 0.03, 0.08);
  // front paws (they wash the face) and the big back feet
  const paws = [];
  for (const s of [-1, 1]) {
    const g = new THREE.Group();
    g.position.set(s * 0.06, -0.06, 0.13);
    body.add(g);
    part(g, new THREE.SphereGeometry(0.034, 6, 4), paw, 0, -0.07, 0.01).scale.set(1, 1.3, 1.2);
    paws.push(g);
  }
  const feet = [];
  for (const s of [-1, 1]) {
    const g = new THREE.Group();
    g.position.set(s * 0.08, -0.12, -0.06);
    body.add(g);
    part(g, new THREE.SphereGeometry(0.06, 6, 4), pattern === "socks" ? "#ffffff" : point || fur, 0, -0.02, 0).scale.set(0.8, 0.5, 1.6);
    feet.push(g);
  }
  return { root, body, head, ears, lop, paws, feet, nose };
}

function makeDeer(stag) {
  const fur = "#b9895c";
  const belly = "#f1dcc0";
  const root = new THREE.Group();
  const body = new THREE.Group();
  body.position.y = 0.95;
  root.add(body);
  const torso = part(body, new THREE.CapsuleGeometry(0.28, 0.7, 2, 8), fur);
  torso.rotation.x = Math.PI / 2;
  part(body, new THREE.SphereGeometry(0.24, 7, 5), belly, 0, -0.1, 0).scale.set(0.9, 0.6, 2);
  for (const [x, z] of [[0.12, 0.2], [-0.15, -0.1], [0.05, -0.25], [-0.1, 0.25], [0.18, -0.05]]) part(body, new THREE.SphereGeometry(0.03, 5, 4), "#fff7ea", x, 0.25, z);
  const neck = new THREE.Group();
  neck.position.set(0, 0.15, 0.42);
  body.add(neck);
  const n = part(neck, new THREE.CylinderGeometry(0.1, 0.14, 0.55, 6), fur, 0, 0.25, 0.05);
  n.rotation.x = 0.35;
  const head = new THREE.Group();
  head.position.set(0, 0.52, 0.18);
  neck.add(head);
  part(head, new THREE.SphereGeometry(0.15, 8, 6), fur).scale.set(0.9, 0.9, 1.1);
  part(head, new THREE.ConeGeometry(0.09, 0.22, 6), fur, 0, -0.04, 0.17).rotation.x = Math.PI / 2;
  part(head, new THREE.SphereGeometry(0.035, 5, 4), "#2b1d24", 0, -0.04, 0.28);
  for (const s of [-1, 1]) {
    part(head, new THREE.SphereGeometry(0.03, 6, 4), "#2b1d24", s * 0.1, 0.03, 0.08);
    const ear = part(head, new THREE.ConeGeometry(0.06, 0.18, 4), fur, s * 0.13, 0.12, -0.04);
    ear.rotation.z = -s * 1.0;
    if (stag) {
      const antler = new THREE.Group();
      antler.position.set(s * 0.07, 0.13, -0.02);
      antler.rotation.z = -s * 0.35;
      head.add(antler);
      const bone = "#efe2c8";
      part(antler, new THREE.CylinderGeometry(0.015, 0.02, 0.3, 4), bone, 0, 0.15, 0);
      for (const [y, a] of [[0.12, 0.8], [0.22, -0.7]]) {
        const tine = part(antler, new THREE.CylinderGeometry(0.01, 0.014, 0.14, 4), bone, s * 0.04, y, 0);
        tine.rotation.z = -s * a;
      }
    }
  }
  part(body, new THREE.SphereGeometry(0.07, 6, 4), "#ffffff", 0, 0.1, -0.52);
  const legs = [];
  for (const [x, z] of [[0.15, 0.32], [-0.15, 0.32], [0.15, -0.32], [-0.15, -0.32]]) legs.push(leg(body, 0.045, 0.85, fur, x, -0.05, z));
  return { root, body, neck, head, legs };
}

const SPECIES = {
  cat: { walk: 1.1, run: 3.6, radius: 0.28, home: 20 },
  bunny: { walk: 1.4, run: 4.6, radius: 0.22, home: 16 },
  deer: { walk: 1.0, run: 6.2, radius: 0.55, home: 24 },
  boy: { walk: 2.4, run: 5.5, radius: 0.38, home: 40 },
};

export function buildPetModels(cfg) {
  const pc = normalizePet(cfg);
  // every pet is built from its own look
  const one = (kind) => {
    const c = pc[kind];
    const name = c.name;
    let model;
    let headR;
    if (kind === "bunny") {
      model = makeBunny([c.fur, c.accent], c);
      headR = 0.11;
    } else {
      model = makeCat([c.fur, c.accent], c);
      headR = 0.15;
    }
    // the collar sits round the neck; a fluffy ruff would swallow it (leaving just a
    // floating bell), so with a fluffy coat it goes lower and wider, outside the fur
    const fluffy = c.coat === "fluffy";
    const cy = fluffy ? (kind === "bunny" ? -0.12 : -0.13) : -headR * 0.75;
    const cr = fluffy ? (kind === "bunny" ? 0.1 : 0.13) : headR * 0.68;
    // round the neck itself: back behind the head and tilted along the neck, not a ring
    // under the chin
    const tilt = 0.55;
    const cz = -0.07;
    const collar = part(model.head, new THREE.TorusGeometry(cr, 0.02, 5, 16), c.collar, 0, cy, cz);
    collar.rotation.x = tilt - Math.PI / 2;
    if (fluffy) collar.scale.x = 1.25;
    // a little bell hanging from the front of it
    const bell = new THREE.Group();
    bell.position.set(0, cy - Math.sin(tilt) * (cr + 0.012) - 0.026, cz + Math.cos(tilt) * (cr + 0.012));
    model.head.add(bell);
    part(bell, new THREE.TorusGeometry(0.008, 0.003, 3, 8), "#c9a23a", 0, 0.022, 0);
    part(bell, new THREE.SphereGeometry(0.022, 8, 6), "#ffd166");
    part(bell, new THREE.BoxGeometry(0.03, 0.004, 0.006), "#8a6a1a", 0, -0.006, 0.019);
    if (c.hat !== "none") petHat(model.head, c.hat, headR * 0.92, c.collar);
    model.root.scale.setScalar(PET_SIZES[c.size] || 1);
    // a pet always moves (hops, wags, breathes): never merged into the still scenery round it
    // (bake.js), or its body would stay behind while only its collar went on hopping
    model.root.userData.live = true;
    return { model, kind: kind === "bunny" ? "bunny" : "cat", species: kind, name };
  };
  return petSpecies(pc).map(one);
}

export class Creatures {
  constructor(scene, { lowEnd, collide, isWalkable, places }) {
    this.scene = scene;
    this.collide = collide;
    this.isWalkable = isWalkable;
    this.places = places;
    this.list = [];
    this.t = 0;
    const rnd = (a, b) => a + Math.random() * (b - a);
    const randomSpot = (r = 42) => {
      for (let i = 0; i < 40; i++) {
        const a = Math.random() * Math.PI * 2;
        const d = 12 + Math.random() * (r - 12);
        const p = new THREE.Vector3(Math.sin(a) * d, 0, Math.cos(a) * d);
        if (isWalkable(p)) return p;
      }
      return new THREE.Vector3(0, 0, 25);
    };
    this.randomSpot = randomSpot;

    const counts = lowEnd ? { cat: 3, bunny: 5, deer: 3 } : { cat: 5, bunny: 8, deer: 4 };
    for (let i = 1; i < counts.cat; i++) {
      const look = { pattern: pickOf(PET_OPTIONS.pattern), ears: pickOf(PET_OPTIONS.ears), tail: pickOf(PET_OPTIONS.tail), coat: pickOf(PET_OPTIONS.coat), eyes: PET_COLORS.eyes[Math.floor(Math.random() * PET_COLORS.eyes.length)] };
      this.add("cat", makeCat(CAT_COLORS[i % CAT_COLORS.length], look), randomSpot());
    }
    for (let i = 0; i < counts.bunny; i++) {
      const look = { pattern: pickOf(BUNNY_OPTIONS.pattern), ears: pickOf(BUNNY_OPTIONS.ears), tail: pickOf(BUNNY_OPTIONS.tail), coat: Math.random() < 0.3 ? "fluffy" : "short" };
      this.add("bunny", makeBunny([BUNNY_COLORS[i % BUNNY_COLORS.length], "#ffffff"], look), randomSpot());
    }
    for (let i = 0; i < counts.deer; i++) this.add("deer", makeDeer(i % 2 === 0), randomSpot(44));

    // your own pet follows you around
    this.setPet(loadPet(), randomSpot());

    // no computer characters: just you two and the animals
    this.boy = null;
    void rnd;
  }

  add(kind, model, pos, extra = {}) {
    const c = {
      kind,
      model,
      pos: pos.clone(),
      facing: Math.random() * Math.PI * 2,
      speed: 0,
      mode: "idle",
      timer: Math.random() * 3,
      target: null,
      phase: Math.random() * 10,
      hop: 0,
      happy: 0,
      ...SPECIES[kind],
      ...extra,
    };
    model.root.position.copy(pos);
    model.root.userData.creature = c;
    if (kind !== "boy") {
      model.root.traverse((o) => {
        if (o.isMesh) o.castShadow = false;
      });
      const shadow = blobShadow(kind === "deer" ? 1.6 : kind === "boy" ? 1 : 0.7);
      c.shadow = shadow;
      this.scene.add(shadow);
    }
    this.scene.add(model.root);
    this.list.push(c);
    return c;
  }

  // build (or rebuild) your pets from their settings
  setPet(cfg, at) {
    const olds = this.pets || [];
    const pos = at ? at.clone() : olds[0] ? olds[0].pos.clone() : new THREE.Vector3(0, 0, 30);
    const stay = olds[0]?.stay || false;
    // same pets, new look (colours, hats…): swap only the models, so each pet keeps
    // where it is and what it's doing instead of popping back in fresh every change
    const next = normalizePet(cfg);
    const built = !at && olds.length ? buildPetModels(next) : null;
    if (built && built.length === olds.length && built.every((b, i) => b.species === olds[i].species && b.kind === olds[i].kind)) {
      this.petConfig = next;
      built.forEach((b, i) => {
        const c = olds[i];
        const old = c.model.root;
        this.scene.remove(old);
        old.traverse((o) => o.geometry?.dispose());
        b.model.root.position.copy(old.position);
        b.model.root.rotation.copy(old.rotation);
        b.model.root.userData.creature = c;
        b.model.root.traverse((o) => {
          if (o.isMesh) o.castShadow = false;
        });
        c.model = b.model;
        this.scene.add(b.model.root);
        if (b.name !== c.petName) {
          if (c.tag) this.scene.remove(c.tag);
          c.tag = b.name ? petTag(b.name) : null;
          if (c.tag) this.scene.add(c.tag);
          c.petName = b.name;
        }
      });
      return this.pet;
    }
    if (built) for (const b of built) b.model.root.traverse((o) => o.geometry?.dispose());
    // each pet keeps its spot when only the other one changes
    const spots = new Map(at ? [] : olds.map((o) => [o.species, { pos: o.pos.clone(), facing: o.facing }]));
    for (const old of olds) {
      this.remove(old);
      if (old.tag) this.scene.remove(old.tag);
    }
    this.petConfig = normalizePet(cfg);
    this.pets = buildPetModels(this.petConfig).map((b, i) => {
      const spot = spots.get(b.species);
      const p = spot ? spot.pos : pos.clone().add(new THREE.Vector3(i * 0.8, 0, i * 0.5));
      const pet = this.add(b.kind, b.model, p, { companion: true, species: b.species, petName: b.name, slot: i, stay, ...(spot ? { facing: spot.facing } : {}) });
      if (b.name) {
        pet.tag = petTag(b.name);
        this.scene.add(pet.tag);
      }
      return pet;
    });
    this.pet = this.pets[0];
    return this.pet;
  }

  // "sit" / "come here"
  toggleStay() {
    const stay = !this.pets?.[0]?.stay;
    for (const p of this.pets || []) {
      p.stay = stay;
      p.mode = "idle";
      p.target = null;
      p.timer = 2;
      p.happy = 1.2;
    }
    return stay;
  }

  // your person's pets: models only, moved by the network
  makeRemotePets(cfg) {
    return buildPetModels(cfg).map((b, i) => {
      const c = { kind: b.kind, model: b.model, pos: new THREE.Vector3(), facing: 0, speed: 0, mode: "idle", phase: Math.random() * 10, happy: 0, pose: "", species: b.species, petName: b.name, slot: i, remote: true };
      b.model.root.traverse((o) => {
        if (o.isMesh) o.castShadow = false;
      });
      c.shadow = blobShadow(0.7);
      this.scene.add(c.shadow, b.model.root);
      if (b.name) {
        c.tag = petTag(b.name);
        this.scene.add(c.tag);
      }
      return c;
    });
  }
  dropRemotePets(list) {
    for (const c of list || []) this.scene.remove(c.model.root, c.shadow, ...(c.tag ? [c.tag] : []));
  }
  animateRemotePet(c, dt) {
    c.happy = Math.max(0, (c.happy || 0) - dt);
    this.animate(c, dt, 99);
  }
  // where your pets are and what they're doing: [x, z, facing, speed, idle, pose, happy, stay]
  petStates() {
    return (this.pets || []).map((p) => [+p.pos.x.toFixed(2), +p.pos.z.toFixed(2), +p.facing.toFixed(2), +p.speed.toFixed(2), p.mode === "idle" ? 1 : 0, p.pose || 0, +(p.happy || 0).toFixed(1), p.stay ? 1 : 0]);
  }
  // their pet's state from the network (held for a moment after you pet it here)
  applyRemotePet(c, s) {
    if (c.hold > performance.now()) return;
    c.targetFacing = s[2];
    c.pose = s[5] || "";
    c.happy = s[6] || 0;
    c.stay = Boolean(s[7]);
  }

  // golden bunnies for the catch game: they run from you
  spawnGolden(pos) {
    const model = makeBunny(["#ffd166", "#fff4c4"]);
    const bow = part(model.head, new THREE.TorusGeometry(0.05, 0.02, 4, 8), "#e2557f", 0, 0.1, -0.06);
    bow.rotation.y = Math.PI / 2;
    const c = this.add("bunny", model, pos, { scared: true, run: 4.2, golden: true });
    c.mode = "flee";
    return c;
  }

  remove(c) {
    c.hidden = true;
    this.scene.remove(c.model.root);
    if (c.shadow) this.scene.remove(c.shadow);
    this.list = this.list.filter((x) => x !== c);
  }

  // nearest animal or the boy the player can interact with
  nearest(p, max = 2.0) {
    let best = null;
    let bd = max;
    for (const c of this.list) {
      if (c.hidden || c.golden) continue;
      const d = Math.hypot(c.pos.x - p.x, c.pos.z - p.z) - (c.kind === "deer" ? 0.5 : 0);
      if (d < bd) {
        bd = d;
        best = c;
      }
    }
    return best;
  }

  label(c) {
    if (c.companion) return `pet ${c.petName || `your ${c.species === "cat" ? "kitty" : c.species}`} ♡`;
    if (c.remote) return `pet ${c.petName || `${c.owner?.name ? `${c.owner.name}’s` : "their"} ${c.species === "cat" ? "kitty" : c.species}`} ♡`;
    return { cat: "pet the kitty ♡", bunny: "pet the bunny ♡", deer: "pet the deer ♡", boy: "hug him ♡" }[c.kind];
  }

  // the player pets / greets c
  greet(c, player) {
    c.happy = 2.2;
    c.mode = "idle";
    c.timer = 2.5;
    c.facing = Math.atan2(player.pos.x - c.pos.x, player.pos.z - c.pos.z);
    if (c.kind === "cat" || c.kind === "bunny") {
      // a kitty rolls over for belly rubs; a bunny stays on its feet and settles
      // into a happy loaf under your hand (no flopping onto the floor)
      c.poseT = 4 + Math.random() * 2;
      c.pose = c.kind === "bunny" ? "loaf" : "belly";
      c.wasMoving = false;
    }
    if (c.remote) {
      // their pet: show it now, until their own update catches up
      c.targetFacing = c.facing;
      c.hold = performance.now() + 900;
    }
    if (c.kind === "boy") {
      c.avatar.playEmote("hug");
      c.bubble.userData.say(["hehe ♡", "hiii ♡", "warm ♡", "again ♡"][Math.floor(Math.random() * 4)]);
    }
    return c.kind;
  }

  update(dt, player) {
    this.t += dt;
    for (const c of this.list) this.think(c, dt, player);
  }

  // hit by the rifle: fall over, then get up (and run, or complain)
  knock(c) {
    c.knock = c.kind === "boy" ? 2.4 : 1.8;
    c.speed = 0;
    if (c.kind === "boy") c.bubble.userData.say(["ow!! >:(", "hey!!", "why 😭"][Math.floor(Math.random() * 3)]);
  }

  think(c, dt, player) {
    const dx = player.pos.x - c.pos.x;
    const dz = player.pos.z - c.pos.z;
    const pd = Math.hypot(dx, dz);
    if (c.knock > 0) {
      c.knock -= dt;
      if (c.knock <= 0 && c.kind !== "boy") {
        c.mode = "flee";
        c.timer = 2;
        c.target = c.pos.clone().add(new THREE.Vector3(-dx, 0, -dz).normalize().multiplyScalar(8));
      }
      this.animate(c, dt, pd);
      return;
    }
    c.timer -= dt;
    c.happy = Math.max(0, c.happy - dt);

    // decide
    if (c.companion) {
      // stays put when told to sit, and waits at the edge while you do the sky trail
      const away = player.offIsland;
      if (c.stay || away) {
        if (c.mode !== "idle") {
          c.mode = "idle";
          c.timer = 2;
        }
        c.target = null;
        if (!c.stay && away && pd > 6) c.facing = turnTo(c.facing, Math.atan2(dx, dz), dt * 3);
      } else if (pd > 28) {
        // after travelling, the kitty catches up
        c.pos.set(player.pos.x - Math.sin(player.facing) * 1.5, 0, player.pos.z - Math.cos(player.facing) * 1.5);
      }
      if (c.stay || away) {
        // waiting
      } else if (pd > 2.2 + (c.slot || 0) * 0.8 && c.happy <= 0) {
        c.mode = pd > 5 ? "run" : "walk";
        const side = (c.slot || 0) * 0.9;
        c.target = new THREE.Vector3(player.pos.x - (dx / pd) * 1.4 + (dz / pd) * side, 0, player.pos.z - (dz / pd) * 1.4 - (dx / pd) * side);
      } else if (c.mode !== "idle") {
        c.mode = "idle";
        c.timer = 1 + Math.random() * 2;
      }
    } else if (c.kind === "deer" || c.kind === "bunny") {
      const scary = (player.speed > 4 && pd < 6) || (c.kind === "deer" && pd < 2.4 && player.speed > 2.5) || (c.scared && pd < 7);
      if (scary && c.happy <= 0) {
        c.mode = "flee";
        c.timer = 1.5;
        const away = new THREE.Vector3(-dx, 0, -dz).normalize().multiplyScalar(7);
        c.target = c.pos.clone().add(away);
      }
    } else if (c.kind === "boy") {
      if (pd < 4 && player.pos.y < 0.6) {
        if (!c.greeted) {
          c.greeted = true;
          c.avatar.playEmote("wave");
          c.bubble.userData.say("hi ♡");
        }
        c.mode = "idle";
        c.timer = Math.max(c.timer, 1);
        c.facing = turnTo(c.facing, Math.atan2(dx, dz), dt * 6);
      } else if (pd > 9) c.greeted = false;
    }

    if (c.timer <= 0 && !c.companion) {
      // wild cats like to hang about and do cat things for a while
      if (c.mode === "idle" && c.kind === "cat" && Math.random() < 0.6) c.timer = 6 + Math.random() * 10;
      else if (c.mode === "idle") {
        c.mode = "walk";
        c.timer = 4 + Math.random() * 5;
        c.target = c.kind === "boy" ? this.places[Math.floor(Math.random() * this.places.length)].clone() : this.wanderTarget(c);
      } else {
        c.mode = "idle";
        c.timer = 1.5 + Math.random() * 4;
      }
    }

    // move
    let want = 0;
    if ((c.mode === "walk" || c.mode === "run" || c.mode === "flee") && c.target) {
      const tx = c.target.x - c.pos.x;
      const tz = c.target.z - c.pos.z;
      const td = Math.hypot(tx, tz);
      if (td < 0.4) {
        c.mode = "idle";
        c.timer = 1 + Math.random() * 3;
      } else {
        want = c.mode === "walk" ? c.walk : c.run;
        c.facing = turnTo(c.facing, Math.atan2(tx, tz), dt * (c.mode === "flee" ? 9 : 4));
      }
    }
    c.speed += (want - c.speed) * (1 - Math.exp(-dt * 6));
    if (c.speed > 0.02) {
      const before = c.pos.clone();
      c.pos.x += Math.sin(c.facing) * c.speed * dt;
      c.pos.z += Math.cos(c.facing) * c.speed * dt;
      this.collide(c.pos, c.radius);
      if (!this.isWalkable(c.pos)) c.pos.copy(before);
      // stuck: pick somewhere else
      if (before.distanceTo(c.pos) < c.speed * dt * 0.3 && c.mode !== "idle") {
        c.target = this.wanderTarget(c);
      }
    }
    if (c.kind === "cat" || c.kind === "bunny") this.choosePose(c, dt);
    this.animate(c, dt, pd);
  }

  // cats do cat things while they hang around: loaf, stretch, roll over, clean themselves
  choosePose(c, dt) {
    if (c.mode !== "idle" || c.knock > 0) {
      c.pose = "";
      c.wasMoving = true;
      return;
    }
    // just stopped: sit a moment before doing anything
    if (c.wasMoving) {
      c.wasMoving = false;
      c.pose = "";
      c.poseT = 2.5 + Math.random() * 2;
    }
    c.poseT = (c.poseT ?? 3) - dt;
    if (c.poseT > 0 || c.happy > 0) return;
    // what follows what, like a real cat: sit -> wash -> sit, sit -> loaf -> stretch, ...
    const NEXT = c.kind === "bunny"
      ? {
          // a bunny: sit up and look about, wash, loaf, flop, stretch, and binky when happy
          "": [["tall", 3], ["groom", 3], ["loaf", 3], ["belly", 1], ["stretch", 1], ["binky", c.companion ? 2 : 1]],
          tall: [["", 3], ["groom", 1]],
          groom: [["", 3], ["loaf", 1], ["tall", 1]],
          loaf: [["stretch", 2], ["", 1], ["belly", 1]],
          belly: [["", 2], ["groom", 1]],
          stretch: [["", 2], ["groom", 1], ["binky", 1]],
          binky: [["", 2], ["tall", 1]],
        }
      : {
          "": [["groom", 4], ["loaf", 3], ["belly", 2], ["", 1]],
          groom: [["", 3], ["loaf", 1]],
          loaf: [["stretch", 3], ["belly", 1], ["loaf", 1]],
          belly: [["", 2], ["groom", 1]],
          stretch: [["", 2], ["groom", 1]],
        };
    const opts = NEXT[c.pose || ""] || NEXT[""];
    let roll = Math.random() * opts.reduce((n, [, w]) => n + w, 0);
    let pick = "";
    for (const [p, w] of opts) if ((roll -= w) <= 0) {
      pick = p;
      break;
    }
    const LEN = { "": [3, 6], groom: [4, 7], loaf: [8, 14], belly: [5, 8], stretch: [2.2, 2.2], tall: [2, 4], binky: [0.8, 0.8] };
    const [lo, hi] = LEN[pick];
    c.poseT = lo + Math.random() * (hi - lo);
    c.pose = pick;
  }

  wanderTarget(c) {
    for (let i = 0; i < 12; i++) {
      const a = Math.random() * Math.PI * 2;
      const d = 2 + Math.random() * 7;
      const p = new THREE.Vector3(c.pos.x + Math.sin(a) * d, 0, c.pos.z + Math.cos(a) * d);
      if (Math.hypot(p.x, p.z) < ISLAND_R - 6 && this.isWalkable(p)) return p;
    }
    return this.randomSpot();
  }

  animate(c, dt, pd) {
    const m = c.model;
    const t = this.t;
    const s = c.speed;
    m.root.position.set(c.pos.x, c.pos.y || 0, c.pos.z);
    m.root.rotation.y = c.facing;
    const fall = c.knock > 0 ? Math.min(1, c.knock * 3, (c.kind === "boy" ? 2.4 : 1.8) - c.knock + 0.0001 > 0 ? 1 : 0) : 0;
    c.fall = (c.fall || 0) + (fall - (c.fall || 0)) * (1 - Math.exp(-dt * 10));
    m.root.rotation.z = c.fall * 1.45;
    if (c.shadow) c.shadow.position.set(c.pos.x, 0.02, c.pos.z);
    if (c.tag) c.tag.position.set(c.pos.x, c.kind === "bunny" ? 0.85 : 0.95, c.pos.z);

    if (c.kind === "cat") {
      c.phase += dt * (2 + s * 5);
      const amp = Math.min(1, s / 1.2) * 0.6;
      m.legs.forEach((l, i) => (l.rotation.x = Math.sin(c.phase + (i === 0 || i === 3 ? 0 : Math.PI)) * amp));
      // slow, soft blends between poses (rolling over takes its time)
      const ease = (key, on, rate = 3.2) => (c[key] = (c[key] || 0) + ((on ? 1 : 0) - (c[key] || 0)) * (1 - Math.exp(-dt * rate)));
      const belly = ease("wBelly", c.pose === "belly", 2.2);
      const loaf = ease("wLoaf", c.pose === "loaf");
      const stretch = ease("wStretch", c.pose === "stretch");
      const groom = ease("wGroom", c.pose === "groom");
      const pose = Math.max(belly, loaf, stretch, groom * 0.4);
      // on her back: roll over, paws in the air, wriggle
      m.root.rotation.z = c.fall * 1.45 + belly * (2.75 + Math.sin(t * 2.2 + c.phase) * 0.18);
      m.body.position.y = 0.3 + Math.abs(Math.sin(c.phase)) * 0.02 * amp - belly * 0.46 - loaf * 0.17 - stretch * 0.03;
      const sit = c.mode === "idle" ? (c.stay ? 1.4 : 1) * (1 - pose) : 0;
      m.body.rotation.x += ((-0.35 * sit + stretch * 0.32) - m.body.rotation.x) * (1 - Math.exp(-dt * 4));
      m.legs.forEach((l, i) => {
        const front = i < 2;
        if (belly > 0.01) l.rotation.x = l.rotation.x * (1 - belly) + belly * ((front ? -0.9 : 0.7) + Math.sin(t * 3 + i * 1.3) * 0.35);
        if (stretch > 0.01) l.rotation.x = l.rotation.x * (1 - stretch) + stretch * (front ? -1.2 : 0.15);
        l.scale.y = 1 - loaf * 0.8;
        // grooming: sit up, lift a front paw to the mouth and lick it, then wipe the face
        if (i === 0 && groom > 0.01) l.rotation.x = l.rotation.x * (1 - groom) + groom * (-1.75 + Math.sin(t * 5) * 0.12);
      });
      m.tail.forEach((seg, i) => (seg.rotation.z = Math.sin(t * (c.happy > 0 ? 9 : 2.5) + i * 0.8 + c.phase * 0.1) * (0.25 + i * 0.05)));
      m.head.rotation.y = c.mode === "idle" ? Math.sin(t * 0.7 + c.phase) * 0.5 * (1 - pose) : 0;
      m.head.rotation.y += groom * 0.35;
      // on her back the head tips up off the ground to look at you
      m.head.rotation.x = belly * 0.45 + groom * (0.45 + Math.sin(t * 9) * 0.12);
      m.head.position.y = 0.16 - belly * 0.2;
      m.head.rotation.z = c.happy > 0 ? Math.sin(t * 6) * 0.2 : 0;
    } else if (c.kind === "bunny") {
      // a real bunny's hop: the big back feet push off, it stretches out in the air,
      // lands on its front paws first and the back feet swing past them
      const moving = s > 0.1;
      if (moving) c.phase += dt * Math.PI * 2 * (1.9 + s * 0.45);
      const u = moving ? ((c.phase / (Math.PI * 2)) % 1 + 1) % 1 : 0.8;
      const airborne = moving && u < 0.55;
      const air = airborne ? Math.sin((Math.PI * u) / 0.55) : 0;
      c.hopY = (c.hopY || 0) + ((air * (0.1 + s * 0.035)) - (c.hopY || 0)) * (1 - Math.exp(-dt * 25));
      // nose up as it takes off, nose down as it lands, then it gathers itself
      const hopPitch = !moving ? 0 : airborne ? -0.28 + 0.56 * (u / 0.55) : 0.28 - 0.36 * ((u - 0.55) / 0.45);
      const gather = moving && !airborne ? Math.sin((Math.PI * (u - 0.55)) / 0.45) : 0;

      // bunny things while it hangs about
      const ease = (key, on, rate = 3.2) => (c[key] = (c[key] || 0) + ((on ? 1 : 0) - (c[key] || 0)) * (1 - Math.exp(-dt * rate)));
      const flop = ease("wBelly", c.pose === "belly", 2.2);
      const loaf = ease("wLoaf", c.pose === "loaf");
      const stretch = ease("wStretch", c.pose === "stretch");
      const groom = ease("wGroom", c.pose === "groom");
      const tall = ease("wTall", c.pose === "tall", 4);
      // a binky: a happy leap with a twist in the air
      c.bk = c.pose === "binky" ? (c.bk ?? 0) + dt : undefined;
      const bk = c.bk !== undefined && c.bk < 0.75 ? Math.sin((Math.PI * c.bk) / 0.75) : 0;
      const pose = Math.max(flop, loaf, stretch, groom, tall);
      const sit = c.mode === "idle" && c.stay ? 1 - pose : 0;

      m.root.position.y = c.hopY + bk * 0.42;
      if (c.happy > 0 && !flop) m.root.position.y += Math.abs(Math.sin(t * 10)) * 0.05 * (1 - pose);
      m.root.rotation.y = c.facing + (bk ? bk * Math.sin(c.bk * 9) * 0.6 : 0);
      // flopped onto its side, a back foot twitching
      m.root.rotation.z = c.fall * 1.45 + flop * (1.45 + Math.sin(t * 1.6 + c.phase) * 0.05) + bk * 0.35;
      // lifted and shifted so it lies on its side right where it was
      m.root.position.y += flop * 0.16;
      m.root.position.x += Math.cos(c.facing) * flop * 0.17;
      m.root.position.z -= Math.sin(c.facing) * flop * 0.17;
      m.body.position.y = 0.18 - loaf * 0.05 + groom * 0.03 + sit * 0.02 + tall * 0.1;
      // sitting up tall on its back feet to look around, or leaning back to wash
      m.body.rotation.x = hopPitch - groom * 0.55 - sit * 0.25 + stretch * 0.12 - tall * 0.95 - bk * 0.3;
      // long in the air, bunched up on landing, flat as a loaf
      m.body.scale.set(1 + loaf * 0.1, (1 - air * 0.08 + gather * 0.06) * (1 - loaf * 0.14), (1 + air * 0.18 - gather * 0.1) * (1 + stretch * 0.22));
      m.paws.forEach((pw, i) => {
        // reaching out to land, tucked under after; at the chest when sitting up
        const hopPaw = airborne ? -1.0 * Math.max(0, (u - 0.2) / 0.35) : moving ? 0.35 * gather : 0;
        pw.rotation.x = hopPaw - stretch * 1.1 - groom * (2.0 + Math.sin(t * 7 + i * 0.6) * 0.3) + flop * 0.5 - tall * 0.7 - bk * 0.6;
        pw.scale.y = 1 - loaf * 0.6;
      });
      m.feet.forEach((f, i) => {
        // push off behind, then swing forward past the front paws
        const hopFoot = airborne ? 0.9 * air : moving ? -0.5 * gather : 0;
        f.rotation.x = hopFoot + flop * (0.7 + (i ? Math.max(0, Math.sin(t * 5)) * 0.4 : 0)) + stretch * 0.5 + bk * 0.9 - tall * 0.2;
      });
      // ears: back in the air and when relaxed, up and turning when alert, and a flick now and then
      const earBack = Math.max(loaf, stretch * 0.8, flop * 0.6);
      m.ears.forEach((e, i) => {
        const flick = Math.max(0, Math.sin(t * 0.9 + i * 2.3 + c.phase) - 0.96) * 25;
        if (m.lop) e.rotation.x = Math.sin(t * 2 + i) * 0.04 + air * 0.2 + flick * 0.15;
        else {
          e.rotation.x = -0.15 - air * 0.4 - earBack * 0.9 + tall * 0.15 + Math.sin(t * 3 + i) * 0.04 - flick * 0.35;
          e.rotation.y = (i ? -1 : 1) * (Math.sin(t * 0.6 + i + c.phase) * 0.25 * (1 - earBack) + flick * 0.5);
        }
      });
      // the nose never stops (little bursts), the head scans about while sitting tall
      const twitching = c.mode === "idle" && Math.sin(t * 0.8 + c.phase) > -0.3;
      if (m.nose) m.nose.scale.setScalar(1 + (twitching ? Math.max(0, Math.sin(t * 22)) * 0.35 : 0));
      m.head.rotation.x = (twitching ? Math.sin(t * 22) * 0.015 : 0) + groom * (0.35 + Math.sin(t * 7) * 0.1) + stretch * 0.25 - flop * 0.2 + tall * 0.75 - hopPitch * 0.5;
      m.head.rotation.y = c.happy > 0 && !flop ? Math.sin(t * 6) * 0.2 : tall * Math.sin(t * 0.9 + c.phase) * 0.7 + (c.mode === "idle" ? Math.sin(t * 0.4 + c.phase * 3) * 0.25 * (1 - pose) : 0);
    } else if (c.kind === "deer") {
      c.phase += dt * (1.5 + s * 2.4);
      const amp = Math.min(1, s / 1.0) * (s > 3 ? 0.7 : 0.4);
      m.legs.forEach((l, i) => (l.rotation.x = Math.sin(c.phase + (i === 0 || i === 3 ? 0 : Math.PI)) * amp));
      m.body.position.y = 0.95 + (s > 3 ? Math.abs(Math.sin(c.phase)) * 0.12 : 0);
      // graze when idle
      const graze = c.mode === "idle" && pd > 5 ? 1 : 0;
      m.neck.rotation.x += ((graze ? 1.3 : 0) - m.neck.rotation.x) * (1 - Math.exp(-dt * 2.5));
      m.head.rotation.y = graze ? 0 : Math.sin(t * 0.5 + c.phase) * 0.4;
    } else if (c.kind === "boy") {
      c.avatar.update(dt, s, false, 0);
      const b = c.bubble;
      if (b.userData.life > 0) {
        b.userData.life -= dt;
        b.material.opacity = Math.min(1, b.userData.life * 3);
      } else b.material.opacity = 0;
      b.position.set(c.pos.x, 2.4, c.pos.z);
      this.boyTag?.position.set(c.pos.x, 1.95, c.pos.z);
    }
  }
}

function turnTo(a, b, k) {
  const d = Math.atan2(Math.sin(b - a), Math.cos(b - a));
  return a + d * Math.min(1, k);
}
