// The finishing touches on the picture: a soft glow around everything that shines (lamps,
// fairy lights, the crystal heart, fireflies, lanterns), smooth edges, and a little light
// from the island's own sky on every surface so the colours sit together. The colours,
// tone and exposure are exactly the island's own: the last step applies the same tone
// mapping the plain picture used.
import * as THREE from "three";
import { EffectComposer } from "three/examples/jsm/postprocessing/EffectComposer.js";
import { RenderPass } from "three/examples/jsm/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/examples/jsm/postprocessing/UnrealBloomPass.js";
import { OutputPass } from "three/examples/jsm/postprocessing/OutputPass.js";

// how strongly things glow: more at night, when the lights matter
const GLOW = { day: 0, night: 0.07 };
// only what shines brighter than a white wall in full light glows (worked out from the
// theme's own sun and sky light), so walls, paths and grass never do: just the lights
const ABOVE_LIT = 1.4;
// how much of the sky's light lands on surfaces (a hint: the island's own lights lead)
const SKY_LIGHT = 0.14;

export class Look {
  constructor(renderer, scene, camera, { phone = false } = {}) {
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
    this.phone = phone;
    this.glowOn = true;
    const target = new THREE.WebGLRenderTarget(1, 1, {
      type: THREE.HalfFloatType,
      // smooth edges (the canvas's own smoothing doesn't reach a picture drawn off-screen)
      samples: phone ? 2 : 4,
    });
    this.composer = new EffectComposer(renderer, target);
    this.composer.addPass(new RenderPass(scene, camera));
    this.bloom = new UnrealBloomPass(new THREE.Vector2(1, 1), GLOW.night, 0.16, 2);
    this.composer.addPass(this.bloom);
    this.composer.addPass(new OutputPass());
    this.pmrem = new THREE.PMREMGenerator(renderer);
    this.envTarget = null;
    this.envKey = "";
    this.skyScene = null;
  }

  setSize(w, h, ratio) {
    this.composer.setPixelRatio(ratio);
    // (the glow works itself out at half size: it's soft anyway)
    this.composer.setSize(w, h);
  }

  // the theme / time of day / weather changed
  setPalette(p) {
    const night = THREE.MathUtils.clamp(p.night ?? 0.5, 0, 1);
    this.bloom.strength = THREE.MathUtils.lerp(GLOW.day, GLOW.night, night) * (this.phone ? 0.85 : 1);
    const lit = ((p.sunI ?? 1.5) + (p.hemiI ?? 1)) * 0.9;
    this.bloom.threshold = lit * ABOVE_LIT;
    this.skyLight(p);
  }

  // a little sky made from the theme's own colours, turned into light for every surface
  skyLight(p) {
    const sky = p.sky || ["#2a1856", "#8a5bb0", "#ffb1c8"];
    const key = [...sky, p.hemiGround].join();
    if (key === this.envKey) return;
    this.envKey = key;
    if (!this.skyScene) {
      const mat = new THREE.ShaderMaterial({
        side: THREE.BackSide,
        depthWrite: false,
        uniforms: {
          top: { value: new THREE.Color() },
          mid: { value: new THREE.Color() },
          low: { value: new THREE.Color() },
          ground: { value: new THREE.Color() },
        },
        vertexShader: "varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }",
        fragmentShader: `uniform vec3 top; uniform vec3 mid; uniform vec3 low; uniform vec3 ground; varying vec3 vDir;
          void main(){
            float y = vDir.y;
            vec3 c = y > 0.0 ? mix(low, mix(mid, top, smoothstep(0.25, 1.0, y)), smoothstep(0.0, 0.25, y)) : mix(low, ground, smoothstep(0.0, -0.3, y));
            gl_FragColor = vec4(c, 1.0);
          }`,
      });
      this.skyScene = new THREE.Scene();
      this.skyScene.add(new THREE.Mesh(new THREE.SphereGeometry(10, 32, 16), mat));
    }
    const u = this.skyScene.children[0].material.uniforms;
    u.top.value.set(sky[0]);
    u.mid.value.set(sky[1]);
    u.low.value.set(sky[2]);
    u.ground.value.set(p.hemiGround || "#556644");
    const next = this.pmrem.fromScene(this.skyScene, 0, 0.1, 50);
    this.envTarget?.dispose();
    this.envTarget = next;
    this.scene.environment = next.texture;
    this.scene.environmentIntensity = SKY_LIGHT;
  }

  // a slow computer drops the glow before anything else
  setGlow(on) {
    this.glowOn = on;
    this.bloom.enabled = on;
  }

  // everything off: the plain picture, exactly as before
  setEnabled(on) {
    this.enabled = on;
    this.scene.environment = on ? this.envTarget?.texture || null : null;
  }

  render() {
    if (this.enabled === false) this.renderer.render(this.scene, this.camera);
    else this.composer.render();
  }

  dispose() {
    this.scene.environment = null;
    this.envTarget?.dispose();
    this.pmrem.dispose();
    this.skyScene?.children[0].geometry.dispose();
    this.skyScene?.children[0].material.dispose();
    for (const pass of this.composer.passes) pass.dispose?.();
    this.composer.renderTarget1.dispose();
    this.composer.renderTarget2.dispose();
  }
}
