// Procedural textures painted on canvas: every surface in the world comes
// from here, so nothing needs to be downloaded. All are tileable.
import * as THREE from "three";

const cache = new Map();
let SIZE = 256;
let maxAniso = 4;

export function configureTextures({ lowEnd, renderer }) {
  SIZE = lowEnd ? 128 : 256;
  maxAniso = Math.min(8, renderer.capabilities.getMaxAnisotropy());
}

function rng(seed) {
  let s = (seed * 2654435761) >>> 0 || 1;
  return () => {
    s ^= s << 13;
    s ^= s >>> 17;
    s ^= s << 5;
    return (s >>> 0) / 4294967296;
  };
}

// periodic value noise, so the textures tile without seams
function tileNoise(size, cells, seed) {
  const r = rng(seed);
  const g = new Float32Array(cells * cells);
  for (let i = 0; i < g.length; i++) g[i] = r();
  return (x, y) => {
    const fx = (x / size) * cells;
    const fy = (y / size) * cells;
    const x0 = Math.floor(fx);
    const y0 = Math.floor(fy);
    const tx = fx - x0;
    const ty = fy - y0;
    const sx = tx * tx * (3 - 2 * tx);
    const sy = ty * ty * (3 - 2 * ty);
    const xa = ((x0 % cells) + cells) % cells;
    const ya = ((y0 % cells) + cells) % cells;
    const xb = (xa + 1) % cells;
    const yb = (ya + 1) % cells;
    const a = g[ya * cells + xa];
    const b = g[ya * cells + xb];
    const c = g[yb * cells + xa];
    const d = g[yb * cells + xb];
    return a + (b - a) * sx + (c - a) * sy + (a - b - c + d) * sx * sy;
  };
}

function fbm(size, seed, base = 4) {
  const layers = [1, 2, 4, 8].map((m, i) => tileNoise(size, base * m, seed + i * 977));
  return (x, y) =>
    layers[0](x, y) * 0.5 + layers[1](x, y) * 0.25 + layers[2](x, y) * 0.15 + layers[3](x, y) * 0.1;
}

const hexToRgb = (hex) => {
  const c = new THREE.Color(hex);
  return [c.r * 255, c.g * 255, c.b * 255];
};

function paintPixels(ctx, size, fn) {
  const img = ctx.createImageData(size, size);
  const d = img.data;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const i = (y * size + x) * 4;
      const [r, g, b] = fn(x, y);
      d[i] = r;
      d[i + 1] = g;
      d[i + 2] = b;
      d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
}

const mix = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
const shade = (c, k) => [c[0] * k, c[1] * k, c[2] * k];

const painters = {
  grass(ctx, s, [a, b]) {
    const n = fbm(s, 11, 4);
    const fine = tileNoise(s, 64, 5);
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    paintPixels(ctx, s, (x, y) => shade(mix(ca, cb, n(x, y)), 0.88 + fine(x, y) * 0.22));
    const r = rng(3);
    for (let i = 0; i < s * 1.4; i++) {
      const x = r() * s;
      const y = r() * s;
      ctx.strokeStyle = `rgba(255,255,255,${0.05 + r() * 0.08})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + (r() - 0.5) * 3, y - 2 - r() * 4);
      ctx.stroke();
    }
  },
  wood(ctx, s, [a, b]) {
    const n = fbm(s, 21, 2);
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    const rows = 4;
    const r = rng(9);
    const tints = Array.from({ length: rows }, () => 0.85 + r() * 0.3);
    const offsets = Array.from({ length: rows }, () => r() * s);
    paintPixels(ctx, s, (x, y) => {
      const row = Math.floor((y / s) * rows);
      const ry = (y / s) * rows - row;
      const grain = Math.sin(((x + offsets[row]) / s) * Math.PI * 6 + n(x, y) * 14 + row) * 0.5 + 0.5;
      let c = shade(mix(ca, cb, grain * 0.6 + n(x, y) * 0.4), tints[row]);
      if (ry < 0.04 || ry > 0.96) c = shade(c, 0.55);
      const seam = ((x + offsets[row]) % s) / s;
      if (seam < 0.012) c = shade(c, 0.6);
      return c;
    });
  },
  tiles(ctx, s, [a, b]) {
    const n = fbm(s, 31, 4);
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    const cells = 4;
    paintPixels(ctx, s, (x, y) => {
      const cx = Math.floor((x / s) * cells);
      const cy = Math.floor((y / s) * cells);
      const fx = (x / s) * cells - cx;
      const fy = (y / s) * cells - cy;
      const base = (cx + cy) % 2 ? ca : mix(ca, cb, 0.5);
      let c = shade(base, 0.9 + n(x, y) * 0.2);
      if (fx < 0.05 || fy < 0.05) c = shade(cb, 0.7);
      return c;
    });
  },
  cobble(ctx, s, [a, b]) {
    ctx.fillStyle = b;
    ctx.fillRect(0, 0, s, s);
    const r = rng(41);
    const ca = hexToRgb(a);
    const rows = 5;
    const h = s / rows;
    for (let row = 0; row < rows; row++) {
      let x = row % 2 ? -h * 0.5 : 0;
      while (x < s) {
        const w = h * (0.8 + r() * 0.6);
        const k = 0.8 + r() * 0.35;
        ctx.fillStyle = `rgb(${ca[0] * k | 0},${ca[1] * k | 0},${ca[2] * k | 0})`;
        const rad = h * 0.3;
        for (const dx of [0, s, -s]) {
          ctx.beginPath();
          ctx.roundRect(x + dx + 2, row * h + 2, w - 4, h - 4, rad);
          ctx.fill();
        }
        x += w;
      }
    }
    noiseOverlay(ctx, s, 51, 0.12);
  },
  wallpaper(ctx, s, [a, b]) {
    ctx.fillStyle = a;
    ctx.fillRect(0, 0, s, s);
    ctx.fillStyle = b;
    const stripes = 8;
    for (let i = 0; i < stripes; i += 2) ctx.fillRect((i / stripes) * s, 0, s / stripes / 3, s);
    ctx.globalAlpha = 0.55;
    const step = s / 4;
    for (let y = 0; y < 4; y++) {
      for (let x = 0; x < 4; x++) {
        heart(ctx, x * step + step * 0.5 + (y % 2 ? step / 2 : 0), y * step + step * 0.5, s / 28, b);
      }
    }
    ctx.globalAlpha = 1;
    noiseOverlay(ctx, s, 61, 0.06);
  },
  fabric(ctx, s, [a, b]) {
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    const n = fbm(s, 71, 8);
    paintPixels(ctx, s, (x, y) => {
      const w = ((Math.floor(x / 2) + Math.floor(y / 2)) % 2) * 0.5;
      const check = (Math.floor(x / (s / 4)) + Math.floor(y / (s / 4))) % 2;
      return shade(mix(ca, cb, check * 0.6 + w * 0.15), 0.9 + n(x, y) * 0.18);
    });
  },
  shingles(ctx, s, [a, b]) {
    ctx.fillStyle = b;
    ctx.fillRect(0, 0, s, s);
    const r = rng(81);
    const ca = hexToRgb(a);
    const rows = 6;
    const h = s / rows;
    const cols = 6;
    const w = s / cols;
    for (let row = 0; row < rows + 1; row++) {
      for (let col = -1; col < cols + 1; col++) {
        const k = 0.82 + r() * 0.3;
        ctx.fillStyle = `rgb(${ca[0] * k | 0},${ca[1] * k | 0},${ca[2] * k | 0})`;
        const x = col * w + (row % 2 ? w / 2 : 0);
        const y = row * h;
        ctx.beginPath();
        ctx.moveTo(x + 1, y - h * 0.2);
        ctx.lineTo(x + w - 1, y - h * 0.2);
        ctx.lineTo(x + w - 1, y + h * 0.55);
        ctx.quadraticCurveTo(x + w / 2, y + h * 1.1, x + 1, y + h * 0.55);
        ctx.closePath();
        ctx.fill();
      }
    }
    noiseOverlay(ctx, s, 91, 0.1);
  },
  stone(ctx, s, [a, b]) {
    const n = fbm(s, 101, 3);
    const fine = tileNoise(s, 48, 7);
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    paintPixels(ctx, s, (x, y) => {
      const band = Math.sin((y / s) * Math.PI * 10 + n(x, y) * 9) * 0.5 + 0.5;
      return shade(mix(ca, cb, band * 0.5 + n(x, y) * 0.5), 0.85 + fine(x, y) * 0.25);
    });
  },
  plaster(ctx, s, [a, b]) {
    const n = fbm(s, 111, 4);
    const ca = hexToRgb(a);
    const cb = hexToRgb(b);
    paintPixels(ctx, s, (x, y) => mix(ca, cb, n(x, y) * 0.7));
    // a beam along the bottom edge for a cottage look
    ctx.fillStyle = "rgba(90,60,45,0.35)";
    ctx.fillRect(0, s * 0.94, s, s * 0.06);
  },
  rug(ctx, s, [a, b]) {
    ctx.fillStyle = a;
    ctx.fillRect(0, 0, s, s);
    ctx.strokeStyle = b;
    ctx.lineWidth = s / 24;
    for (let i = 1; i < 5; i++) {
      ctx.beginPath();
      ctx.arc(s / 2, s / 2, (i / 5) * s * 0.48, 0, Math.PI * 2);
      ctx.stroke();
    }
    heart(ctx, s / 2, s / 2, s / 10, b);
    noiseOverlay(ctx, s, 121, 0.1);
  },
};

function heart(ctx, x, y, r, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x, y + r * 0.9);
  ctx.bezierCurveTo(x - r * 1.6, y - r * 0.2, x - r * 0.6, y - r * 1.4, x, y - r * 0.4);
  ctx.bezierCurveTo(x + r * 0.6, y - r * 1.4, x + r * 1.6, y - r * 0.2, x, y + r * 0.9);
  ctx.fill();
}

function noiseOverlay(ctx, s, seed, strength) {
  const n = fbm(s, seed, 8);
  const img = ctx.getImageData(0, 0, s, s);
  const d = img.data;
  for (let y = 0; y < s; y++) {
    for (let x = 0; x < s; x++) {
      const i = (y * s + x) * 4;
      const k = 1 + (n(x, y) - 0.5) * strength * 2;
      d[i] *= k;
      d[i + 1] *= k;
      d[i + 2] *= k;
    }
  }
  ctx.putImageData(img, 0, 0);
}

export function texture(kind, colors, repeat = 1) {
  const key = `${kind}|${colors.join(",")}|${repeat}`;
  if (cache.has(key)) return cache.get(key);
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = SIZE;
  const ctx = canvas.getContext("2d");
  painters[kind](ctx, SIZE, colors);
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeat, repeat);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = maxAniso;
  cache.set(key, tex);
  return tex;
}

// A canvas for signs and in-world screens that we redraw when text changes.
export function textCanvas(width, height) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = maxAniso;
  return { canvas, ctx: canvas.getContext("2d"), tex };
}

// photos and paintings travel between us as data URLs; only real images are
// ever shown, linked or drawn (never a script link)
export const isImageData = (src) => typeof src === "string" && /^data:image\/(png|jpe?g|webp|gif);base64,[a-z0-9+/=]+$/i.test(src);

export const FONT = '"Quicksand", "Noto Sans", "Noto Sans Symbols 2", "Noto Sans Batak", "Apple Color Emoji", "Noto Color Emoji", "Segoe UI Symbol", sans-serif';

export function wrapText(ctx, text, maxWidth) {
  const out = [];
  for (const para of String(text).split(/\n+/)) {
    const words = para.split(/\s+/).filter(Boolean);
    let line = "";
    for (const word of words) {
      const test = line ? `${line} ${word}` : word;
      if (ctx.measureText(test).width > maxWidth && line) {
        out.push(line);
        line = word;
      } else line = test;
    }
    if (line) out.push(line);
  }
  return out;
}

// a repeating texture painted onto a fresh canvas
export function canvasTex(w, h, paint, rx = 1, ry = 1) {
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  paint(c.getContext("2d"), w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(rx, ry);
  t.anisotropy = 4;
  return t;
}
