// Fewer draw calls: once a place is built, its pieces that never move are merged
// into one mesh per material. It watches for a moment first, so anything an
// animation moves (or that's clickable, see-through, or marked live) stays as it was.
import * as THREE from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";

// is o, or anything between it and root, marked as something that moves later on?
function isLive(o, root) {
  for (let p = o; p && p !== root; p = p.parent) if (p.userData.live) return true;
  return false;
}

function snapshot(root) {
  root.updateMatrixWorld(true);
  const inv = root.matrixWorld.clone().invert();
  const out = new Map();
  root.traverse((o) => {
    if (o.isMesh && !o.isInstancedMesh && !o.isSkinnedMesh) out.set(o, new THREE.Matrix4().multiplyMatrices(inv, o.matrixWorld));
  });
  return out;
}

export function bakeWhenSettled(root, wait = 1200) {
  const before = snapshot(root);
  setTimeout(() => {
    if (!root.parent) return; // gone already
    const after = snapshot(root);
    const groups = new Map();
    for (const [o, m0] of before) {
      const m1 = after.get(o);
      if (!m1 || !o.parent || !o.visible || !m0.equals(m1)) continue; // moved, or gone
      const mat = o.material;
      // anything carrying its own data (clickable, a picture, a glow) is looked up later: leave it
      if (!mat || Array.isArray(mat) || mat.transparent || Object.keys(o.userData).length || isLive(o, root)) continue;
      if (m1.determinant() <= 0) continue; // mirrored pieces would turn inside out
      const geo = o.geometry;
      if (!geo?.attributes?.position || !geo.attributes.normal || geo.morphAttributes?.position) continue;
      const key = `${mat.uuid}|${Object.keys(geo.attributes).sort().join(",")}|${o.castShadow}|${o.receiveShadow}|${o.renderOrder}`;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push([o, m1]);
    }
    for (const list of groups.values()) {
      if (list.length < 2) continue;
      const geos = list.map(([o, m]) => (o.geometry.index ? o.geometry.toNonIndexed() : o.geometry.clone()).applyMatrix4(m));
      const merged = mergeGeometries(geos);
      for (const g of geos) g.dispose();
      if (!merged) continue;
      const first = list[0][0];
      const mesh = new THREE.Mesh(merged, first.material);
      mesh.castShadow = first.castShadow;
      mesh.receiveShadow = first.receiveShadow;
      mesh.renderOrder = first.renderOrder;
      root.add(mesh);
      for (const [o] of list) o.parent.remove(o);
    }
  }, wait);
}
