// Duck lake: a round-ish lake with a sandy shore, reeds, lily pads, a little wooden
// jetty and a bench, and ducks paddling about, each with a line of ducklings behind.
import * as THREE from "three";
import { std, windify, mulberry, put } from "./world.js";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { bakeWhenSettled } from "./bake.js";

const TAU = Math.PI * 2;
const CZ = -1.2; // the lake's middle, a little back from the place's middle (the path comes in at +z)
const shoreR = (a) => 7.6 + Math.sin(a * 3 + 1) * 0.7 + Math.sin(a * 5 + 2.3) * 0.35;
const DOCK_W = 0.75; // half the jetty's width
const flat = (c, k) => std(c, { polygonOffset: true, polygonOffsetFactor: -k, polygonOffsetUnits: -k * 2 });

function blob(grow, n = 64) {
  const s = new THREE.Shape();
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * TAU;
    const r = shoreR(a) + grow;
    const x = Math.sin(a) * r, y = -(Math.cos(a) * r + CZ);
    if (i === 0) s.moveTo(x, y);
    else s.lineTo(x, y);
  }
  return new THREE.ShapeGeometry(s, 1);
}
const BOX = new THREE.BoxGeometry(1, 1, 1);
const BALL = new THREE.IcosahedronGeometry(1, 1);
const ROCK = new THREE.IcosahedronGeometry(1, 0);
const CYL = new THREE.CylinderGeometry(1, 1, 1, 7);
const CONE = new THREE.ConeGeometry(1, 1, 5);

function makeDuck(kind) {
  const g = new THREE.Group();
  const body = new THREE.Group();
  g.add(body);
  const s = kind === "baby" ? 0.45 : 1;
  const main = std(kind === "baby" ? "#ffe066" : kind === "drake" ? "#efe6da" : "#c89b72");
  put(body, BALL, main, 0, 0.12 * s, 0, { sx: 0.2 * s, sy: 0.14 * s, sz: 0.3 * s });
  put(body, BALL, main, 0, 0.2 * s, -0.24 * s, { sx: 0.08 * s, sy: 0.07 * s, sz: 0.12 * s, rx: -0.6 });
  if (kind !== "baby") for (const k of [-1, 1]) put(body, BALL, std(kind === "drake" ? "#8a7a6a" : "#9a7050"), k * 0.17, 0.16, -0.02, { sx: 0.05, sy: 0.08, sz: 0.2 });
  const head = new THREE.Group();
  head.position.set(0, 0.3 * s, 0.2 * s);
  body.add(head);
  put(head, BALL, std(kind === "drake" ? "#2f8f6a" : kind === "baby" ? "#ffe066" : "#b88a62"), 0, 0.06 * s, 0, { s: 0.11 * s });
  if (kind === "drake") put(head, CYL, std("#ffffff"), 0, -0.04, 0, { sx: 0.08, sy: 0.02, sz: 0.08 });
  put(head, BOX, std("#ffa62b"), 0, 0.03 * s, 0.12 * s, { sx: 0.08 * s, sy: 0.03 * s, sz: 0.1 * s });
  for (const k of [-1, 1]) put(head, BALL, std("#1f1a24"), k * 0.07 * s, 0.09 * s, 0.07 * s, { s: 0.018 * s });
  return { g, body, head, s };
}

export class Lake {
  constructor({ world, toast, audio }) {
    Object.assign(this, { world, toast, audio });
    this.room = world.rooms.get("lake");
    if (!this.room) return;
    this.still = new THREE.Group();
    this.live = new THREE.Group();
    // the whole lake is turned a little (def.turn) so its jetty faces the path coming in
    // past toto's gift rather than the gift's back wall
    this.turn = this.room.def.turn || 0;
    for (const g of [this.still, this.live]) g.rotation.y = this.turn;
    this.room.group.add(this.still, this.live);
    this.room.far = [[this.live, 130]]; // the ducks aren't drawn from right across the island (world.js)
    this.build();
    bakeWhenSettled(this.still);
    // the water (not the jetty): nowhere to land when travelling
    const v = new THREE.Vector3();
    world.isWater = (x, z) => {
      this.live.worldToLocal(v.set(x, 0, z));
      if (Math.abs(v.x) < DOCK_W + 0.2 && v.z > shoreR(0) + CZ - 3.6) return false;
      const dz = v.z - CZ;
      return Math.hypot(v.x, dz) < shoreR(Math.atan2(v.x, dz)) + 0.3;
    };
  }
  // the lake's own (turned) frame into the place's frame, and into the world
  rot(x, z) {
    const c = Math.cos(this.turn), s = Math.sin(this.turn);
    return [x * c + z * s, -x * s + z * c];
  }
  at(x, z) {
    return this.world.toWorld(this.room, ...this.rot(x, z).flatMap((v, i) => (i ? [0, v] : [v])));
  }
  build() {
    this.waterTime = { value: 0 };
    const S = this.still;
    const w = this.world;
    const room = this.room;
    // shore, shallows, deep water
    put(S, blob(1.5), flat("#f1dfb8", 1), 0, 0.04, 0, { rx: -Math.PI / 2, cast: false });
    put(S, blob(0.6), flat("#e3cc9c", 2), 0, 0.055, 0, { rx: -Math.PI / 2, cast: false });
    put(S, blob(0), flat("#86d0ea", 3), 0, 0.07, 0, { rx: -Math.PI / 2, cast: false });
    this.deep = put(this.live, blob(-1.6), new THREE.MeshStandardMaterial({ color: "#45a9d8", roughness: 0.15, metalness: 0.1, flatShading: true, emissive: "#1d6e9c", emissiveIntensity: 0, polygonOffset: true, polygonOffsetFactor: -4, polygonOffsetUnits: -8 }), 0, 0.08, 0, { rx: -Math.PI / 2, cast: false });
    ripple(this.deep.material, this.waterTime);

    // no walls round the water: you can wade right in
    const r0 = shoreR(0);
    const tip = r0 + CZ - 3.2;

    // the jetty
    const wood = std("#c98a5a"), dark = std("#8a5a3c");
    // the jetty sits only a hand above the water, so it's pulled forward in depth even more
    // than the water is: from across the lake its far end never sinks under the surface
    const over = { polygonOffset: true, polygonOffsetFactor: -8, polygonOffsetUnits: -16 };
    const jWood = std("#c98a5a", over), jDark = std("#8a5a3c", over);
    const zFrom = r0 + CZ + 0.8, zTo = tip - 0.25;
    for (let z = zFrom; z > zTo; z -= 0.34) put(S, BOX, jWood, 0, 0.1, z, { sx: DOCK_W * 2 + 0.1, sy: 0.07, sz: 0.3, ry: (Math.round(z * 7) % 3) * 0.01 });
    for (const x of [-DOCK_W, DOCK_W]) for (const z of [zFrom - 0.5, (zFrom + zTo) / 2, zTo + 0.15]) put(S, CYL, jDark, x, 0.15, z, { sx: 0.08, sy: 0.5, sz: 0.08 });
    put(S, CYL, jDark, DOCK_W - 0.05, 0.5, zTo + 0.15, { sx: 0.07, sy: 0.6, sz: 0.07 });

    this.lamp = put(S, BALL, std("#fff3c4", { emissive: "#ffcf7a", emissiveIntensity: 0.6 }), DOCK_W - 0.05, 0.88, zTo + 0.15, { s: 0.1 });
    w.seat(room, this.rot(0, zTo + 0.25), Math.PI + this.turn, 0.16, "sit on the jetty 🦆");
    this.jetty = this.at(0, zTo);

    // a bench on the shore, looking at the water
    const bx = -4.2, bz = shoreR(-0.55) * Math.cos(-0.55) + CZ + 2.6;
    const bench = new THREE.Group();
    bench.position.set(bx, 0, bz);
    bench.rotation.set(0, Math.atan2(0 - bx, CZ - bz), 0);
    S.add(bench);
    put(bench, BOX, wood, 0, 0.46, 0, { sx: 1.7, sy: 0.08, sz: 0.5 });
    put(bench, BOX, wood, 0, 0.84, -0.24, { sx: 1.7, sy: 0.42, sz: 0.06, rx: -0.12 });
    for (const lx of [-0.75, 0.75]) put(bench, BOX, dark, lx, 0.23, 0, { sx: 0.08, sy: 0.46, sz: 0.46 });
    put(bench, BOX, std("#bfe6f7"), 0.45, 0.66, -0.15, { sx: 0.34, sy: 0.3, sz: 0.12, rx: -0.25, rz: -0.15 });
    const face = bench.rotation.y;
    for (const o of [-0.42, 0.42]) w.seat(room, this.rot(bx + Math.cos(face) * o, bz - Math.sin(face) * o), face + this.turn, 0.5, "watch the ducks 🦆");
    const back = [bx - Math.sin(face) * 0.28, bz - Math.cos(face) * 0.28];
    const a = this.at(back[0] - Math.cos(face) * 0.9, back[1] + Math.sin(face) * 0.9), b = this.at(back[0] + Math.cos(face) * 0.9, back[1] - Math.sin(face) * 0.9);
    w.addWallSegment(a.x, a.z, b.x, b.z, 1);

    // stones round the edge, reeds and cattails in clumps, lily pads with flowers
    const R = mulberry(31);
    const stone = ["#d9d2cc", "#c9c0bb", "#e6ded6"].map((c) => std(c));
    for (let k = 0; k < 34; k++) {
      const a = R() * TAU;
      if (Math.abs(Math.atan2(Math.sin(a), Math.cos(a))) < 0.25) continue;
      const r = shoreR(a) + 0.15 + R() * 0.5;
      put(S, ROCK, stone[k % 3], Math.sin(a) * r, 0.06, Math.cos(a) * r + CZ, { sx: 0.18 + R() * 0.2, sy: 0.1 + R() * 0.1, sz: 0.16 + R() * 0.2, ry: R() * 6 });
    }
    const reedMat = windify(std("#6fae5a", { unique: true }), 0.08, 1.4);
    const reedGeos = [];
    const tops = [];
    for (let c = 0; c < 9; c++) {
      const a = 0.6 + c * ((TAU - 1.2) / 8) + (R() - 0.5) * 0.3;
      const r = shoreR(a) - 0.2;
      const cx = Math.sin(a) * r, cz = Math.cos(a) * r + CZ;
      for (let k = 0; k < 7; k++) {
        const x = cx + (R() - 0.5) * 0.9, z = cz + (R() - 0.5) * 0.9;
        const hh = 0.7 + R() * 0.7;
        const g = new THREE.ConeGeometry(0.03, hh, 3).translate(0, hh / 2, 0);
        g.rotateZ((R() - 0.5) * 0.25);
        g.translate(x, 0.05, z);
        reedGeos.push(g);
        if (k % 3 === 0) tops.push([x, hh * 0.85, z]);
      }
    }
    const reeds = new THREE.Mesh(mergeGeometries(reedGeos), reedMat);
    reeds.castShadow = true;
    S.add(reeds);
    for (const [x, y, z] of tops) put(S, CYL, std("#8a5a3c"), x, y + 0.05, z, { sx: 0.04, sy: 0.18, sz: 0.04 });
    const pad = std("#6fbf6c", { side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: -8, polygonOffsetUnits: -16 }); // always over the water
    const padGeo = new THREE.CircleGeometry(1, 9, 0.4, TAU - 0.4);
    for (let k = 0; k < 18; k++) {
      const a = R() * TAU;
      if (Math.abs(Math.atan2(Math.sin(a), Math.cos(a))) < 0.4) continue;
      const r = shoreR(a) - 1.2 - R() * 2;
      const x = Math.sin(a) * r, z = Math.cos(a) * r + CZ;
      put(S, padGeo, pad, x, 0.13, z, { s: 0.38 + R() * 0.22, rx: -Math.PI / 2, rz: R() * 6, cast: false });
      if (k % 3 === 0) {
        for (let p = 0; p < 6; p++) put(S, CONE, std(k % 2 ? "#ffc4dc" : "#ffffff"), x + Math.sin(p) * 0.05, 0.19, z + Math.cos(p) * 0.05, { sx: 0.04, sy: 0.12, sz: 0.04, rx: Math.sin(p) * 0.5, rz: Math.cos(p) * 0.5 });
        put(S, BALL, std("#ffe066"), x, 0.2, z, { s: 0.03 });
      }
    }

    // the ducks, each with its own little line of ducklings paddling behind
    this.ducks = [];
    const add = (kind, lane, speed, off) => {
      const d = makeDuck(kind);
      d.g.userData.live = true;
      this.live.add(d.g);
      Object.assign(d, { kind, lane, speed, t: off, trail: [] });
      this.ducks.push(d);
      return d;
    };
    const family = (kind, lane, speed, off, n) => {
      const mum = add(kind, lane, speed, off);
      mum.babies = Array.from({ length: n }, () => add("baby", 0, 0, 0));
      // the way she's already come, so her ducklings start out in line behind her
      for (let k = 0, t = off; mum.trail.length < 80 && k < 6000; k++, t -= Math.sign(speed) * 0.002) {
        const p = this.lanePos(lane, t), q = mum.trail[mum.trail.length - 1];
        if (!q || Math.hypot(p[0] - q[0], p[1] - q[1]) > 0.04) mum.trail.push(p);
      }
      mum.g.position.set(mum.trail[0][0], 0.08, mum.trail[0][1]);
    };
    family("hen", 0.62, 0.05, 0, 4);
    family("drake", 0.45, -0.07, 2, 3);
    family("drake", 0.75, 0.04, 3.5, 2);
    family("hen", 0.3, -0.09, 5, 3);
    this.ripples = [];
    const rippleMat = new THREE.MeshBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.5, depthWrite: false });
    const rippleGeo = new THREE.RingGeometry(0.85, 1, 20);
    for (let i = 0; i < 14; i++) {
      const m = new THREE.Mesh(rippleGeo, rippleMat.clone());
      m.rotation.x = -Math.PI / 2;
      m.visible = false;
      m.userData.live = true;
      this.live.add(m);
      this.ripples.push({ m, life: 0 });
    }
    this.nextRipple = 0;
    const it = { id: "lake-ducks", icon: "", pos: this.at(0, r0 + CZ + 1.2).setY(0), radius: 2.2, action: { type: "lake" }, room: "lake", hits: [] };
    Object.defineProperty(it, "label", { value: "feed the ducks 🍞", enumerable: true });
    w.interactables.push(it);
  }
  // a wobbly loop round the lake, lane 0 (middle) to 1 (the edge)
  lanePos(lane, t) {
    const a = t;
    const r = (shoreR(a) - 1.4) * lane + Math.sin(t * 2.3) * 0.3;
    return [Math.sin(a) * r, Math.cos(a) * r + CZ];
  }
  feed() {
    this.audio?.sfx("pop");
    this.fed = 6;
    this.toast?.(["quack quack! 🦆", "the ducklings paddle over as fast as they can 🐥", "the ducks gobble up the crumbs ♡"][Math.floor(Math.random() * 3)]);
  }
  // the point dist metres back along the way duck d swam (from where she is now)
  behind(d, dist) {
    let px = d.g.position.x, pz = d.g.position.z;
    for (const [qx, qz] of d.trail) {
      const seg = Math.hypot(qx - px, qz - pz);
      if (seg >= dist && seg > 0) return [px + ((qx - px) * dist) / seg, pz + ((qz - pz) * dist) / seg];
      dist -= seg;
      px = qx;
      pz = qz;
    }
    return [px, pz];
  }
  update(dt, player, night = 0) {
    if (!this.room) return;
    const c = this.room.def.pos;
    if (player && Math.hypot(player.pos.x - c.x, player.pos.z - c.z) > 55) return;
    const time = performance.now() / 1000;
    this.deep.material.emissiveIntensity = night * 0.35;
    this.waterTime.value = time;
    this.fed = Math.max(0, (this.fed || 0) - dt);
    const r0 = shoreR(0);
    for (const d of this.ducks) {
      if (d.kind === "baby") continue;
      let x, z;
      if (this.fed > 0) {
        // paddle towards the jetty for the crumbs
        const tx = (d.lane - 0.5) * 2.4, tz = r0 + CZ - 3.6 - d.lane;
        x = d.g.position.x + (tx - d.g.position.x) * (1 - Math.exp(-dt * 0.6));
        z = d.g.position.z + (tz - d.g.position.z) * (1 - Math.exp(-dt * 0.6));
      } else {
        d.t += d.speed * dt;
        [x, z] = this.lanePos(d.lane, d.t);
        x = d.g.position.x + (x - d.g.position.x) * (1 - Math.exp(-dt * 1.5));
        z = d.g.position.z + (z - d.g.position.z) * (1 - Math.exp(-dt * 1.5));
      }
      const dx = x - d.g.position.x, dz = z - d.g.position.z;
      if (Math.hypot(dx, dz) > 0.0005) d.g.rotation.y += (Math.atan2(Math.sin(Math.atan2(dx, dz) - d.g.rotation.y), Math.cos(Math.atan2(dx, dz) - d.g.rotation.y))) * (1 - Math.exp(-dt * 3));
      d.g.position.set(x, 0.08, z);
      // the path behind her, a point every few centimetres (so the line keeps its spacing at any speed)
      const last = d.trail[0];
      if (!last || Math.hypot(x - last[0], z - last[1]) > 0.04) {
        d.trail.unshift([x, z]);
        if (d.trail.length > 80) d.trail.length = 80;
      }
      // her ducklings in a line behind, clear of her tail and of each other: each one a set
      // distance back along the way she came, measured from where she is right now and
      // between the trail's points, so they glide along with her instead of hopping from
      // point to point
      d.babies?.forEach((b, i) => {
        const p = this.behind(d, 0.52 + i * 0.32);
        if (!p) return;
        const dx = p[0] - b.g.position.x, dz = p[1] - b.g.position.z;
        if (Math.hypot(dx, dz) > 0.0005) {
          const want = Math.atan2(dx, dz);
          b.g.rotation.y += Math.atan2(Math.sin(want - b.g.rotation.y), Math.cos(want - b.g.rotation.y)) * (1 - Math.exp(-dt * 8));
        }
        b.g.position.set(p[0], 0.08, p[1]);
      });
    }
    for (const [i, d] of this.ducks.entries()) {
      d.body.position.y = Math.sin(time * 2.2 + i) * 0.015;
      d.body.rotation.z = Math.sin(time * 1.7 + i) * 0.06;
      d.head.rotation.x = this.fed > 0 ? Math.max(0, Math.sin(time * 8 + i)) * 0.7 : Math.sin(time * 0.9 + i * 2) * 0.12;
    }
    // little ripples behind them
    this.nextRipple -= dt;
    if (this.nextRipple <= 0) {
      this.nextRipple = 0.35;
      const d = this.ducks[Math.floor(Math.random() * this.ducks.length)];
      const r = this.ripples.find((q) => q.life <= 0);
      if (r) {
        r.life = 1;
        r.m.position.set(d.g.position.x, 0.095, d.g.position.z);
        r.m.visible = true;
        r.s = d.s;
      }
    }
    for (const r of this.ripples) {
      if (r.life <= 0) continue;
      r.life -= dt * 0.6;
      const k = 1 - r.life;
      r.m.scale.setScalar((0.15 + k * 0.5) * (r.s || 1));
      r.m.material.opacity = Math.max(0, r.life) * 0.45;
      if (r.life <= 0) r.m.visible = false;
    }
  }
}


// little waves drifting over the deep water: the surface tilts a touch here and there, so
// the sky and the lamps catch on it and glint as you look across (the shape stays flat)
function ripple(mat, time) {
  mat.onBeforeCompile = (sh) => {
    sh.uniforms.uWaterTime = time;
    sh.vertexShader = `varying vec3 vWaterPos;
${sh.vertexShader}`.replace(
      "#include <worldpos_vertex>",
      `#include <worldpos_vertex>
  vWaterPos = (modelMatrix * vec4(transformed, 1.0)).xyz;`,
    );
    sh.fragmentShader = `uniform float uWaterTime;
varying vec3 vWaterPos;
${sh.fragmentShader}`.replace(
      "#include <normal_fragment_maps>",
      `#include <normal_fragment_maps>
      {
        vec2 p = vWaterPos.xz;
        float t = uWaterTime;
        vec2 tilt = vec2(sin(p.x * 1.7 + t * 1.3) + sin(p.y * 2.3 - t * 1.1) * 0.6, cos(p.y * 1.9 + t * 1.2) + cos((p.x + p.y) * 1.3 - t * 0.9) * 0.6) * 0.1;
        normal = normalize(normal + (viewMatrix * vec4(tilt.x, 0.0, tilt.y, 0.0)).xyz);
      }`,
    );
  };
  mat.customProgramCacheKey = () => "lake-ripple";
}
