// Our little farm: a red gambrel barn with a silo, two pastures (cows on one side, sheep
// and goats on the other), a hen house with its wire run, a vegetable patch and a pumpkin
// patch by the gate. Milk the cows and goats, collect the eggs and churn milk into butter:
// it all goes in our pantry (pantry.js), which is what dodo's bakery bakes with.
import * as THREE from "three";
import { std, buildWalkways, glow, mulberry, put } from "./world.js";
import { texture } from "./textures.js";
import { bakeWhenSettled } from "./bake.js";

const TAU = Math.PI * 2;
const MILK_REST = 10 * 60000; // a cow (or goat) can be milked again after this
const EGG_EVERY = 6 * 60000; // the hens lay one egg this often
const EGG_MAX = 6;
const COW_NAMES = ["Bella", "Mochi"];
const GOAT_NAMES = ["Pudding", "Biscuit"];
const SHEEP_NAMES = ["Cloud", "Marshmallow", "Cotton", "Puff"];

// the farm's own frame: +z is the gate, towards the middle of the island
const OUT = { hw: 12.6, hd: 12.2, r: 4.5 }; // the boundary fence, a rounded rectangle
const GATE_W = 3.2;
const BARN = { x: 0, z: -7.6, w: 7, d: 5.4, h: 3.1 };
// where the animals roam (rounded rectangles: middle, half sizes)
const COWS = { x: -7, z: 2.5, hw: 4.6, hd: 4.4 };
const PEN = { x: 7, z: 2.5, hw: 4.6, hd: 4.4 };
const RUN = { x: -7.3, z: -7.3, hw: 2.9, hd: 2.6 };

const WOOD = "#8b6a4f";
const WOOD_D = "#6f5340";
const CREAM = "#f3ead8";
const BARN_RED = "#c9604f";

const geo = {
  box: new THREE.BoxGeometry(1, 1, 1),
  ball: new THREE.SphereGeometry(1, 14, 10),
  lowball: new THREE.IcosahedronGeometry(1, 1),
  cyl: new THREE.CylinderGeometry(1, 1, 1, 12),
  cone: new THREE.ConeGeometry(1, 1, 10),
};
const M = (c, o) => std(c, o);
const S_ = (c) => std(c, { flatShading: false, roughness: 0.85 }); // smooth, for the animals
// points round a rounded rectangle, starting at the middle of the front (+z) edge
function roundRect({ x, z, hw, hd, r }) {
  // go round anticlockwise seen from above (+x right, +z down the page): front edge rightwards
  const segs = [];
  const P = (px, pz) => segs.push([px, pz]);
  P(x, z + hd);
  for (let k = 1; k <= 8; k++) P(x + ((hw - r) * k) / 8, z + hd);
  for (let k = 1; k <= 6; k++) {
    const a = Math.PI / 2 - (k / 6) * (Math.PI / 2);
    P(x + hw - r + Math.cos(a) * r, z + hd - r + Math.sin(a) * r);
  }
  for (let k = 1; k <= 12; k++) P(x + hw, z + hd - r - ((hd * 2 - r * 2) * k) / 12);
  for (let k = 1; k <= 6; k++) {
    const a = -(k / 6) * (Math.PI / 2);
    P(x + hw - r + Math.cos(a) * r, z - hd + r + Math.sin(a) * r);
  }
  for (let k = 1; k <= 16; k++) P(x + hw - r - ((hw * 2 - r * 2) * k) / 16, z - hd);
  for (let k = 1; k <= 6; k++) {
    const a = -Math.PI / 2 - (k / 6) * (Math.PI / 2);
    P(x - hw + r + Math.cos(a) * r, z - hd + r + Math.sin(a) * r);
  }
  for (let k = 1; k <= 12; k++) P(x - hw, z - hd + r + ((hd * 2 - r * 2) * k) / 12);
  for (let k = 1; k <= 6; k++) {
    const a = Math.PI - (k / 6) * (Math.PI / 2);
    P(x - hw + r + Math.cos(a) * r, z + hd - r + Math.sin(a) * r);
  }
  for (let k = 1; k <= 8; k++) P(x - hw + r + ((hw - r) * k) / 8, z + hd);
  return segs;
}
// cut an opening of width w out of a closed loop of points, centred on (gx, gz); returns the run that's left
function withGap(pts, gx, gz, w) {
  let best = 0;
  pts.forEach(([px, pz], i) => {
    if (Math.hypot(px - gx, pz - gz) < Math.hypot(pts[best][0] - gx, pts[best][1] - gz)) best = i;
  });
  const rot = [...pts.slice(best), ...pts.slice(0, best)];
  return rot.filter(([px, pz]) => Math.hypot(px - gx, pz - gz) > w / 2);
}

// a wooden plank sign with painted lettering
function plank(text, w, h, { size = 64, color = "#f6efe2" } = {}) {
  const c = document.createElement("canvas");
  c.width = 512;
  c.height = Math.round((512 * h) / w);
  const g = c.getContext("2d");
  g.fillStyle = "#7a5a43";
  g.fillRect(0, 0, c.width, c.height);
  // wood grain
  for (let i = 0; i < 26; i++) {
    g.strokeStyle = `rgba(${i % 2 ? "40,25,15" : "160,120,90"},${0.12 + (i % 3) * 0.04})`;
    g.lineWidth = 1 + (i % 3);
    g.beginPath();
    const y = (i / 26) * c.height;
    g.moveTo(0, y);
    g.bezierCurveTo(c.width * 0.3, y + 4, c.width * 0.6, y - 4, c.width, y + 2);
    g.stroke();
  }
  g.strokeStyle = "rgba(40,25,15,0.5)";
  g.lineWidth = 10;
  g.strokeRect(5, 5, c.width - 10, c.height - 10);
  g.font = `600 ${size}px "Fredoka", "Quicksand", "Segoe UI", sans-serif`;
  g.textAlign = "center";
  g.textBaseline = "middle";
  g.fillStyle = "rgba(30,18,10,0.55)";
  g.fillText(text, c.width / 2 + 3, c.height / 2 + 5);
  g.fillStyle = color;
  g.fillText(text, c.width / 2, c.height / 2 + 2);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  const face = new THREE.MeshStandardMaterial({ map: t, roughness: 0.9 });
  const edge = M("#6a4d39");
  return new THREE.Mesh(new THREE.BoxGeometry(w, h, 0.07), [edge, edge, edge, edge, face, face]);
}

// a patchy black-and-white hide for the dairy cow
let hideTex;
function hide() {
  if (hideTex) return hideTex;
  const c = document.createElement("canvas");
  c.width = 256;
  c.height = 128;
  const g = c.getContext("2d");
  g.fillStyle = "#f7f3ee";
  g.fillRect(0, 0, 256, 128);
  g.fillStyle = "#2c2628";
  const R = mulberry(19);
  for (let i = 0; i < 9; i++) {
    const cx = R() * 256, cy = R() * 128, r = 14 + R() * 22;
    g.beginPath();
    for (let k = 0; k <= 14; k++) {
      const a = (k / 14) * TAU;
      const rr = r * (0.7 + R() * 0.5);
      g[k ? "lineTo" : "moveTo"](cx + Math.cos(a) * rr, cy + Math.sin(a) * rr * 0.8);
    }
    g.fill();
  }
  hideTex = new THREE.CanvasTexture(c);
  hideTex.colorSpace = THREE.SRGBColorSpace;
  return hideTex;
}

// ---- the animals, all facing +z ---------------------------------------------------------
function legsOf(parent, mat, pts, h, r, hoof) {
  return pts.map(([x, z]) => {
    const pivot = new THREE.Group();
    pivot.position.set(x, h, z);
    put(pivot, new THREE.CylinderGeometry(r, r * 0.8, h, 8), mat, 0, -h / 2, 0);
    if (hoof) put(pivot, new THREE.CylinderGeometry(r * 0.85, r * 0.95, 0.07, 8), hoof, 0, -h + 0.035, 0);
    parent.add(pivot);
    return pivot;
  });
}
function makeCow(kind) {
  const g = new THREE.Group();
  const holstein = kind === 0;
  const coat = holstein ? new THREE.MeshStandardMaterial({ map: hide(), roughness: 0.85 }) : S_("#b98457");
  const pale = S_(holstein ? "#f7f3ee" : "#d9b089");
  const nose = S_("#e2aaa0");
  const dark = S_("#2a2224");
  const horn = S_("#efe4cc");
  const body = new THREE.Group();
  g.add(body);
  put(body, new THREE.CapsuleGeometry(0.4, 0.85, 6, 14), coat, 0, 1.0, 0, { rx: Math.PI / 2, sx: 1, sz: 1.08 });
  put(body, geo.ball, pale, 0, 0.72, -0.25, { sx: 0.17, sy: 0.12, sz: 0.2 }); // udder
  for (const [x, z] of [[-0.06, -0.2], [0.06, -0.2], [-0.06, -0.3], [0.06, -0.3]]) put(body, geo.cyl, nose, x, 0.6, z, { sx: 0.022, sy: 0.08, sz: 0.022 });
  const tail = new THREE.Group();
  tail.position.set(0, 1.3, -0.82);
  body.add(tail);
  put(tail, geo.cyl, coat, 0, -0.32, -0.03, { sx: 0.025, sy: 0.65, sz: 0.025, rx: 0.08 });
  put(tail, geo.ball, dark, 0, -0.66, -0.05, { sx: 0.05, sy: 0.09, sz: 0.05 });
  // neck and head
  put(body, new THREE.CapsuleGeometry(0.22, 0.3, 4, 10), coat, 0, 1.22, 0.62, { rx: 1.0 });
  const head = new THREE.Group();
  head.position.set(0, 1.35, 0.86);
  head.scale.setScalar(1.3);
  body.add(head);
  put(head, geo.ball, holstein ? pale : coat, 0, 0, 0.1, { sx: 0.2, sy: 0.22, sz: 0.3, rx: 0.35 });
  put(head, geo.ball, holstein ? M("#2c2628", { flatShading: false }) : coat, 0, 0.1, 0.02, { sx: 0.21, sy: 0.16, sz: 0.2 });
  put(head, geo.ball, nose, 0, -0.12, 0.33, { sx: 0.16, sy: 0.12, sz: 0.11 });
  for (const s of [-1, 1]) {
    put(head, geo.ball, dark, s * 0.05, -0.11, 0.43, { s: 0.022 });
    put(head, geo.ball, dark, s * 0.15, 0.07, 0.2, { s: 0.032 });
    put(head, geo.ball, coat, s * 0.27, 0.08, 0.02, { sx: 0.13, sy: 0.05, sz: 0.08, rz: s * -0.3 });
    put(head, geo.cone, horn, s * 0.14, 0.24, 0.0, { sx: 0.035, sy: 0.14, sz: 0.035, rz: s * -0.7 });
  }
  const legs = legsOf(body, holstein ? pale : coat, [[-0.24, 0.48], [0.24, 0.48], [-0.24, -0.48], [0.24, -0.48]], 0.7, 0.075, dark);
  return { g, body, head, legs, tail, step: 3.2, speed: 0.5, bob: 0.025 };
}
function makeGoat(kind) {
  const g = new THREE.Group();
  const coat = S_(kind === 0 ? "#efe9df" : "#9b6b48");
  const dark = S_(kind === 0 ? "#c9bfb2" : "#4a3428");
  const horn = S_("#b9ab94");
  const body = new THREE.Group();
  g.add(body);
  put(body, new THREE.CapsuleGeometry(0.24, 0.6, 5, 12), coat, 0, 0.75, 0, { rx: Math.PI / 2 });
  const tail = new THREE.Group();
  tail.position.set(0, 0.9, -0.52);
  body.add(tail);
  put(tail, geo.cone, coat, 0, 0.05, 0, { sx: 0.04, sy: 0.14, sz: 0.04, rx: -0.6 });
  put(body, new THREE.CapsuleGeometry(0.11, 0.22, 4, 8), coat, 0, 0.98, 0.38, { rx: 0.7 });
  const head = new THREE.Group();
  head.position.set(0, 1.12, 0.5);
  body.add(head);
  put(head, geo.ball, coat, 0, 0, 0.08, { sx: 0.12, sy: 0.13, sz: 0.2, rx: 0.5 });
  put(head, geo.cone, S_("#f2ece2"), 0, -0.17, 0.16, { sx: 0.035, sy: 0.12, sz: 0.035, rx: Math.PI }); // beard
  for (const s of [-1, 1]) {
    put(head, geo.ball, S_("#2a2224"), s * 0.08, 0.04, 0.17, { s: 0.022 });
    put(head, geo.ball, coat, s * 0.15, -0.03, 0.02, { sx: 0.05, sy: 0.13, sz: 0.035, rz: s * 0.5 }); // floppy ears
    put(head, new THREE.TorusGeometry(0.12, 0.022, 6, 10, Math.PI * 0.75), horn, s * 0.06, 0.12, -0.02, { ry: Math.PI / 2, rz: -0.2 });
  }
  const legs = legsOf(body, coat, [[-0.13, 0.28], [0.13, 0.28], [-0.13, -0.28], [0.13, -0.28]], 0.52, 0.045, dark);
  return { g, body, head, legs, tail, step: 5, speed: 0.75, bob: 0.025 };
}
function makeSheep() {
  const g = new THREE.Group();
  const wool = S_("#f4efe6"), shade = S_("#e6dfd3"), face = S_("#3b3135");
  const body = new THREE.Group();
  g.add(body);
  // an oval fleece, longer than it is wide, with small curls spread evenly over its top
  const BX = 0.3, BY = 0.27, BZ = 0.46, BYC = 0.56; // sitting low on short legs
  put(body, geo.ball, wool, 0, BYC, 0, { sx: BX, sy: BY, sz: BZ });
  const n = 26;
  for (let i = 0; i < n; i++) {
    const y = 1 - (i + 0.5) / n * 1.25; // the top and the sides, not underneath
    const r = Math.sqrt(Math.max(0, 1 - y * y));
    const a = i * 2.39996;
    put(body, geo.ball, i % 3 ? wool : shade, Math.cos(a) * r * BX * 0.95, BYC + y * BY * 0.95, Math.sin(a) * r * BZ * 0.95, { s: 0.1 + (i % 4) * 0.012 });
  }
  const tail = new THREE.Group();
  tail.position.set(0, BYC + 0.05, -BZ - 0.02);
  body.add(tail);
  put(tail, geo.ball, wool, 0, 0, 0, { s: 0.07 });
  const head = new THREE.Group();
  head.position.set(0, BYC + 0.12, BZ + 0.02);
  head.scale.setScalar(1.15);
  body.add(head);
  put(head, geo.ball, face, 0, -0.02, 0.1, { sx: 0.1, sy: 0.12, sz: 0.17, rx: 0.45 });
  put(head, geo.ball, wool, 0, 0.09, 0.0, { sx: 0.12, sy: 0.08, sz: 0.1 }); // a little woolly cap
  for (const s of [-1, 1]) {
    put(head, geo.ball, S_("#1b1618"), s * 0.07, 0.02, 0.15, { s: 0.018 });
    put(head, geo.ball, face, s * 0.13, 0.02, 0.02, { sx: 0.08, sy: 0.03, sz: 0.045, rz: s * -0.35 });
  }
  const legs = legsOf(body, face, [[-0.14, 0.27], [0.14, 0.27], [-0.14, -0.27], [0.14, -0.27]], 0.34, 0.038);
  return { g, body, head, legs, tail, step: 5, speed: 0.55, bob: 0.025 };
}
function makeHen(c, rooster) {
  const g = new THREE.Group();
  const f = S_(c), red = S_("#d9364a"), beak = S_("#f0a42b");
  const body = new THREE.Group();
  g.add(body);
  put(body, geo.ball, f, 0, 0.26, 0, { sx: 0.15, sy: 0.15, sz: 0.2 });
  put(body, geo.ball, f, 0, 0.24, 0.08, { sx: 0.12, sy: 0.12, sz: 0.12 });
  const tail = new THREE.Group();
  tail.position.set(0, 0.3, -0.16);
  body.add(tail);
  if (rooster) for (const [k, col] of [[0, "#2f5d4f"], [1, "#a9552d"], [2, "#2f5d4f"]]) put(tail, geo.ball, S_(col), (k - 1) * 0.035, 0.12 + (k % 2) * 0.03, -0.04, { sx: 0.025, sy: 0.15, sz: 0.06, rx: -0.5 });
  else put(tail, geo.ball, f, 0, 0.06, 0, { sx: 0.05, sy: 0.1, sz: 0.08, rx: -0.5 });
  const head = new THREE.Group();
  head.position.set(0, 0.4, 0.13);
  body.add(head);
  put(head, geo.ball, f, 0, 0.03, 0, { s: 0.08 });
  put(head, geo.cone, beak, 0, 0.02, 0.09, { sx: 0.022, sy: 0.05, sz: 0.022, rx: Math.PI / 2 });
  for (let k = 0; k < 3; k++) put(head, geo.ball, red, 0, 0.1 + (k % 2) * 0.01, -0.03 + k * 0.03, { sx: 0.015, sy: rooster ? 0.045 : 0.03, sz: 0.022 });
  put(head, geo.ball, red, 0, -0.04, 0.06, { sx: 0.015, sy: 0.035, sz: 0.015 });
  for (const s of [-1, 1]) put(head, geo.ball, S_("#1e1a1c"), s * 0.055, 0.05, 0.04, { s: 0.013 });
  const legs = legsOf(body, beak, [[-0.05, 0], [0.05, 0]], 0.13, 0.01);
  return { g, body, head, legs, tail, step: 9, speed: 0.55, bob: 0.02, hen: true };
}
function makeChick() {
  const g = new THREE.Group();
  const body = new THREE.Group();
  g.add(body);
  const y = S_("#ffe27a");
  put(body, geo.ball, y, 0, 0.07, 0, { sx: 0.065, sy: 0.06, sz: 0.075 });
  const head = new THREE.Group();
  head.position.set(0, 0.13, 0.04);
  body.add(head);
  put(head, geo.ball, y, 0, 0, 0, { s: 0.045 });
  put(head, geo.cone, S_("#f0a42b"), 0, 0, 0.045, { sx: 0.012, sy: 0.025, sz: 0.012, rx: Math.PI / 2 });
  return { g, body, head, legs: [], step: 12, speed: 0.45, bob: 0.012, hen: true };
}

export class Farm {
  constructor({ world, h, toast, audio, isGuest, myName, confetti, pantry }) {
    Object.assign(this, { world, h, toast, audio, isGuest, myName, confetti, pantry });
    this.room = world.rooms.get("farm");
    if (!this.room) return;
    this.still = new THREE.Group();
    this.live = new THREE.Group();
    this.room.group.add(this.still, this.live);
    // the animals aren't drawn from right across the island (world.js); the rest is baked into a few meshes
    this.room.far = [[this.live, 130]];
    this.animals = [];
    this.build();
    bakeWhenSettled(this.still);
  }

  // ---- helpers in the farm's own frame -----------------------------------------------------
  wall(ax, az, bx, bz, hgt = 1.3) {
    const a = this.world.toWorld(this.room, ax, 0, az);
    const b = this.world.toWorld(this.room, bx, 0, bz);
    this.world.addWallSegment(a.x, a.z, b.x, b.z, hgt);
  }
  circle(x, z, r) {
    const p = this.world.toWorld(this.room, x, 0, z);
    this.world.addCircle(p.x, p.z, r);
  }
  item(id, label, x, z, what, extra = {}, radius = 1.7, hits = []) {
    const it = { id, icon: "", pos: this.world.toWorld(this.room, x, 0, z).setY(0), radius, action: { type: "farm", what, ...extra }, room: "farm", hits };
    Object.defineProperty(it, "label", typeof label === "function" ? { get: label, enumerable: true } : { value: label, enumerable: true });
    for (const m of hits) m.traverse((o) => (o.userData.item = it));
    this.world.interactables.push(it);
    return it;
  }
  // a split-rail fence along a run of points: weathered posts, two rails, solid
  rails(pts, { h = 1.05, color = WOOD, solid = true, rails = 2 } = {}) {
    const S = this.still;
    const post = M(WOOD_D), rail = M(color);
    const R = mulberry(Math.round(pts[0][0] * 31 + pts[0][1] * 17) + 3);
    let since = 99;
    for (let i = 0; i < pts.length; i++) {
      const [x, z] = pts[i];
      const next = pts[i + 1];
      if (next && Math.hypot(next[0] - x, next[1] - z) > 1.5) {
        since = 99;
        continue; // a gap in the run (an opening)
      }
      since += next ? Math.hypot(next[0] - x, next[1] - z) : 0;
      if (since >= 1.9 || i === 0 || !next) {
        since = 0;
        const ph = h + (R() - 0.5) * 0.1;
        put(S, geo.cyl, post, x, ph / 2, z, { sx: 0.075, sy: ph, sz: 0.075, ry: R() * 3 });
      }
      if (!next) continue;
      const [bx, bz] = next;
      const len = Math.hypot(bx - x, bz - z);
      const ry = Math.atan2(bx - x, bz - z);
      for (let k = 0; k < rails; k++) put(S, geo.box, rail, (x + bx) / 2, h * (rails === 2 ? [0.42, 0.82][k] : [0.3, 0.6, 0.9][k]), (z + bz) / 2, { sx: 0.05, sy: 0.09, sz: len + 0.04, ry, rz: (R() - 0.5) * 0.04 });
      if (solid) this.wall(x, z, bx, bz, h + 0.4);
    }
  }
  flat(shape, color, y, k = 1) {
    const m = std(color, { polygonOffset: true, polygonOffsetFactor: -k, polygonOffsetUnits: -k * 2 });
    return put(this.still, new THREE.ShapeGeometry(shape, 2), m, 0, y, 0, { rx: -Math.PI / 2, cast: false });
  }
  blob(cx, cz, rx, rz, seed) {
    const s = new THREE.Shape();
    const R = mulberry(seed);
    const n = 28;
    for (let i = 0; i <= n; i++) {
      const a = (i / n) * TAU;
      const w = 1 + (R() - 0.5) * 0.16;
      const x = cx + Math.cos(a) * rx * w, z = cz + Math.sin(a) * rz * w;
      if (i === 0) s.moveTo(x, -z);
      else s.lineTo(x, -z);
    }
    return s;
  }

  build() {
    const S = this.still;
    // a worn dirt yard in front of the barn, trodden patches by the troughs
    this.flat(this.blob(0, -3.6, 5.2, 2.6, 4), "#a98d6c", 0.025, 1);
    this.flat(this.blob(RUN.x, RUN.z, RUN.hw + 0.2, RUN.hd + 0.2, 8), "#b59a76", 0.03, 2);
    // the lane from the gate to the barn doors: the island's cobbles, in warm farmyard stone,
    // on sandy ground, with no blossom this far out among the fields
    S.add(buildWalkways([{ pts: [[0, OUT.hd + 1.2], [0, 6], [0, BARN.z + BARN.d / 2 + 0.3]], w: 2.2, pebbleFrom: 0.6 }], { seed: 21, y: 0.035, cobbles: { tones: ["#b89c7c", "#a88b6a", "#c4a886", "#9c7f60", "#b0926f", "#c9b090"], ground: "#d8c6a8", petals: false, pebbles: ["#a8916f", "#b89c7c", "#8f7658", "#c4ad8c"] } }));

    // the boundary fence with its gate
    const ring = roundRect({ x: 0, z: 0, hw: OUT.hw, hd: OUT.hd, r: OUT.r });
    this.rails(withGap(ring, 0, OUT.hd, GATE_W), { rails: 3, h: 1.1 });
    this.gate();
    this.barn();
    this.silo(5.7, -9.3);
    this.pasture(COWS, "cows");
    this.pasture(PEN, "sheep & goats");
    this.coop();
    this.crops();
    this.yard();

    // the animals
    COW_NAMES.forEach((n, i) => this.addAnimal(makeCow(i), COWS, { kind: "cow", name: n, id: `cow${i}` }));
    GOAT_NAMES.forEach((n, i) => this.addAnimal(makeGoat(i), PEN, { kind: "goat", name: n, id: `goat${i}` }));
    SHEEP_NAMES.forEach((n, i) => this.addAnimal(makeSheep(), PEN, { kind: "sheep", name: n, id: `sheep${i}` }));
    ["#f5efe6", "#a8643a", "#3a3236", "#c98a52"].forEach((c, i) => this.addAnimal(makeHen(c, false), RUN, { kind: "hen", id: `hen${i}` }));
    this.addAnimal(makeHen("#f1e2c8", true), RUN, { kind: "rooster", id: "rooster" });
    for (let i = 0; i < 3; i++) this.addAnimal(makeChick(), RUN, { kind: "chick", id: `chick${i}` });
  }

  // two log posts, a beam across, the farm's name on a plank hanging from it, lanterns
  gate() {
    const S = this.still;
    const log = M("#7a5a43");
    const z = OUT.hd;
    for (const s of [-1, 1]) {
      const x = s * (GATE_W / 2 + 0.15);
      put(S, geo.cyl, log, x, 1.6, z, { sx: 0.17, sy: 3.2, sz: 0.17 });
      put(S, geo.cyl, M(WOOD_D), x, 3.22, z, { sx: 0.19, sy: 0.06, sz: 0.19 });
      this.circle(x, z, 0.25);
      // a lantern on a little arm
      put(S, geo.box, M("#2e2a2c"), x + s * 0.25, 2.45, z + 0.05, { sx: 0.35, sy: 0.04, sz: 0.04 });
      put(S, geo.box, M("#2e2a2c"), x + s * 0.4, 2.27, z + 0.05, { sx: 0.18, sy: 0.04, sz: 0.18 });
      put(S, new THREE.CylinderGeometry(0.07, 0.07, 0.22, 8), glow.warm, x + s * 0.4, 2.12, z + 0.05, { cast: false });
      put(S, geo.cone, M("#2e2a2c"), x + s * 0.4, 2.3, z + 0.05, { sx: 0.11, sy: 0.08, sz: 0.11 });
    }
    put(S, geo.cyl, log, 0, 3.0, z, { sx: 0.14, sy: GATE_W + 1.1, sz: 0.14, rz: Math.PI / 2 });
    const sign = plank("our little farm", 2.6, 0.62, { size: 66 });
    sign.position.set(0, 2.45, z + 0.02);
    sign.castShadow = true;
    S.add(sign);
    for (const s of [-1, 1]) put(S, geo.cyl, M("#4a4446"), s * 1.05, 2.86, z + 0.02, { sx: 0.012, sy: 0.24, sz: 0.012 });
  }

  // our storage barn: a red gambrel barn with its big doors slid open, so you can walk in.
  // Inside, the shelves and crates hold whatever is in our pantry right now.
  barn() {
    const S = this.still;
    const { x, z, w: W, d: D, h: H } = BARN;
    const red = new THREE.MeshStandardMaterial({ map: texture("wood", [BARN_RED, "#b85546"], 1), roughness: 0.9, flatShading: true });
    const redG = new THREE.MeshStandardMaterial({ map: texture("wood", [BARN_RED, "#b85546"], 0.35), roughness: 0.9, flatShading: true });
    const roof = new THREE.MeshStandardMaterial({ map: texture("shingles", ["#5a4a4e", "#463a3e"], 0.6), roughness: 0.95, flatShading: true });
    const trim = M(CREAM);
    const stone = M("#9a948e");
    const T = 0.16;
    const DW = 3.0, DH = 2.6; // the doorway
    const k1 = W * 0.33, h1 = 1.35, h2 = 2.0;
    const fz = z + D / 2;
    // the roof, with a plank ceiling under it like the rooms have (the camera stays under it inside)
    const shell = new THREE.Group();
    shell.userData.live = true;
    this.live.add(shell);
    this.barnShell = shell;
    // walls: back, sides, and the front either side of (and over) the doorway
    put(S, geo.box, red, x, H / 2, z - D / 2, { sx: W, sy: H, sz: T });
    for (const s of [-1, 1]) put(S, geo.box, red, x + s * (W / 2), H / 2, z, { sx: T, sy: H, sz: D });
    const side = (W - DW) / 2;
    for (const s of [-1, 1]) put(S, geo.box, red, x + s * (DW / 2 + side / 2), H / 2, fz, { sx: side, sy: H, sz: T });
    put(S, geo.box, red, x, DH + (H - DH) / 2, fz, { sx: DW, sy: H - DH, sz: T });
    // a stone footing round the outside, a plank floor inside
    for (const [px, pz, sx, sz] of [[x, z - D / 2, W + 0.2, T + 0.12], [x - W / 2, z, T + 0.12, D + 0.2], [x + W / 2, z, T + 0.12, D + 0.2], [x - DW / 2 - side / 2, fz, side + 0.1, T + 0.12], [x + DW / 2 + side / 2, fz, side + 0.1, T + 0.12]]) put(S, geo.box, stone, px, 0.16, pz, { sx, sy: 0.32, sz });
    put(S, geo.box, new THREE.MeshStandardMaterial({ map: texture("wood", ["#a0805f", "#8c6d50"], 1), roughness: 0.9 }), x, 0.03, z, { sx: W - T, sy: 0.06, sz: D - T, cast: false });
    // the gambrel ends, over the walls
    const prof = new THREE.Shape();
    prof.moveTo(-W / 2, 0);
    prof.lineTo(W / 2, 0);
    prof.lineTo(k1, h1);
    prof.lineTo(0, h2);
    prof.lineTo(-k1, h1);
    const gab = new THREE.ExtrudeGeometry(prof, { depth: T, bevelEnabled: false });
    for (const e of [-1, 1]) put(shell, gab, redG, x, H, z + e * (D / 2) - T / 2);
    // the roof: two slopes each side, a ridge, overhanging front and back
    const slab = (ax, ay, bx, by) => {
      const len = Math.hypot(bx - ax, by - ay);
      const ang = Math.atan2(by - ay, bx - ax);
      const nx = -Math.sin(ang) * 0.08, ny = Math.cos(ang) * 0.08;
      put(shell, geo.box, roof, x + (ax + bx) / 2 + nx, (ay + by) / 2 + ny, z, { sx: len + 0.22, sy: 0.14, sz: D + 0.7, rz: ang });
    };
    for (const s of [-1, 1]) {
      slab(s * (W / 2 + 0.18), H - 0.12, s * k1, H + h1);
      slab(s * k1, H + h1, 0, H + h2);
    }
    put(shell, geo.box, M("#3e3236"), x, H + h2 + 0.08, z, { sx: 0.26, sy: 0.14, sz: D + 0.74 });
    // cream trim: corners, the eaves line, round the gables and the doorway
    for (const s of [-1, 1]) for (const e of [-1, 1]) put(S, geo.box, trim, x + s * (W / 2), H / 2, z + e * (D / 2), { sx: 0.2, sy: H, sz: 0.2 });
    for (const e of [-1, 1]) {
      const zz = z + e * (D / 2 + T / 2 + 0.02);
      for (const [ax, ay, bx, by] of [[-W / 2, H, -k1, H + h1], [-k1, H + h1, 0, H + h2], [0, H + h2, k1, H + h1], [k1, H + h1, W / 2, H]]) {
        const len = Math.hypot(bx - ax, by - ay);
        put(shell, geo.box, trim, x + (ax + bx) / 2, (ay + by) / 2, zz, { sx: len + 0.1, sy: 0.12, sz: 0.05, rz: Math.atan2(by - ay, bx - ax) });
      }
      put(S, geo.box, trim, x, H, zz, { sx: W, sy: 0.12, sz: 0.05 });
    }
    const dz = fz + T / 2 + 0.03;
    for (const s of [-1, 1]) put(S, geo.box, trim, x + s * (DW / 2 + 0.05), DH / 2, dz, { sx: 0.12, sy: DH, sz: 0.05 });
    put(S, geo.box, trim, x, DH + 0.05, dz, { sx: DW + 0.22, sy: 0.12, sz: 0.05 });
    // the two sliding doors, pushed open along their rail, each with a frame and a Z brace
    const dw = DW / 2 + 0.05;
    put(S, geo.box, M("#3a3436"), x, DH + 0.2, dz + 0.04, { sx: W - 0.3, sy: 0.06, sz: 0.06 });
    for (const s of [-1, 1]) {
      const cx = x + s * (DW / 2 + dw / 2 + 0.02);
      const doz = dz + 0.1;
      put(S, geo.box, red, cx, DH / 2, doz, { sx: dw, sy: DH - 0.05, sz: 0.06 });
      for (const [px, py, sx, sy] of [[0, DH / 2 - 0.08, dw, 0.1], [0, -DH / 2 + 0.08, dw, 0.1], [-dw / 2 + 0.05, 0, 0.1, DH - 0.1], [dw / 2 - 0.05, 0, 0.1, DH - 0.1], [0, 0, dw, 0.1]]) put(S, geo.box, trim, cx + px, DH / 2 + py, doz + 0.04, { sx, sy, sz: 0.04 });
      for (const e of [-1, 1]) put(S, geo.box, trim, cx, DH / 2 + e * DH / 4, doz + 0.05, { sx: Math.hypot(dw - 0.15, DH / 2 - 0.15), sy: 0.09, sz: 0.04, rz: s * e * Math.atan2(DH / 2 - 0.15, dw - 0.15) });
    }
    // the hay loft door up in the gable, a pulley beam, a lantern by the doorway
    put(shell, geo.box, M("#3e2f2a"), x, H + 0.65, dz - 0.02, { sx: 1.0, sy: 0.95, sz: 0.04 });
    for (const [px, py, sx, sy] of [[0, 0.47, 1.1, 0.09], [0, -0.47, 1.1, 0.09], [-0.5, 0, 0.09, 1.0], [0.5, 0, 0.09, 1.0]]) put(shell, geo.box, trim, x + px, H + 0.65 + py, dz + 0.01, { sx, sy, sz: 0.05 });
    put(shell, geo.box, M(WOOD_D), x, H + h2 - 0.25, fz + 0.45, { sx: 0.14, sy: 0.14, sz: 0.9 });
    put(S, geo.box, M("#2e2a2c"), x + DW / 2 + 0.35, 2.3, dz + 0.1, { sx: 0.16, sy: 0.04, sz: 0.24 });
    put(S, new THREE.CylinderGeometry(0.07, 0.07, 0.2, 8), glow.warm, x + DW / 2 + 0.35, 2.15, dz + 0.18, { cast: false });
    // a warm bulb inside, so the shelves aren't lost in the dark
    put(S, geo.cyl, M("#2e2a2c"), x + 0.65, H - 0.3, z + 0.6, { sx: 0.01, sy: 0.4, sz: 0.01 });
    put(S, new THREE.SphereGeometry(0.11, 10, 8), glow.warm, x + 0.65, H - 0.6, z + 0.6, { cast: false });
    put(S, new THREE.ConeGeometry(0.28, 0.2, 12, 1, true), M("#3a3436", { side: THREE.DoubleSide }), x + 0.65, H - 0.51, z + 0.6, { cast: false });
    this.barnLight = new THREE.PointLight("#ffd9a8", 0, 9, 1.5);
    this.barnLight.position.set(x, H - 0.9, z);
    this.live.add(this.barnLight);
    // a weathervane on top
    put(shell, geo.cyl, M("#2e2a2c"), x, H + h2 + 0.5, z, { sx: 0.02, sy: 0.8, sz: 0.02 });
    put(shell, geo.box, M("#2e2a2c"), x, H + h2 + 0.75, z, { sx: 0.6, sy: 0.03, sz: 0.03 });
    put(shell, geo.cone, M("#2e2a2c"), x + 0.32, H + h2 + 0.75, z, { sx: 0.06, sy: 0.12, sz: 0.03, rz: -Math.PI / 2 });
    // little windows down the sides
    for (const s of [-1, 1]) for (const e of [-1, 1]) {
      const wz = z + e * 1.2;
      const wx = x + s * (W / 2 + T / 2 + 0.01);
      put(S, geo.box, M("#3e2f2a"), wx, 1.8, wz, { sx: 0.04, sy: 0.6, sz: 0.6 });
      for (const [py, pz, sy, sz] of [[0.3, 0, 0.08, 0.7], [-0.3, 0, 0.08, 0.7], [0, 0.3, 0.6, 0.08], [0, -0.3, 0.6, 0.08], [0, 0, 0.6, 0.05]]) put(S, geo.box, trim, wx + s * 0.02, 1.8 + py, wz + pz, { sx: 0.05, sy, sz });
    }
    // you bump into the walls, but walk in through the doorway
    const hw = W / 2 + T / 2, hd = D / 2 + T / 2;
    this.wall(x - hw, z - hd, x + hw, z - hd, 5);
    this.wall(x + hw, z - hd, x + hw, z + hd, 5);
    this.wall(x - hw, z - hd, x - hw, z + hd, 5);
    this.wall(x - hw, z + hd, x - DW / 2, z + hd, 5);
    this.wall(x + DW / 2, z + hd, x + hw, z + hd, 5);
    put(S, geo.box, new THREE.MeshStandardMaterial({ map: texture("wood", ["#8c6d50", "#7a5d44"], 1), roughness: 0.9 }), x, H - 0.04, z, { sx: W - T, sy: 0.08, sz: D - T, cast: false });
    for (let i = -2; i <= 2; i++) put(S, geo.box, M(WOOD_D), x + i * 1.3, H - 0.16, z, { sx: 0.14, sy: 0.16, sz: D - T, cast: false });
    (this.world.ceilings ||= []).push({ test: (p) => this.inBarn(p), y: H - 0.3 });
    this.storage(x, z, W, D);
  }
  inBarn(p) {
    const lp = this.room.group.worldToLocal(p.clone());
    return Math.abs(lp.x - BARN.x) < BARN.w / 2 && Math.abs(lp.z - BARN.z) < BARN.d / 2 + 0.1;
  }

  // shelves along the back, flour sacks and fruit crates on the floor: as full as our pantry
  storage(x, z, W, D) {
    const S = this.still;
    const wood = M(WOOD), dark = M(WOOD_D);
    const bz = z - D / 2 + 0.45;
    // a three-shelf rack along the back wall
    for (let i = 0; i < 3; i++) put(S, geo.box, wood, x, 0.55 + i * 0.6, bz, { sx: 4.2, sy: 0.06, sz: 0.55 });
    for (const s of [-2.05, -0.7, 0.7, 2.05]) put(S, geo.box, dark, x + s, 1.0, bz, { sx: 0.07, sy: 1.95, sz: 0.55 });
    this.circle(x - 1.4, bz, 0.45);
    this.circle(x, bz, 0.45);
    this.circle(x + 1.4, bz, 0.45);
    const stock = (this.stockShow = { milk: [], egg: [], butter: [], flour: [], fruit: [] });
    const L = this.live;
    // milk: glass bottles on the top shelf
    const bottle = new THREE.CylinderGeometry(0.06, 0.07, 0.24, 10);
    const milkM = S_("#fbf8f2"), cap = S_("#4f8fc0");
    for (let i = 0; i < 12; i++) {
      const g = new THREE.Group();
      g.position.set(x - 1.95 + i * 0.335, 1.75 + 0.12, bz + (i % 2 ? 0.08 : -0.08));
      put(g, bottle, milkM, 0, 0, 0, { cast: false });
      put(g, geo.cyl, cap, 0, 0.13, 0, { sx: 0.045, sy: 0.03, sz: 0.045, cast: false });
      L.add(g);
      stock.milk.push(g);
    }
    // eggs: in trays on the middle shelf
    for (let t = 0; t < 3; t++) put(S, geo.box, M("#d9c6a6"), x - 1.4 + t * 0.95, 1.2, bz, { sx: 0.8, sy: 0.04, sz: 0.42, cast: false });
    for (let i = 0; i < 18; i++) {
      const t = Math.floor(i / 6), k = i % 6;
      const e = put(L, geo.ball, S_(i % 3 ? "#faf4ea" : "#e9cba6"), x - 1.65 + t * 0.95 + (k % 3) * 0.25, 1.27, bz - 0.1 + Math.floor(k / 3) * 0.2, { sx: 0.06, sy: 0.075, sz: 0.06, cast: false });
      stock.egg.push(e);
    }
    put(S, geo.box, M("#d9c6a6"), x + 1.55, 1.2, bz, { sx: 0.7, sy: 0.04, sz: 0.42, cast: false });
    // butter: wrapped blocks on the bottom shelf
    for (let i = 0; i < 10; i++) {
      const b = put(L, geo.box, S_(i % 2 ? "#f6e08a" : "#f1d76e"), x - 1.8 + (i % 5) * 0.32, 0.64, bz - 0.1 + Math.floor(i / 5) * 0.2, { sx: 0.22, sy: 0.12, sz: 0.12, cast: false });
      stock.butter.push(b);
    }
    // flour: sacks stacked on the floor, left
    for (let i = 0; i < 10; i++) {
      const row = Math.floor(i / 4), k = i % 4;
      const sx = x - W / 2 + 0.55 + (k % 2) * 0.6, sz = z - 0.6 + Math.floor(k / 2) * 0.55;
      const g = new THREE.Group();
      g.position.set(sx, 0.25 + row * 0.38, sz);
      g.rotation.y = (i * 0.7) % 0.6 - 0.3;
      put(g, geo.ball, S_("#ece2cf"), 0, 0, 0, { sx: 0.26, sy: 0.2, sz: 0.2, cast: false });
      put(g, geo.cyl, S_("#c9a46a"), 0, 0.2, 0, { sx: 0.06, sy: 0.08, sz: 0.06, cast: false });
      L.add(g);
      stock.flour.push(g);
    }
    this.circle(x - W / 2 + 0.85, z - 0.3, 0.75);
    // fruit: wooden crates on the right, filled with cherries, apples and oranges
    for (let c = 0; c < 2; c++) {
      const cx = x + W / 2 - 0.65, cz = z - 0.5 + c * 0.75;
      for (const [px, pz, sx, sz] of [[0, 0.3, 0.7, 0.05], [0, -0.3, 0.7, 0.05], [0.33, 0, 0.05, 0.6], [-0.33, 0, 0.05, 0.6]]) put(S, geo.box, wood, cx + px, 0.2, cz + pz, { sx, sy: 0.36, sz, cast: false });
      put(S, geo.box, dark, cx, 0.05, cz, { sx: 0.68, sy: 0.04, sz: 0.58, cast: false });
      for (let i = 0; i < 9; i++) {
        const f = put(L, geo.ball, S_(["#d6334f", "#e5893a", "#c62f3e"][(i + c) % 3]), cx - 0.2 + (i % 3) * 0.2, 0.15, cz - 0.17 + Math.floor((i % 9) / 3) * 0.17, { s: 0.08, cast: false });
        stock.fruit.push(f);
      }
    }
    this.circle(x + W / 2 - 0.65, z - 0.12, 0.75);
    this.item("farm-pantry", "our storage 🧺", x, z + 0.3, "pantry", {}, 1.6);
    this.showStock();
    this.pantry?.onChange(() => this.showStock());
  }
  showStock() {
    const have = this.pantry?.state.have || {};
    for (const [k, list] of Object.entries(this.stockShow || {})) list.forEach((o, i) => (o.visible = i < (have[k] || 0)));
  }

  silo(x, z) {
    const S = this.still;
    const metal = M("#c3c8cc", { metalness: 0.35, roughness: 0.5 });
    put(S, new THREE.CylinderGeometry(1.25, 1.25, 6.4, 20), metal, x, 3.2, z);
    for (let y = 0.6; y < 6.4; y += 0.8) put(S, new THREE.TorusGeometry(1.26, 0.035, 4, 24), M("#9ea5ab", { metalness: 0.4, roughness: 0.5 }), x, y, z, { rx: Math.PI / 2, cast: false });
    put(S, new THREE.SphereGeometry(1.32, 20, 8, 0, TAU, 0, Math.PI / 2), M("#8f989f", { metalness: 0.4, roughness: 0.45 }), x, 6.4, z);
    put(S, geo.cyl, M("#9a948e"), x, 0.15, z, { sx: 1.4, sy: 0.3, sz: 1.4 });
    // a ladder up the side facing the yard
    const lx = x - 1.27, lz = z + 0.1;
    for (const o of [-0.2, 0.2]) put(S, geo.box, M("#5c5658"), lx, 3.2, lz + o, { sx: 0.04, sy: 6.2, sz: 0.04 });
    for (let y = 0.4; y < 6.2; y += 0.35) put(S, geo.box, M("#5c5658"), lx, y, lz, { sx: 0.03, sy: 0.03, sz: 0.4 });
    this.circle(x, z, 1.4);
  }

  // a fenced pasture with an opening towards the lane, a trough and a hay rack
  pasture(zone, name) {
    const S = this.still;
    const loop = roundRect({ x: zone.x, z: zone.z, hw: zone.hw + 0.6, hd: zone.hd + 0.6, r: 2.2 });
    const gx = zone.x - Math.sign(zone.x) * (zone.hw + 0.6);
    this.rails(withGap(loop, gx, zone.z, 2.2));
    zone.gate = [gx, zone.z];
    // a little swing gate, standing open against the fence
    const s = -Math.sign(zone.x);
    const hinge = new THREE.Group();
    hinge.position.set(gx, 0, zone.z + 1.1);
    hinge.rotation.y = s * 0.25; // swung open, out towards the lane
    S.add(hinge);
    for (const y of [0.35, 0.65, 0.95]) put(hinge, geo.box, M(WOOD), 0.05 * s, y, 1.0, { sx: 0.05, sy: 0.08, sz: 2.0 });
    put(hinge, geo.box, M(WOOD), 0.05 * s, 0.65, 1.0, { sx: 0.05, sy: 0.08, sz: 2.2, rx: 0.3 });
    // a sign by the opening
    const sign = plank(name, 1.3, 0.38, { size: name.length > 8 ? 54 : 66 });
    sign.position.set(gx + s * 0.35, 1.25, zone.z - 1.55);
    sign.rotation.y = s > 0 ? Math.PI / 2 : -Math.PI / 2;
    S.add(sign);
    put(S, geo.box, M(WOOD_D), gx + s * 0.35, 0.6, zone.z - 1.55, { sx: 0.08, sy: 1.2, sz: 0.08 });
    // the trough, at the back
    const tx = zone.x + Math.sign(zone.x) * 1.6, tz = zone.z - zone.hd + 0.6;
    put(S, geo.box, M(WOOD_D), tx, 0.28, tz, { sx: 1.6, sy: 0.45, sz: 0.55 });
    put(S, geo.box, M("#7fb7cf", { roughness: 0.15 }), tx, 0.49, tz, { sx: 1.45, sy: 0.02, sz: 0.4 });
    this.circle(tx - 0.5, tz, 0.4);
    this.circle(tx + 0.5, tz, 0.4);
    // a hay rack
    const hx = zone.x - Math.sign(zone.x) * 1.4, hz = zone.z - zone.hd + 0.5;
    put(S, geo.box, M(WOOD), hx, 0.55, hz, { sx: 1.3, sy: 0.08, sz: 0.5 });
    for (const e of [-1, 1]) put(S, geo.box, M(WOOD_D), hx + e * 0.6, 0.5, hz, { sx: 0.08, sy: 1.0, sz: 0.08 });
    for (let i = 0; i < 6; i++) put(S, geo.lowball, M(i % 2 ? "#d9b86a" : "#c9a656"), hx - 0.5 + i * 0.2, 0.72, hz, { sx: 0.2, sy: 0.16, sz: 0.2 });
    this.circle(hx, hz, 0.6);
  }

  coop() {
    const S = this.still;
    const zone = RUN;
    const x = zone.x - 0.8, z = zone.z - 1.4;
    const wall = new THREE.MeshStandardMaterial({ map: texture("wood", ["#dfe5cf", "#cdd6ba"], 0.5), roughness: 0.9, flatShading: true });
    const roof = new THREE.MeshStandardMaterial({ map: texture("shingles", ["#8a4a44", "#733c37"], 0.8), roughness: 0.95, flatShading: true });
    // on short legs
    for (const [lx, lz] of [[-0.85, -0.55], [0.85, -0.55], [-0.85, 0.55], [0.85, 0.55]]) put(S, geo.box, M(WOOD_D), x + lx, 0.25, z + lz, { sx: 0.1, sy: 0.5, sz: 0.1 });
    put(S, geo.box, wall, x, 1.05, z, { sx: 1.9, sy: 1.1, sz: 1.3 });
    const gable = new THREE.Shape();
    gable.moveTo(-0.95, 0);
    gable.lineTo(0.95, 0);
    gable.lineTo(0, 0.6);
    const gg = new THREE.ExtrudeGeometry(gable, { depth: 1.3, bevelEnabled: false });
    gg.translate(0, 0, -0.65);
    put(S, gg, wall, x, 1.6, z);
    for (const s of [-1, 1]) put(S, geo.box, roof, x + s * 0.52, 1.92, z, { sx: 1.22, sy: 0.08, sz: 1.55, rz: s * -0.56 });
    put(S, geo.box, M(CREAM), x, 1.05, z + 0.7, { sx: 1.95, sy: 0.08, sz: 0.04 }); // in front of the door, never in its plane
    put(S, geo.box, M("#3e2f2a"), x - 0.4, 0.79, z + 0.665, { sx: 0.42, sy: 0.4, sz: 0.03 });
    put(S, geo.cyl, M(CREAM), x + 0.35, 1.25, z + 0.66, { sx: 0.18, sy: 0.04, sz: 0.18, rx: Math.PI / 2 });
    put(S, geo.cyl, M("#3e2f2a"), x + 0.35, 1.25, z + 0.68, { sx: 0.13, sy: 0.04, sz: 0.13, rx: Math.PI / 2 });
    // the little ramp, with slats
    put(S, geo.box, M(WOOD), x - 0.4, 0.3, z + 1.08, { sx: 0.4, sy: 0.04, sz: 0.95, rx: 0.55 });
    for (let i = 0; i < 4; i++) put(S, geo.box, M(WOOD_D), x - 0.4, 0.14 + i * 0.12, z + 1.35 - i * 0.2, { sx: 0.4, sy: 0.02, sz: 0.03 });
    // nest boxes on the side, where the eggs turn up
    this.nest = new THREE.Group();
    this.nest.position.set(x + 1.1, 0, z);
    this.live.add(this.nest);
    put(this.nest, geo.box, M(WOOD), 0.15, 0.85, 0, { sx: 0.32, sy: 0.4, sz: 1.0 });
    put(this.nest, geo.box, M("#d9b86a"), 0.17, 1.06, 0, { sx: 0.26, sy: 0.04, sz: 0.92 });
    put(this.nest, geo.box, roof, 0.18, 1.18, 0, { sx: 0.42, sy: 0.05, sz: 1.08, rz: -0.3 });
    this.eggs = [];
    for (let i = 0; i < EGG_MAX; i++) {
      const e = put(this.nest, geo.ball, S_(i % 2 ? "#e9cba6" : "#faf4ea"), 0.1 + (i % 2) * 0.1, 1.11, -0.38 + i * 0.15, { sx: 0.045, sy: 0.058, sz: 0.045 });
      e.visible = false;
      this.eggs.push(e);
    }
    this.circle(x, z, 1.15);
    this.circle(x + 1.15, z, 0.45);
    // the run: posts and a top rail with chicken wire between, open towards the lane
    const loop = roundRect({ x: zone.x, z: zone.z, hw: zone.hw + 0.5, hd: zone.hd + 0.5, r: 1.2 });
    const gate = [zone.x + 1.2, zone.z + zone.hd + 0.5]; // the front, onto the path along the cow pasture
    const run = withGap(loop, gate[0], gate[1], 1.6);
    this.rails(run, { h: 1.0, rails: 2, color: "#9a7a5e" });
    const wire = this.wire();
    for (let i = 0; i < run.length - 1; i++) {
      const [ax, az] = run[i], [bx, bz] = run[i + 1];
      const len = Math.hypot(bx - ax, bz - az);
      if (len > 1.5) continue;
      const m = new THREE.Mesh(new THREE.PlaneGeometry(len, 0.9), wire);
      m.position.set((ax + bx) / 2, 0.47, (az + bz) / 2);
      m.rotation.y = Math.atan2(bx - ax, bz - az) - Math.PI / 2;
      S.add(m);
    }
    zone.gate = gate;
    this.item("farm-eggs", () => {
      const n = this.eggCount();
      return n ? `collect the eggs 🥚 (${n})` : "the hens are laying… 🐔";
    }, x + 1.6, z + 0.4, "eggs", {}, 1.6, [this.nest]);
  }
  wire() {
    const c = document.createElement("canvas");
    c.width = c.height = 64;
    const g = c.getContext("2d");
    g.strokeStyle = "rgba(220,224,228,0.9)";
    g.lineWidth = 2;
    for (let r = 0; r < 4; r++) for (let q = 0; q < 4; q++) {
      const cx = q * 16 + (r % 2) * 8, cy = r * 16;
      g.beginPath();
      for (let k = 0; k <= 6; k++) {
        const a = (k / 6) * TAU + Math.PI / 6;
        g[k ? "lineTo" : "moveTo"](cx + Math.cos(a) * 8, cy + Math.sin(a) * 8);
      }
      g.stroke();
    }
    const t = new THREE.CanvasTexture(c);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(6, 4);
    // (cut out with alphaTest, not blended: so the fence panels can be merged into one mesh)
    return new THREE.MeshStandardMaterial({ map: t, alphaTest: 0.3, side: THREE.DoubleSide, roughness: 0.6, metalness: 0.3 });
  }

  // a vegetable patch on the left of the gate, pumpkins on the right
  crops() {
    const S = this.still;
    const R = mulberry(41);
    const soil = M("#6e5140");
    for (let r = 0; r < 3; r++) {
      const z = 8.8 + r * 1.0;
      put(S, geo.box, soil, -7.2, 0.06, z, { sx: 7, sy: 0.14, sz: 0.6, cast: false });
      for (let k = 0; k < 11; k++) {
        const x = -10.3 + k * 0.62 + (R() - 0.5) * 0.08;
        if (r === 1) {
          // cabbages
          put(S, geo.lowball, M("#a7d18a"), x, 0.24, z, { sx: 0.2, sy: 0.17, sz: 0.2 });
          for (let l = 0; l < 4; l++) put(S, geo.lowball, M("#7fb26a"), x + Math.cos(l * 1.6) * 0.15, 0.2, z + Math.sin(l * 1.6) * 0.15, { sx: 0.13, sy: 0.04, sz: 0.11, ry: l * 1.6 });
        } else {
          // carrot tops and lettuce
          if (r === 0) for (let l = 0; l < 4; l++) put(S, geo.cone, M("#5f9e4c"), x + (l - 1.5) * 0.04, 0.3, z, { sx: 0.02, sy: 0.3, sz: 0.02, rz: (l - 1.5) * 0.3 });
          else put(S, geo.lowball, M("#c3e09a"), x, 0.2, z, { sx: 0.17, sy: 0.12, sz: 0.17 });
        }
      }
    }
    // a scarecrow keeping watch
    const sx = -4.4, sz = 10.6;
    put(S, geo.cyl, M(WOOD_D), sx, 0.9, sz, { sx: 0.05, sy: 1.8, sz: 0.05 });
    put(S, geo.box, M(WOOD_D), sx, 1.35, sz, { sx: 1.1, sy: 0.05, sz: 0.05 });
    put(S, geo.box, M("#6f7f9e"), sx, 1.2, sz, { sx: 0.5, sy: 0.55, sz: 0.25 });
    put(S, geo.box, M("#b8623e"), sx, 1.35, sz, { sx: 1.0, sy: 0.16, sz: 0.2 });
    put(S, geo.ball, M("#e8d3a8"), sx, 1.68, sz, { s: 0.18 });
    put(S, geo.cyl, M("#c9a656"), sx, 1.84, sz, { sx: 0.32, sy: 0.03, sz: 0.32 });
    put(S, geo.cone, M("#c9a656"), sx, 1.92, sz, { sx: 0.16, sy: 0.18, sz: 0.16 });
    // pumpkins among big leaves
    for (let k = 0; k < 9; k++) {
      const x = 4.2 + R() * 6.6, z = 8.6 + R() * 2.4;
      for (let l = 0; l < 3; l++) put(S, new THREE.CircleGeometry(0.32, 7), M("#5d8f49", { side: THREE.DoubleSide }), x + (R() - 0.5) * 0.8, 0.05 + l * 0.01, z + (R() - 0.5) * 0.8, { rx: -Math.PI / 2 + (R() - 0.5) * 0.4, rz: R() * 6, cast: false });
      if (k % 3 === 2) continue;
      const s = 0.22 + R() * 0.16;
      put(S, new THREE.SphereGeometry(1, 12, 8), M(k % 4 ? "#e5893a" : "#efe3c8", { flatShading: false }), x, s * 0.75, z, { sx: s * 1.2, sy: s * 0.85, sz: s * 1.2 });
      put(S, geo.cyl, M("#5b4a2e"), x, s * 1.5, z, { sx: 0.03, sy: 0.12, sz: 0.03, rz: 0.2 });
    }
  }

  yard() {
    const S = this.still;
    // the butter churn and milk cans by the barn doors
    const cx = 2.9, cz = -4.1;
    put(S, new THREE.CylinderGeometry(0.26, 0.34, 0.9, 12), M("#a77a52"), cx, 0.45, cz);
    for (const y of [0.15, 0.75]) put(S, new THREE.TorusGeometry(0.3 - y * 0.06, 0.022, 4, 16), M("#4a4446"), cx, y, cz, { rx: Math.PI / 2 });
    put(S, geo.cyl, M("#d8c8ae"), cx, 1.15, cz, { sx: 0.025, sy: 0.6, sz: 0.025 });
    put(S, geo.cyl, M("#d8c8ae"), cx, 1.46, cz, { sx: 0.08, sy: 0.04, sz: 0.08 });
    this.circle(cx, cz, 0.4);
    for (const [x, z] of [[3.6, -4.6], [3.95, -4.2]]) {
      put(S, new THREE.CylinderGeometry(0.17, 0.19, 0.6, 14), M("#d9dee2", { metalness: 0.55, roughness: 0.3 }), x, 0.3, z);
      put(S, new THREE.CylinderGeometry(0.1, 0.17, 0.14, 14), M("#d9dee2", { metalness: 0.55, roughness: 0.3 }), x, 0.67, z);
      put(S, geo.cyl, M("#c3c9ce", { metalness: 0.55, roughness: 0.3 }), x, 0.78, z, { sx: 0.1, sy: 0.06, sz: 0.1 });
    }
    this.item("farm-churn", () => {
      const m = this.pantry?.state.have.milk || 0;
      return m >= 2 ? "churn butter 🧈 (2 🥛)" : "the butter churn 🧈 · needs 2 milk";
    }, cx, cz + 0.9, "churn", {}, 1.5);
    // hay: round bales and a stack of square ones
    const hay = M("#d4b064"), hayEnd = M("#c49d52");
    for (const [x, z, ry] of [[4.6, -6.6, -0.2]]) {
      put(S, new THREE.CylinderGeometry(0.62, 0.62, 1.1, 16), hay, x, 0.62, z, { rz: Math.PI / 2, ry });
      for (const e of [-1, 1]) put(S, new THREE.CylinderGeometry(0.5, 0.5, 0.02, 16), hayEnd, x + Math.cos(ry) * e * 0.56, 0.62, z - Math.sin(ry) * e * 0.56, { rz: Math.PI / 2, ry });
      this.circle(x, z, 0.7);
    }
    for (const [x, y, z, ry] of [[5.0, 0.28, -3.0, 1.6], [5.0, 0.28, -3.75, 1.5], [5.0, 0.82, -3.38, 1.55]]) {
      put(S, geo.box, hay, x, y, z, { sx: 0.6, sy: 0.55, sz: 0.95, ry });
      for (const e of [-1, 1]) put(S, geo.box, M("#8a6a3a"), x, y, z + e * 0.2, { sx: 0.62, sy: 0.57, sz: 0.03, ry });
    }
    this.circle(5.0, -3.38, 0.75);
    // a pitchfork leaning on the stack, and a wheelbarrow
    put(S, geo.cyl, M(WOOD), 4.4, 0.85, -3.4, { sx: 0.025, sy: 1.6, sz: 0.025, rz: 0.25 });
    const wb = new THREE.Group();
    wb.position.set(2.5, 0, 11.3);
    wb.rotation.y = 0.9;
    S.add(wb);
    put(wb, geo.box, M("#6f8f7a"), 0, 0.5, 0, { sx: 0.6, sy: 0.3, sz: 0.85 });
    put(wb, geo.box, M("#d4b064"), 0, 0.66, 0, { sx: 0.52, sy: 0.08, sz: 0.75 });
    put(wb, geo.cyl, M("#3e3a3c"), 0, 0.22, 0.55, { sx: 0.2, sy: 0.07, sz: 0.2, rz: Math.PI / 2 });
    for (const s of [-1, 1]) {
      put(wb, geo.cyl, M(WOOD), s * 0.22, 0.45, -0.55, { sx: 0.025, sy: 0.7, sz: 0.025, rx: 1.2 });
      put(wb, geo.box, M(WOOD_D), s * 0.22, 0.2, -0.25, { sx: 0.04, sy: 0.4, sz: 0.04 });
    }
    this.circle(2.5, 11.3, 0.6);
    // a cast-iron water pump
    put(S, geo.box, M("#9a948e"), 1.75, 0.1, -3.3, { sx: 0.6, sy: 0.2, sz: 0.6 });
    put(S, geo.cyl, M("#3f4a4f", { metalness: 0.4 }), 1.75, 0.75, -3.3, { sx: 0.09, sy: 1.1, sz: 0.09 });
    put(S, geo.cyl, M("#3f4a4f", { metalness: 0.4 }), 1.75, 1.15, -3.15, { sx: 0.04, sy: 0.3, sz: 0.04, rx: 1.3 });
    put(S, geo.box, M("#3f4a4f", { metalness: 0.4 }), 1.75, 1.35, -3.45, { sx: 0.04, sy: 0.04, sz: 0.5, rx: -0.4 });
    put(S, geo.cyl, M("#7a5a43"), 1.75, 0.2, -2.9, { sx: 0.2, sy: 0.3, sz: 0.2 });
    this.circle(1.75, -3.3, 0.4);
    // an old oak behind the sheep, shading the corner
    const ox = 10.4, oz = -4.8;
    put(S, new THREE.CylinderGeometry(0.28, 0.42, 2.6, 9), M("#6b4f3a"), ox, 1.3, oz);
    for (const [dx, dy, dz, r, c] of [[0, 3.4, 0, 1.6, "#5d8f4f"], [1.0, 3.0, 0.4, 1.1, "#6fa35a"], [-0.9, 3.1, -0.3, 1.2, "#4f8046"], [0.2, 4.2, -0.2, 1.1, "#6fa35a"], [-0.3, 2.8, 0.9, 0.9, "#5d8f4f"]]) put(S, geo.lowball, M(c), ox + dx, dy, oz + dz, { s: r });
    this.circle(ox, oz, 0.5);
  }

  addAnimal(a, zone, info) {
    Object.assign(a, info, { zone, x: 0, z: 0, yaw: Math.random() * TAU, tx: 0, tz: 0, wait: Math.random() * 3, phase: Math.random() * TAU, happy: 0 });
    const p = this.spot(zone);
    a.x = a.tx = p[0];
    a.z = a.tz = p[1];
    a.g.position.set(a.x, 0, a.z);
    a.g.userData.live = true;
    this.live.add(a.g);
    this.animals.push(a);
    if (a.kind === "cow" || a.kind === "goat") {
      a.it = this.item(`farm-${a.id}`, () => {
        const left = (this.pantry?.state.cows[a.id] || 0) + MILK_REST - Date.now();
        return left > 0 ? `${a.name} is resting ♡ (${Math.ceil(left / 60000)}m)` : `milk ${a.name} 🥛`;
      }, a.x, a.z, "milk", { id: a.id }, a.kind === "cow" ? 1.9 : 1.4, [a.g]);
    } else if (a.kind === "sheep") a.it = this.item(`farm-${a.id}`, `pet ${a.name} ♡`, a.x, a.z, "pet", { id: a.id }, 1.3, [a.g]);
    else if (a.kind === "hen" || a.kind === "rooster") a.it = this.item(`farm-${a.id}`, a.kind === "rooster" ? "say hi to the rooster 🐓" : "pet the hen 🐔", a.x, a.z, "pet", { id: a.id }, 0.9, [a.g]);
  }
  // somewhere free in the zone, away from its opening and the others
  spot(zone) {
    for (let k = 0; k < 24; k++) {
      const x = zone.x + (Math.random() * 2 - 1) * (zone.hw - 0.7);
      const z = zone.z + (Math.random() * 2 - 1) * (zone.hd - 0.7);
      if (zone.gate && Math.hypot(x - zone.gate[0], z - zone.gate[1]) < 2) continue;
      if (zone === RUN && x < zone.x + 0.6 && z < zone.z - 0.4) continue; // the hen house
      if (this.animals.some((o) => o.zone === zone && Math.hypot(o.tx - x, o.tz - z) < 1.2)) continue;
      return [x, z];
    }
    return [zone.x, zone.z];
  }

  eggCount(now = Date.now()) {
    const st = this.pantry?.state;
    if (!st) return 0;
    if (!st.eggT) return 3; // a few waiting the very first time
    return Math.max(0, Math.min(EGG_MAX, Math.floor((now - st.eggT) / EGG_EVERY)));
  }

  use(a) {
    const p = this.pantry;
    const an = this.animals.find((o) => o.id === a.id);
    if (a.what === "pantry") {
      const hv = p?.state.have || {};
      return this.toast(`🧺 our pantry · 🥛 ${hv.milk || 0} · 🥚 ${hv.egg || 0} · 🧈 ${hv.butter || 0} · 🌾 ${hv.flour || 0} · 🍒 ${hv.fruit || 0}`);
    }
    if (a.what === "pet" && an) {
      an.happy = 1.4;
      an.wait = 2;
      this.audio.sfx("kiss");
      this.confetti?.(this.world.toWorld(this.room, an.x, 1, an.z));
      const says = { sheep: [`${an.name} goes baa ♡`, `so fluffy… ${an.name} leans into you ☁️`], hen: ["bok bok ♡", "the hen fluffs up happily 🐔"], rooster: ["cock-a-doodle-doo! 🐓", "the rooster puffs out his chest 🐓"] }[an.kind] || ["♡"];
      return this.toast(says[Math.floor(Math.random() * says.length)]);
    }
    if (this.isGuest) return this.toast("toto & dodo look after the animals here ♡");
    if (a.what === "milk" && an) {
      const left = (p.state.cows[an.id] || 0) + MILK_REST - Date.now();
      if (left > 0) return this.toast(`${an.name} needs a little rest ♡ come back in ${Math.ceil(left / 60000)} min`);
      const n = an.kind === "cow" ? 2 : 1;
      p.state.cows[an.id] = Date.now();
      p.add("milk", n);
      an.happy = 1.4;
      an.wait = 3;
      this.audio.sfx("collect");
      this.confetti?.(this.world.toWorld(this.room, an.x, 1, an.z));
      return this.toast(`🥛 ${an.name} gave ${n} milk ♡ · ${p.state.have.milk} in the pantry for the bakery`);
    }
    if (a.what === "eggs") {
      const n = this.eggCount();
      if (!n) return this.toast(`no eggs yet 🐔 the hens lay one every ${EGG_EVERY / 60000} minutes`);
      p.state.eggT = Date.now();
      p.add("egg", n);
      this.audio.sfx("pop");
      this.confetti?.(this.nest.getWorldPosition(new THREE.Vector3()).setY(1.2));
      return this.toast(`🥚 ${n} egg${n > 1 ? "s" : ""} into the basket · ${p.state.have.egg} in the pantry`);
    }
    if (a.what === "churn") {
      if ((p.state.have.milk || 0) < 2) return this.toast("the churn needs 2 milk 🥛 · milk a cow first");
      p.state.have.milk -= 2;
      p.add("butter", 1);
      this.audio.sfx("bounce");
      return this.toast(`🧈 churn churn… fresh butter! · ${p.state.have.butter} in the pantry`);
    }
  }

  update(dt, player) {
    if (!this.room) return;
    // only animate when someone's near enough to see it
    const c = this.room.def.pos;
    if (player && Math.hypot(player.pos.x - c.x, player.pos.z - c.z) > 60) return;
    // inside the barn: the bulb comes on
    if (player && this.barnLight) {
      const inside = this.inBarn(player.pos);
      this.barnLight.intensity += ((inside ? 6 : 0) - this.barnLight.intensity) * (1 - Math.exp(-dt * 4));
    }
    const t = performance.now() / 1000;
    for (const a of this.animals) {
      a.happy = Math.max(0, a.happy - dt);
      const dx = a.tx - a.x, dz = a.tz - a.z;
      const d = Math.hypot(dx, dz);
      let moving = false;
      if (a.wait > 0) a.wait -= dt;
      else if (d < 0.08) {
        a.wait = (a.hen ? 0.8 : 3) + Math.random() * (a.hen ? 2.5 : 8);
        [a.tx, a.tz] = this.spot(a.zone);
      } else {
        const want = Math.atan2(dx, dz);
        let dy = want - a.yaw;
        dy = Math.atan2(Math.sin(dy), Math.cos(dy));
        a.yaw += dy * (1 - Math.exp(-dt * 2.5));
        if (Math.abs(dy) < 0.6) {
          const sp = Math.min(d, a.speed * dt);
          a.x += Math.sin(a.yaw) * sp;
          a.z += Math.cos(a.yaw) * sp;
          moving = true;
        }
      }
      a.g.position.set(a.x, 0, a.z);
      a.g.rotation.y = a.yaw;
      const ph = t * a.step + a.phase;
      a.legs.forEach((l, i) => (l.rotation.x = moving ? Math.sin(ph + (i % 2 ? Math.PI : 0) + (i > 1 ? Math.PI : 0)) * 0.4 : 0));
      a.body.position.y = moving ? Math.abs(Math.sin(ph)) * a.bob : a.happy > 0 ? Math.abs(Math.sin(t * 12)) * 0.06 : 0;
      // grazing (or pecking) when standing still, a happy wiggle when petted, a swishing tail
      const graze = !moving && a.wait > 0 && Math.sin(a.phase + t * 0.35) > 0;
      const pitch = a.hen ? (graze ? 0.6 + Math.max(0, Math.sin(t * 10 + a.phase)) * 0.5 : 0) : graze ? 0.85 : Math.sin(t * 0.8 + a.phase) * 0.05;
      a.head.rotation.x += (pitch - a.head.rotation.x) * (1 - Math.exp(-dt * 5));
      a.head.rotation.z = a.happy > 0 ? Math.sin(t * 14) * 0.2 : 0;
      if (a.tail) a.tail.rotation.z = Math.sin(t * (a.happy > 0 ? 12 : 2) + a.phase) * (a.happy > 0 ? 0.5 : 0.25);
      if (a.it) a.it.pos.copy(this.world.toWorld(this.room, a.x, 0, a.z)).setY(0);
    }
    const n = this.eggCount();
    this.eggs.forEach((e, i) => (e.visible = i < n));
  }
}

