// Fun extras: the sniper rifle (with little cartoon blood drops on hits),
// target boards and straw dummies, and the dookie emote.
import * as THREE from "three";
import { ISLAND_R, SPREAD } from "./world.js";

const mat = (color, extra = {}) => new THREE.MeshStandardMaterial({ color, flatShading: true, roughness: 0.6, ...extra });

export function makeRifle() {
  const r = rifleModel();
  r.group.position.set(0, -0.2, 0.05);
  r.group.rotation.set(Math.PI / 2, 0, 0);
  return r;
}

function rifleModel() {
  const g = new THREE.Group();
  const metal = mat("#2b2833", { metalness: 0.6, roughness: 0.35 });
  const wood = mat("#8a5a3c");
  const add = (geo, m, x, y, z) => {
    const mesh = new THREE.Mesh(geo, m);
    mesh.position.set(x, y, z);
    mesh.castShadow = true;
    g.add(mesh);
    return mesh;
  };
  add(new THREE.BoxGeometry(0.07, 0.1, 0.42), wood, 0, 0, -0.18); // stock
  add(new THREE.BoxGeometry(0.06, 0.08, 0.3), metal, 0, 0.02, 0.15); // receiver
  const barrel = add(new THREE.CylinderGeometry(0.018, 0.022, 0.7, 8), metal, 0, 0.03, 0.62);
  barrel.rotation.x = Math.PI / 2;
  const scope = add(new THREE.CylinderGeometry(0.03, 0.03, 0.26, 10), metal, 0, 0.1, 0.15);
  scope.rotation.x = Math.PI / 2;
  add(new THREE.CylinderGeometry(0.04, 0.03, 0.04, 10), metal, 0, 0.1, 0.3).rotation.x = Math.PI / 2;
  add(new THREE.BoxGeometry(0.04, 0.12, 0.05), wood, 0, -0.08, 0.02); // grip
  add(new THREE.BoxGeometry(0.01, 0.12, 0.01), metal, 0.05, -0.08, 0.5).rotation.z = 0.4; // bipod
  add(new THREE.BoxGeometry(0.01, 0.12, 0.01), metal, -0.05, -0.08, 0.5).rotation.z = -0.4;
  const muzzle = new THREE.Object3D();
  muzzle.position.set(0, 0.03, 0.98);
  g.add(muzzle);
  return { group: g, muzzle };
}

let glowTex;
function glowSprite(color, size) {
  if (!glowTex) {
    const c = document.createElement("canvas");
    c.width = c.height = 64;
    const x = c.getContext("2d");
    const grd = x.createRadialGradient(32, 32, 0, 32, 32, 32);
    grd.addColorStop(0, "rgba(255,255,255,1)");
    grd.addColorStop(0.35, "rgba(255,255,255,0.5)");
    grd.addColorStop(1, "rgba(255,255,255,0)");
    x.fillStyle = grd;
    x.fillRect(0, 0, 64, 64);
    glowTex = new THREE.CanvasTexture(c);
  }
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }));
  s.scale.setScalar(size);
  return s;
}

export class Fx {
  constructor({ scene, world, audio, avatar }) {
    this.scene = scene;
    this.world = world;
    this.audio = audio;
    this.avatar = avatar;
    this.particles = [];
    this.splats = [];
    this.poops = [];
    this.equipped = false;
    this.scoped = false;
    this.cool = 0;
    this.hits = 0;

    const r = rifleModel();
    this.rifle = r.group;
    this.muzzle = r.muzzle;
    this.rifle.visible = false;
    this.flash = glowSprite("#ffcf70", 0.9);
    this.flash.material.opacity = 0;
    this.scene.add(this.flash);
    // the gun rides in the right hand
    const right = avatar.arms?.[1];
    if (right) right.elbow.add(this.rifle);
    this.rifle.position.set(0, -0.2, 0.05);
    this.rifle.rotation.set(Math.PI / 2, 0, 0);

    this.dropGeo = new THREE.SphereGeometry(0.045, 6, 4);
    this.dropMat = new THREE.MeshStandardMaterial({ color: "#c8102e", roughness: 0.3 });
    this.splatGeo = new THREE.CircleGeometry(0.09, 8);
    this.dustMat = new THREE.MeshStandardMaterial({ color: "#d8ccc0", transparent: true, opacity: 0.8, flatShading: true });
    this.tracerMat = new THREE.LineBasicMaterial({ color: "#fff6d0", transparent: true, opacity: 0.9 });
    // sprint smoke and sparkles
    this.puffGeo = new THREE.IcosahedronGeometry(0.16, 1);
    this.sparkGeo = new THREE.OctahedronGeometry(0.05, 0);

    this.buildTargets();
  }

  // re-attach after the avatar is rebuilt in the editor
  reattach(avatar) {
    this.avatar = avatar;
    avatar.arms?.[1]?.elbow.add(this.rifle);
  }

  // bullseye boards on the floating islets and straw dummies near the sky deck
  buildTargets() {
    this.targets = [];
    const board = (pos, face, islet) => {
      const g = new THREE.Group();
      g.position.copy(pos);
      g.lookAt(face);
      // the board rides on its islet, so it bobs with it
      if (islet) g.position.sub(islet.position);
      const rings = ["#ffffff", "#e2557f", "#ffffff", "#e2557f", "#ffd166"];
      rings.forEach((c, i) => {
        const m = new THREE.Mesh(new THREE.CylinderGeometry(1.1 - i * 0.22, 1.1 - i * 0.22, 0.08 + i * 0.01, 20), mat(c));
        m.rotation.x = Math.PI / 2;
        g.add(m);
      });
      const post = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.1, 2, 6), mat("#8a5a3c"));
      post.position.set(0, -1.6, -0.1);
      g.add(post);
      g.traverse((o) => (o.userData.target = { kind: "board", group: g }));
      (islet || this.scene).add(g);
      this.targets.push(g);
    };
    // the boards stand a little above each islet's grass
    for (const islet of this.world.islets || []) {
      const p = islet.position.clone().add(new THREE.Vector3(1.6, 2.4, 0));
      board(p, new THREE.Vector3(0, p.y, 0), islet);
    }
    // straw dummies
    const straw = mat("#e8c46a");
    const sack = mat("#c9a27e");
    // (off by the north-east fence, clear of dodo's bakery)
    const spot = new THREE.Vector3(Math.sin(THREE.MathUtils.degToRad(40)) * 87 * SPREAD, 0, Math.cos(THREE.MathUtils.degToRad(40)) * 87 * SPREAD);
    for (let i = 0; i < 3; i++) {
      const g = new THREE.Group();
      const side = new THREE.Vector3(-spot.z, 0, spot.x).normalize();
      g.position.copy(spot).addScaledVector(side, (i - 1) * 2.4);
      g.lookAt(0, 0, 0);
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.06, 1.8, 5), mat("#8a5a3c"));
      pole.position.y = 0.9;
      const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.28, 0.5, 2, 8), straw);
      body.position.y = 1.15;
      const head = new THREE.Mesh(new THREE.SphereGeometry(0.22, 8, 6), sack);
      head.position.y = 1.75;
      const arms = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 1.2, 5), straw);
      arms.rotation.z = Math.PI / 2;
      arms.position.y = 1.35;
      g.add(pole, body, head, arms);
      g.traverse((o) => {
        o.castShadow = true;
        o.userData.target = { kind: "dummy", group: g, wobble: 0 };
      });
      this.scene.add(g);
      this.world.circles.push({ x: g.position.x, z: g.position.z, r: 0.3 });
      this.targets.push(g);
    }
  }

  toggle() {
    this.equipped = !this.equipped;
    this.rifle.visible = this.equipped;
    if (!this.equipped) this.scoped = false;
    this.audio.sfx(this.equipped ? "equip" : "pop");
    return this.equipped;
  }

  // ray from the camera through the middle of the screen. Animals are never
  // hit (bullets pass through them); a little aim assist pulls the shot onto
  // the boy, your partner, a dummy or a board when it's close to the crosshair.
  fire(camera, raycaster, { onRemote, onBoy, people = [] }) {
    if (!this.equipped || this.cool > 0) return null;
    this.cool = 0.75;
    this.audio.sfx("shot");
    const muzzle = new THREE.Vector3();
    this.muzzle.getWorldPosition(muzzle);
    this.flash.position.copy(muzzle);
    this.flash.material.opacity = 1;
    raycaster.setFromCamera({ x: 0, y: 0 }, camera);
    raycaster.camera = camera;
    raycaster.far = 400;
    const ray = raycaster.ray;
    const dir = ray.direction.clone();

    const isAnimal = (o) => {
      for (let p = o; p; p = p.parent) {
        const c = p.userData.creature;
        if (c && c.kind !== "boy") return true;
      }
      return false;
    };
    const isMe = (o) => {
      for (let p = o; p; p = p.parent) if (p === this.avatar.root) return true;
      return false;
    };
    const hits = raycaster.intersectObjects(this.scene.children, true).filter((h) => {
      const o = h.object;
      if (o.isSprite || o.isPoints || o.isLine || !o.visible) return false;
      if (o.material?.transparent && o.material.opacity < 0.5) return false;
      return !isMe(o) && !isAnimal(o);
    });
    const first = hits[0];

    // aim assist candidates
    const cands = [
      ...people,
      ...this.targets.map((g) => ({ pos: g.getWorldPosition(new THREE.Vector3()).add(new THREE.Vector3(0, g.children[0]?.userData.target?.kind === "dummy" ? 1.3 : 0, 0)), info: { kind: g.children[0].userData.target.kind, data: g.children[0].userData.target } })),
    ];
    const limit = THREE.MathUtils.degToRad(this.scoped ? 1.3 : 3.2);
    let assist = null;
    let bestAng = limit;
    const v = new THREE.Vector3();
    for (const c of cands) {
      v.subVectors(c.pos, ray.origin);
      const dist = v.length();
      if (dist > 320 || dist < 0.5) continue;
      const ang = v.normalize().angleTo(dir);
      if (ang < bestAng) {
        bestAng = ang;
        assist = { ...c, dist };
      }
    }

    let point;
    let info = null;
    if (assist && (!first || first.distance > assist.dist - 1.2)) {
      point = assist.pos.clone();
      info = assist.info;
    } else if (first) {
      point = first.point.clone();
      for (let p = first.object; p && !info; p = p.parent) {
        if (p.userData.target) info = { kind: p.userData.target.kind, data: p.userData.target };
        else if (p.userData.creature?.kind === "boy") info = { kind: "boy", data: p.userData.creature };
        else if (p.userData.remote) info = { kind: "remote", data: p.userData.remote };
      }
    } else point = ray.at(300, new THREE.Vector3());

    this.tracer(muzzle, point);
    this.lastShot = { a: muzzle.clone(), b: point.clone() };
    if (!info) {
      if (first) this.dust(point);
      return { kind: "miss" };
    }
    if (info.kind === "board") {
      this.dust(point, "#ffd166");
      this.audio.sfx("ding");
      this.hits++;
      return { kind: "board", hit: true };
    }
    if (info.kind === "dummy") {
      info.data.wobble = 1;
      this.blood(point, dir);
      this.audio.sfx("thud");
      return { kind: "dummy", hit: true };
    }
    if (info.kind === "boy") {
      this.blood(point, dir);
      onBoy?.(info.data);
      return { kind: "boy", hit: true };
    }
    if (info.kind === "remote") {
      this.blood(point, dir);
      onRemote?.(info.data, point);
      return { kind: "remote", hit: true };
    }
    return { kind: "miss" };
  }


  tracer(a, b) {
    const geo = new THREE.BufferGeometry().setFromPoints([a, b]);
    const line = new THREE.Line(geo, this.tracerMat.clone());
    this.scene.add(line);
    this.particles.push({ obj: line, life: 0.12, max: 0.12, kind: "tracer" });
  }

  // little cartoon drops that fall and leave small splats
  blood(point, dir) {
    for (let i = 0; i < 12; i++) {
      const m = new THREE.Mesh(this.dropGeo, this.dropMat);
      m.position.copy(point);
      m.scale.setScalar(0.6 + Math.random() * 0.8);
      this.scene.add(m);
      const v = new THREE.Vector3((Math.random() - 0.5) * 2.4, 1 + Math.random() * 2.2, (Math.random() - 0.5) * 2.4).addScaledVector(dir, 1.5);
      this.particles.push({ obj: m, v, life: 1.6, max: 1.6, kind: "drop" });
    }
  }

  dust(point, color = "#d8ccc0") {
    for (let i = 0; i < 6; i++) {
      const m = new THREE.Mesh(new THREE.IcosahedronGeometry(0.08, 0), this.dustMat.clone());
      m.material.color.set(color);
      m.position.copy(point);
      this.scene.add(m);
      const v = new THREE.Vector3((Math.random() - 0.5) * 1.5, Math.random() * 1.5, (Math.random() - 0.5) * 1.5);
      this.particles.push({ obj: m, v, life: 0.6, max: 0.6, kind: "dust" });
    }
  }

  // a soft dust cloud at the feet when sprinting, plus a few sparkles
  puff(point, color = "#efe6ea", sparkle = "#ffd6e7") {
    const m = new THREE.Mesh(this.puffGeo, new THREE.MeshStandardMaterial({ color, transparent: true, opacity: 0.32, roughness: 1, flatShading: true, depthWrite: false }));
    m.position.copy(point);
    m.position.x += (Math.random() - 0.5) * 0.25;
    m.position.z += (Math.random() - 0.5) * 0.25;
    m.scale.setScalar(0.35 + Math.random() * 0.25);
    this.scene.add(m);
    const v = new THREE.Vector3((Math.random() - 0.5) * 0.6, 0.5 + Math.random() * 0.5, (Math.random() - 0.5) * 0.6);
    this.particles.push({ obj: m, v, life: 0.7, max: 0.7, kind: "puff" });
    if (Math.random() < 0.15) {
      const sp = new THREE.Mesh(this.sparkGeo, new THREE.MeshBasicMaterial({ color: sparkle, transparent: true, opacity: 1, depthWrite: false }));
      sp.position.copy(point).add(new THREE.Vector3((Math.random() - 0.5) * 0.4, 0.15, (Math.random() - 0.5) * 0.4));
      this.scene.add(sp);
      const sv = new THREE.Vector3((Math.random() - 0.5) * 1.6, 1.2 + Math.random() * 1.2, (Math.random() - 0.5) * 1.6);
      this.particles.push({ obj: sp, v: sv, life: 0.5, max: 0.5, kind: "spark" });
    }
  }

  // someone else fired: show their tracer and flash
  remoteShot(a, b) {
    this.tracer(a, b);
    this.flash.position.copy(a);
    this.flash.material.opacity = 1;
  }

  splat(pos) {
    const m = new THREE.Mesh(this.splatGeo, new THREE.MeshBasicMaterial({ color: "#a50d26", transparent: true, opacity: 0.85, depthWrite: false }));
    m.rotation.x = -Math.PI / 2;
    m.position.set(pos.x, Math.max(0.03, pos.y) + 0.01, pos.z);
    m.scale.setScalar(0.6 + Math.random() * 0.9);
    m.renderOrder = 2;
    this.scene.add(m);
    this.splats.push({ obj: m, life: 8 });
    if (this.splats.length > 60) {
      const old = this.splats.shift();
      this.scene.remove(old.obj);
      old.obj.material.dispose();
    }
  }

  // ---- the dookie emote ------------------------------------------------------
  poop(at, facing) {
    const g = new THREE.Group();
    const brown = mat("#7a4a2a", { roughness: 0.4 });
    [[0.26, 0.09], [0.2, 0.2], [0.13, 0.3]].forEach(([r, y]) => {
      const t = new THREE.Mesh(new THREE.TorusGeometry(r, 0.09, 6, 14), brown);
      t.rotation.x = Math.PI / 2;
      t.position.y = y;
      g.add(t);
    });
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.18, 8), brown);
    tip.position.y = 0.42;
    tip.rotation.z = 0.4;
    g.add(tip);
    for (const s of [-1, 1]) {
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.045, 8, 6), mat("#ffffff"));
      eye.position.set(s * 0.07, 0.24, 0.2);
      const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.022, 6, 4), mat("#1d1424"));
      pupil.position.set(0, 0, 0.035);
      eye.add(pupil);
      g.add(eye);
    }
    g.traverse((o) => (o.castShadow = true));
    // behind the player
    g.position.set(at.x - Math.sin(facing) * 0.35, at.y, at.z - Math.cos(facing) * 0.35);
    g.rotation.y = facing + Math.PI;
    g.scale.setScalar(0.01);
    this.scene.add(g);
    // stink lines and flies
    const stink = [];
    for (let i = 0; i < 3; i++) {
      const curve = new THREE.CatmullRomCurve3([0, 1, 2, 3].map((k) => new THREE.Vector3(Math.sin(k * 2 + i) * 0.08, 0.5 + k * 0.18, 0)));
      const line = new THREE.Mesh(new THREE.TubeGeometry(curve, 12, 0.012, 4), new THREE.MeshBasicMaterial({ color: "#9bd36a", transparent: true, opacity: 0.8 }));
      line.position.x = (i - 1) * 0.15;
      g.add(line);
      stink.push(line);
    }
    const flies = [];
    for (let i = 0; i < 3; i++) {
      const f = new THREE.Mesh(new THREE.SphereGeometry(0.025, 5, 3), mat("#1d1424"));
      g.add(f);
      flies.push(f);
    }
    this.poops.push({ g, t: 0, stink, flies });
    this.audio.sfx("fart");
  }

  update(dt, t) {
    this.cool = Math.max(0, this.cool - dt);
    this.flash.material.opacity = Math.max(0, this.flash.material.opacity - dt * 12);
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.kind === "drop" || p.kind === "dust") {
        p.v.y -= (p.kind === "drop" ? 12 : 3) * dt;
        p.obj.position.addScaledVector(p.v, dt);
        if (p.kind === "drop" && p.obj.position.y < 0.03 && Math.hypot(p.obj.position.x, p.obj.position.z) < ISLAND_R - 1) {
          this.splat(p.obj.position);
          p.life = 0;
        }
        if (p.kind === "dust") p.obj.material.opacity = Math.max(0, p.life / p.max);
      } else if (p.kind === "puff") {
        p.obj.position.addScaledVector(p.v, dt);
        p.v.multiplyScalar(Math.exp(-dt * 2));
        const k = 1 - p.life / p.max;
        p.obj.scale.setScalar(0.5 + k * 1.3);
        p.obj.material.opacity = 0.55 * (1 - k);
      } else if (p.kind === "spark") {
        p.v.y -= 4 * dt;
        p.obj.position.addScaledVector(p.v, dt);
        p.obj.rotation.y += dt * 8;
        p.obj.material.opacity = Math.max(0, p.life / p.max);
      } else if (p.kind === "tracer") {
        p.obj.material.opacity = Math.max(0, p.life / p.max);
      }
      if (p.life <= 0) {
        this.scene.remove(p.obj);
        if (p.kind === "puff" || p.kind === "spark") p.obj.material.dispose();
        else if (p.kind !== "drop") {
          p.obj.geometry.dispose();
          p.obj.material.dispose();
        }
        this.particles.splice(i, 1);
      }
    }
    for (let i = this.splats.length - 1; i >= 0; i--) {
      const s = this.splats[i];
      s.life -= dt;
      if (s.life < 1.5) s.obj.material.opacity = Math.max(0, s.life / 1.5) * 0.85;
      if (s.life <= 0) {
        this.scene.remove(s.obj);
        s.obj.material.dispose();
        this.splats.splice(i, 1);
      }
    }
    for (const g of this.targets) {
      const d = g.children[0]?.userData.target;
      if (d?.kind === "dummy" && d.wobble > 0) {
        d.wobble = Math.max(0, d.wobble - dt * 1.2);
        g.rotation.z = Math.sin(t * 18) * 0.25 * d.wobble;
      }
    }
    for (let i = this.poops.length - 1; i >= 0; i--) {
      const p = this.poops[i];
      p.t += dt;
      const grow = p.t < 1.2 ? 0 : Math.min(1, (p.t - 1.2) * 4);
      const shrink = p.t > 12 ? Math.max(0, 1 - (p.t - 12)) : 1;
      p.g.scale.setScalar(Math.max(0.001, grow * shrink));
      p.stink.forEach((s, k) => (s.position.y = Math.sin(t * 2 + k) * 0.05));
      p.flies.forEach((f, k) => f.position.set(Math.sin(t * 6 + k * 2) * 0.35, 0.55 + Math.sin(t * 9 + k) * 0.1, Math.cos(t * 6 + k * 2) * 0.35));
      if (p.t > 13) {
        this.scene.remove(p.g);
        this.poops.splice(i, 1);
      }
    }
  }
}
