    add(g, cyl(4.7, 4.9, 0.24, 28), std("#ffffff", { map: texture("wood", ["#e8c9a6", "#cfa47c"], 4), key: "wxDeck" }), 0, -0.1, 0, { cast: false });
    add(g, new THREE.TorusGeometry(4.8, 0.08, 4, 40), dark, 0, 0.03, 0, { rx: -Math.PI / 2, cast: false });
