// Every room's own floor and rug, painted on canvases: a rosy parquet for the diary,
// piano keys for the music room, notebook paper for notes, polaroids for photos,
// a calendar grid, an old library floor, wrapping paper, a starry bedroom carpet and
// paint-splattered studio boards. The rugs are shapes, not just rings.
import * as THREE from "three";

const S = 512;
const cache = new Map();

function canvasTex(key, paint, { repeat = 1 } = {}) {
  const k = `${key}|${repeat}`;
  if (cache.has(k)) return cache.get(k);
  const c = document.createElement("canvas");
  c.width = c.height = S;
  const g = c.getContext("2d");
  paint(g);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeat, repeat);
  t.anisotropy = 4;
  cache.set(k, t);
  return t;
}

// a tiny seeded random, so every load paints the same floor
function rng(seed) {
  let a = seed | 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const heart = (g, x, y, s) => {
  g.beginPath();
  g.moveTo(x, y + s * 0.3);
  g.bezierCurveTo(x - s * 0.7, y - s * 0.2, x - s * 0.4, y - s * 0.8, x, y - s * 0.4);
  g.bezierCurveTo(x + s * 0.4, y - s * 0.8, x + s * 0.7, y - s * 0.2, x, y + s * 0.3);
  g.fill();
};
const star = (g, x, y, r) => {
  g.beginPath();
  for (let i = 0; i < 10; i++) {
    const rr = i % 2 ? r * 0.45 : r;
    const a = (i / 10) * Math.PI * 2 - Math.PI / 2;
    i ? g.lineTo(x + Math.cos(a) * rr, y + Math.sin(a) * rr) : g.moveTo(x + Math.cos(a) * rr, y + Math.sin(a) * rr);
  }
  g.closePath();
  g.fill();
};
const grain = (g, x, y, w, h, col, n = 4) => {
  g.strokeStyle = col;
  g.lineWidth = 1.5;
  for (let i = 0; i < n; i++) {
    const yy = y + ((i + 0.5) / n) * h;
    g.beginPath();
    g.moveTo(x, yy);
    g.bezierCurveTo(x + w * 0.3, yy - 3, x + w * 0.7, yy + 3, x + w, yy);
    g.stroke();
  }
};

// ---- floors ---------------------------------------------------------------------------------
const FLOORS = {
  // rosy chevron parquet
  diary: (g) => {
    g.fillStyle = "#d9a3b6";
    g.fillRect(0, 0, S, S);
    const cw = 64;
    const ph = 32;
    const tones = ["#f6d7e1", "#f0c8d5", "#f9e1e8", "#ecc0cf"];
    const r = rng(1);
    for (let i = 0; i < S / cw; i++) {
      const x0 = i * cw;
      const up = i % 2 === 0;
      for (let y = -ph * 2; y < S + ph * 2; y += ph) {
        g.fillStyle = tones[Math.floor(r() * tones.length)];
        g.beginPath();
        g.moveTo(x0 + 1, y + (up ? ph : 0) + 1);
        g.lineTo(x0 + cw - 1, y + (up ? 0 : ph) + 1);
        g.lineTo(x0 + cw - 1, y + (up ? 0 : ph) + ph - 1);
        g.lineTo(x0 + 1, y + (up ? ph : 0) + ph - 1);
        g.closePath();
        g.fill();
      }
    }
  },
  // piano keys running across, with little floating notes
  song: (g) => {
    const kw = S / 7;
    for (let i = 0; i < 7; i++) {
      g.fillStyle = "#fbf8ff";
      g.fillRect(i * kw, 0, kw, S);
      g.fillStyle = "#c9b8f0";
      g.fillRect(i * kw + kw - 3, 0, 3, S);
    }
    g.fillStyle = "#3b2f5c";
    for (const i of [0, 1, 3, 4, 5]) g.fillRect(i * kw + kw * 0.68, 0, kw * 0.62, S * 0.6);
    g.fillStyle = "rgba(183, 155, 232, 0.55)";
    g.font = "64px serif";
    g.textAlign = "center";
    const r = rng(2);
    for (let i = 0; i < 5; i++) g.fillText(["♪", "♫", "♬"][i % 3], 60 + r() * 400, 360 + r() * 130);
  },
  // notebook paper: blue lines, a red margin, doodled hearts and stars
  note: (g) => {
    g.fillStyle = "#fffaf0";
    g.fillRect(0, 0, S, S);
    g.strokeStyle = "#9cc8ef";
    g.lineWidth = 3;
    for (let y = 32; y < S; y += 42) {
      g.beginPath();
      g.moveTo(0, y);
      g.lineTo(S, y);
      g.stroke();
    }
    g.strokeStyle = "#f08aa0";
    g.lineWidth = 4;
    g.beginPath();
    g.moveTo(84, 0);
    g.lineTo(84, S);
    g.stroke();
    const r = rng(3);
    for (let i = 0; i < 6; i++) {
      g.fillStyle = ["#ffb3cf", "#ffd166", "#b79be8"][i % 3];
      if (i % 2) heart(g, 140 + r() * 340, 60 + r() * 400, 30);
      else star(g, 140 + r() * 340, 60 + r() * 400, 18);
    }
    // binder holes down the margin
    g.fillStyle = "#e8e0d0";
    for (const y of [100, 256, 412]) {
      g.beginPath();
      g.arc(42, y, 14, 0, Math.PI * 2);
      g.fill();
    }
  },
  // polaroids laid out on pale blue boards
  photos: (g) => {
    g.fillStyle = "#dfe9f5";
    g.fillRect(0, 0, S, S);
    for (let i = 0; i < 8; i++) {
      g.fillStyle = i % 2 ? "#d4e0ef" : "#e6eef8";
      g.fillRect(0, i * 64, S, 62);
    }
    const r = rng(4);
    const skies = [["#ffd6a5", "#ff8fb1"], ["#a8d8ff", "#b79be8"], ["#b9f0c9", "#8fd3f0"], ["#ffe08a", "#ffb3cf"]];
    for (let i = 0; i < 4; i++) {
      const x = 64 + (i % 2) * 256 + r() * 30;
      const y = 64 + Math.floor(i / 2) * 256 + r() * 30;
      g.save();
      g.translate(x + 70, y + 80);
      g.rotate((r() - 0.5) * 0.4);
      g.fillStyle = "rgba(60, 80, 110, 0.18)";
      g.fillRect(-66, -74, 140, 166);
      g.fillStyle = "#ffffff";
      g.fillRect(-70, -80, 140, 166);
      const grd = g.createLinearGradient(0, -68, 0, 50);
      grd.addColorStop(0, skies[i][0]);
      grd.addColorStop(1, skies[i][1]);
      g.fillStyle = grd;
      g.fillRect(-60, -70, 120, 120);
      g.fillStyle = "rgba(255,255,255,0.8)";
      heart(g, 0, -6, 34);
      g.restore();
    }
  },
  // a big calendar: mint squares with the dates and little hearts on special days
  calendar: (g) => {
    g.fillStyle = "#e8fbef";
    g.fillRect(0, 0, S, S);
    const n = 4;
    const cs = S / n;
    g.textAlign = "left";
    g.textBaseline = "top";
    g.font = '700 30px "Quicksand", sans-serif';
    let d = 1;
    for (let j = 0; j < n; j++) {
      for (let i = 0; i < n; i++) {
        g.fillStyle = (i + j) % 2 ? "#d3f3e2" : "#f4fff8";
        g.fillRect(i * cs + 3, j * cs + 3, cs - 6, cs - 6);
        g.fillStyle = "#6cbf98";
        g.fillText(String(d), i * cs + 14, j * cs + 12);
        if (d % 5 === 3) {
          g.fillStyle = "#ff8fb1";
          heart(g, i * cs + cs * 0.6, j * cs + cs * 0.62, 34);
        }
        d++;
      }
    }
  },
  // an old library floor: basket-weave boards with faint letters pressed in
  poems: (g) => {
    const b = 64;
    const tones = ["#c9a878", "#bf9b69", "#d3b285", "#b8925f"];
    const r = rng(6);
    for (let j = 0; j < S / b; j++) {
      for (let i = 0; i < S / b; i++) {
        const vert = (i + j) % 2 === 0;
        for (let k = 0; k < 3; k++) {
          g.fillStyle = tones[Math.floor(r() * tones.length)];
          if (vert) g.fillRect(i * b + k * (b / 3), j * b, b / 3 - 2, b - 2);
          else g.fillRect(i * b, j * b + k * (b / 3), b - 2, b / 3 - 2);
        }
      }
    }
    g.fillStyle = "rgba(90, 60, 30, 0.18)";
    g.font = 'italic 46px Georgia, serif';
    for (let i = 0; i < 9; i++) g.fillText("abcdefghijklmnopqrstuvwxyz"[Math.floor(r() * 26)], r() * S, r() * S);
  },
  // wrapping paper: candy stripes, polka dots and a ribbon cross
  gift: (g) => {
    g.fillStyle = "#ffd6e5";
    g.fillRect(0, 0, S, S);
    g.fillStyle = "#ffeaf2";
    for (let i = -S; i < S * 2; i += 64) {
      g.beginPath();
      g.moveTo(i, 0);
      g.lineTo(i + 28, 0);
      g.lineTo(i + 28 - S, S);
      g.lineTo(i - S, S);
      g.fill();
    }
    g.fillStyle = "#f5a3c1";
    for (let y = 32; y < S; y += 64) for (let x = (y / 64) % 2 ? 64 : 32; x < S; x += 64) {
      g.beginPath();
      g.arc(x, y, 7, 0, Math.PI * 2);
      g.fill();
    }
    g.fillStyle = "#e2557f";
    g.fillRect(S / 2 - 22, 0, 44, S);
    g.fillRect(0, S / 2 - 22, S, 44);
    g.fillStyle = "#ffd166";
    g.fillRect(S / 2 - 4, 0, 8, S);
    g.fillRect(0, S / 2 - 4, S, 8);
  },
  // a cosy bedroom carpet: soft lilac with stars and little moons
  wardrobe: (g) => {
    g.fillStyle = "#e6dbf7";
    g.fillRect(0, 0, S, S);
    const r = rng(8);
    for (let i = 0; i < 2600; i++) {
      g.fillStyle = `rgba(${r() < 0.5 ? "255,255,255" : "190,170,230"},0.25)`;
      g.fillRect(r() * S, r() * S, 2, 4);
    }
    for (let i = 0; i < 9; i++) {
      const x = 40 + r() * 430;
      const y = 40 + r() * 430;
      if (i % 3 === 0) {
        g.fillStyle = "#fff3c4";
        g.beginPath();
        g.arc(x, y, 20, 0, Math.PI * 2);
        g.fill();
        g.fillStyle = "#e6dbf7";
        g.beginPath();
        g.arc(x + 9, y - 6, 18, 0, Math.PI * 2);
        g.fill();
      } else {
        g.fillStyle = i % 2 ? "#fff7f2" : "#ffd6e7";
        star(g, x, y, 14);
      }
    }
  },
  // studio boards splattered with paint
  art: (g) => {
    const tones = ["#f7e4cf", "#f1d8bd", "#fbebd9", "#ecd0b2"];
    for (let i = 0; i < 6; i++) {
      g.fillStyle = tones[i % tones.length];
      g.fillRect(0, i * (S / 6), S, S / 6 - 3);
      grain(g, 0, i * (S / 6), S, S / 6, "rgba(160, 110, 70, 0.15)", 4);
    }
    const r = rng(9);
    const paints = ["#ff6f91", "#ffd166", "#6fb6e8", "#8fd3b6", "#b79be8", "#f6a96b"];
    for (let i = 0; i < 14; i++) {
      const x = r() * S;
      const y = r() * S;
      const col = paints[i % paints.length];
      g.fillStyle = col;
      g.beginPath();
      g.arc(x, y, 8 + r() * 18, 0, Math.PI * 2);
      g.fill();
      for (let k = 0; k < 6; k++) {
        g.beginPath();
        g.arc(x + (r() - 0.5) * 70, y + (r() - 0.5) * 70, 2 + r() * 5, 0, Math.PI * 2);
        g.fill();
      }
    }
  },
};

export function floorTexture(id, repeat = 2) {
  const paint = FLOORS[id];
  return paint ? canvasTex(`floor-${id}`, paint, { repeat }) : null;
}

// ---- rugs (round canvases with see-through outsides, so the rug has a real shape) -----------
const RUGS = {
  // a big flower
  diary: (g) => {
    g.fillStyle = "#f7c6d9";
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      g.beginPath();
      g.ellipse(256 + Math.cos(a) * 140, 256 + Math.sin(a) * 140, 110, 80, a, 0, Math.PI * 2);
      g.fill();
    }
    g.fillStyle = "#d9708f";
    g.beginPath();
    g.arc(256, 256, 110, 0, Math.PI * 2);
    g.fill();
    g.fillStyle = "#ffe08a";
    g.beginPath();
    g.arc(256, 256, 60, 0, Math.PI * 2);
    g.fill();
  },
  // a vinyl record
  song: (g) => {
    g.fillStyle = "#2f2648";
    g.beginPath();
    g.arc(256, 256, 250, 0, Math.PI * 2);
    g.fill();
    g.strokeStyle = "rgba(255,255,255,0.08)";
    g.lineWidth = 2;
    for (let r = 120; r < 245; r += 9) {
      g.beginPath();
      g.arc(256, 256, r, 0, Math.PI * 2);
      g.stroke();
    }
    g.fillStyle = "#b79be8";
    g.beginPath();
    g.arc(256, 256, 95, 0, Math.PI * 2);
    g.fill();
    g.fillStyle = "#fff7f2";
    g.font = '700 34px "Fredoka", sans-serif';
    g.textAlign = "center";
    g.fillText("♫ us ♫", 256, 250);
    g.beginPath();
    g.arc(256, 280, 10, 0, Math.PI * 2);
    g.fill();
  },
  // a heart
  note: (g) => {
    g.fillStyle = "#ffd166";
    heart(g, 256, 300, 430);
    g.fillStyle = "#fff3c4";
    heart(g, 256, 290, 300);
  },
  // a camera aperture
  photos: (g) => {
    g.fillStyle = "#5b8fd0";
    g.beginPath();
    g.arc(256, 256, 250, 0, Math.PI * 2);
    g.fill();
    for (let i = 0; i < 6; i++) {
      g.fillStyle = i % 2 ? "#9cc0ea" : "#c6dcf5";
      g.beginPath();
      const a0 = (i / 6) * Math.PI * 2;
      g.moveTo(256, 256);
      g.arc(256, 256, 220, a0, a0 + Math.PI / 3);
      g.closePath();
      g.fill();
    }
    g.fillStyle = "#2b3a55";
    g.beginPath();
    g.arc(256, 256, 70, 0, Math.PI * 2);
    g.fill();
    g.fillStyle = "rgba(255,255,255,0.7)";
    g.beginPath();
    g.arc(232, 232, 18, 0, Math.PI * 2);
    g.fill();
  },
  // a clock face
  calendar: (g) => {
    g.fillStyle = "#4e9a6a";
    g.beginPath();
    g.arc(256, 256, 250, 0, Math.PI * 2);
    g.fill();
    g.fillStyle = "#f3fff6";
    g.beginPath();
    g.arc(256, 256, 225, 0, Math.PI * 2);
    g.fill();
    g.fillStyle = "#4e9a6a";
    g.font = '700 38px "Quicksand", sans-serif';
    g.textAlign = "center";
    g.textBaseline = "middle";
    for (let h = 1; h <= 12; h++) {
      const a = (h / 12) * Math.PI * 2 - Math.PI / 2;
      g.fillText(String(h), 256 + Math.cos(a) * 185, 256 + Math.sin(a) * 185);
    }
    g.strokeStyle = "#ff8fb1";
    g.lineWidth = 14;
    g.lineCap = "round";
    g.beginPath();
    g.moveTo(256, 256);
    g.lineTo(256, 130);
    g.moveTo(256, 256);
    g.lineTo(340, 256);
    g.stroke();
  },
  // an open book
  poems: (g) => {
    for (const s of [-1, 1]) {
      g.fillStyle = "#8a7fd0";
      g.beginPath();
      g.moveTo(256, 120);
      g.quadraticCurveTo(256 + s * 120, 70, 256 + s * 240, 110);
      g.lineTo(256 + s * 240, 410);
      g.quadraticCurveTo(256 + s * 120, 370, 256, 420);
      g.closePath();
      g.fill();
      g.fillStyle = "#fbf3e2";
      g.beginPath();
      g.moveTo(256, 134);
      g.quadraticCurveTo(256 + s * 115, 88, 256 + s * 222, 124);
      g.lineTo(256 + s * 222, 392);
      g.quadraticCurveTo(256 + s * 115, 356, 256, 404);
      g.closePath();
      g.fill();
      g.strokeStyle = "rgba(138,127,208,0.45)";
      g.lineWidth = 4;
      for (let k = 0; k < 6; k++) {
        g.beginPath();
        g.moveTo(256 + s * 30, 170 + k * 36);
        g.lineTo(256 + s * 190, 160 + k * 36);
        g.stroke();
      }
    }
  },
  // a big bow
  gift: (g) => {
    g.fillStyle = "#e2557f";
    for (const s of [-1, 1]) {
      g.beginPath();
      g.moveTo(256, 256);
      g.bezierCurveTo(256 + s * 120, 90, 256 + s * 260, 140, 256 + s * 230, 256);
      g.bezierCurveTo(256 + s * 260, 370, 256 + s * 120, 420, 256, 256);
      g.fill();
      g.beginPath();
      g.moveTo(256 + s * 20, 270);
      g.lineTo(256 + s * 120, 470);
      g.lineTo(256 + s * 60, 440);
      g.lineTo(256 + s * 10, 290);
      g.fill();
    }
    g.fillStyle = "#ff8fb1";
    g.beginPath();
    g.arc(256, 256, 48, 0, Math.PI * 2);
    g.fill();
  },
  // a crescent moon
  wardrobe: (g) => {
    g.fillStyle = "#fff3c4";
    g.beginPath();
    g.arc(256, 256, 240, 0, Math.PI * 2);
    g.fill();
    g.globalCompositeOperation = "destination-out";
    g.beginPath();
    g.arc(340, 200, 200, 0, Math.PI * 2);
    g.fill();
    g.globalCompositeOperation = "source-over";
    g.fillStyle = "#ffd6e7";
    star(g, 360, 330, 34);
    star(g, 420, 230, 20);
  },
  // a painter's palette
  art: (g) => {
    g.fillStyle = "#e8c9a6";
    g.beginPath();
    g.ellipse(256, 256, 245, 200, 0, 0, Math.PI * 2);
    g.fill();
    g.globalCompositeOperation = "destination-out";
    g.beginPath();
    g.arc(150, 330, 44, 0, Math.PI * 2);
    g.fill();
    g.globalCompositeOperation = "source-over";
    ["#ff6f91", "#ffd166", "#6fb6e8", "#8fd3b6", "#b79be8"].forEach((c, i) => {
      const a = -2.6 + i * 0.75;
      g.fillStyle = c;
      g.beginPath();
      g.arc(256 + Math.cos(a) * 160, 256 + Math.sin(a) * 120, 38, 0, Math.PI * 2);
      g.fill();
    });
  },
};

// a flat shaped rug for the room (null if the room has none)
export function makeRug(id, radius) {
  const paint = RUGS[id];
  if (!paint) return null;
  const tex = canvasTex(`rug-${id}`, paint);
  tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;
  const m = new THREE.Mesh(new THREE.CircleGeometry(radius, 48), new THREE.MeshStandardMaterial({ map: tex, transparent: true, alphaTest: 0.5, roughness: 0.95 }));
  m.rotation.x = -Math.PI / 2;
  m.receiveShadow = true;
  return m;
}
