// a cute little parachute, for jumping out of the balloon: a puffy pastel canopy with
// scalloped edges, pompoms on every point, a heart on top and ribbons streaming off it. It
// hangs over whoever wears it (island.js for you, net.js for your person), popping open and
// swaying as you drift down, and folding away behind you when you land
import * as THREE from "three";

const mats = {};
const mat = (c, { key = "", ...extra } = {}) =>
  (mats[c + key] ||= new THREE.MeshStandardMaterial({ color: c, roughness: 0.7, side: THREE.DoubleSide, flatShading: true, ...extra }));
const UP = new THREE.Vector3(0, 1, 0);

let heart = null;
const heartGeo = () => {
  if (heart) return heart;
  const s = new THREE.Shape();
  s.moveTo(0, -0.5);
  s.bezierCurveTo(-0.9, 0.1, -0.4, 0.8, 0, 0.35);
  s.bezierCurveTo(0.4, 0.8, 0.9, 0.1, 0, -0.5);
  heart = new THREE.ExtrudeGeometry(s, { depth: 0.18, bevelEnabled: true, bevelSize: 0.05, bevelThickness: 0.05, bevelSegments: 2 });
  heart.center();
  return heart;
};

export function makeChute(height = 1.6) {
  const root = new THREE.Group();
  const sway = new THREE.Group(); // swings gently from the harness
  root.add(sway);
  sway.position.y = height * 0.78;
  const R = 1.45, TH = Math.PI * 0.4, N = 8;
  const cy = 2.5 - R * Math.cos(TH); // the dome's rim sits this high over the harness
  const rimY = cy + R * Math.cos(TH), rimR = R * Math.sin(TH);
  const cols = ["#ffb3cf", "#fff4f8", "#c9b6f7", "#fff4f8", "#a8e6cf", "#fff4f8", "#ffd8a8", "#fff4f8"];
  // puffy panels: each one bulges out a little between its seams
  for (let k = 0; k < N; k++) {
    const geo = new THREE.SphereGeometry(R, 4, 8, (k / N) * Math.PI * 2, (Math.PI * 2) / N, 0, TH);
    const p = geo.attributes.position;
    const mid = ((k + 0.5) / N) * Math.PI * 2;
    for (let i = 0; i < p.count; i++) {
      const x = p.getX(i), y = p.getY(i), z = p.getZ(i);
      const a = Math.atan2(x, z);
      const d = Math.cos(Math.atan2(Math.sin(a - mid), Math.cos(a - mid)) * (N / 2)); // 1 mid-panel, 0 at the seams
      const f = 1 + 0.07 * Math.max(0, d) * Math.sin(Math.acos(Math.max(-1, Math.min(1, y / R))));
      p.setXYZ(i, x * f, y, z * f);
    }
    geo.computeVertexNormals();
    const seg = new THREE.Mesh(geo, mat(cols[k]));
    seg.position.y = cy;
    seg.castShadow = true;
    sway.add(seg);
    // a scallop hanging off each panel's rim, and a pompom on every point between them
    const sc = new THREE.Mesh(new THREE.CircleGeometry(0.26, 10, 0, Math.PI), mat(cols[k]));
    sc.position.set(Math.sin(mid) * rimR * 1.03, rimY + 0.01, Math.cos(mid) * rimR * 1.03);
    sc.rotation.set(Math.PI, mid, 0);
    sway.add(sc);
    const seam = (k / N) * Math.PI * 2;
    const pom = new THREE.Mesh(new THREE.IcosahedronGeometry(0.075, 1), mat("#ffffff"));
    pom.position.set(Math.sin(seam) * rimR, rimY - 0.04, Math.cos(seam) * rimR);
    sway.add(pom);
  }
  // a heart on top, standing up, and a little bow under it
  const h = new THREE.Mesh(heartGeo(), mat("#ff5a8a", { emissive: "#ff5a8a", emissiveIntensity: 0.15, key: "glow" }));
  h.scale.setScalar(0.42);
  h.position.y = cy + R + 0.16;
  sway.add(h);
  for (const s of [-1, 1]) {
    const loop = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.2, 6), mat("#ff8fb1"));
    loop.rotation.z = (s * Math.PI) / 2;
    loop.position.set(s * 0.1, cy + R - 0.02, 0);
    sway.add(loop);
  }
  // ribbons streaming off two of the points
  const ribbons = [];
  for (const k of [1, 5]) {
    const seam = (k / N) * Math.PI * 2;
    const rb = new THREE.Mesh(new THREE.PlaneGeometry(0.07, 0.7, 1, 4).translate(0, -0.35, 0), mat(k === 1 ? "#ff8fb1" : "#b79be8"));
    rb.position.set(Math.sin(seam) * rimR, rimY - 0.05, Math.cos(seam) * rimR);
    rb.rotation.y = seam;
    sway.add(rb);
    ribbons.push(rb);
  }
  // the cords, from the points down to the harness
  const cord = mat("#fff4f8");
  for (let k = 0; k < N; k++) {
    const a = (k / N) * Math.PI * 2;
    const p = new THREE.Vector3(Math.sin(a) * rimR, rimY, Math.cos(a) * rimR);
    const q = new THREE.Vector3(Math.sin(a) * 0.14, 0, Math.cos(a) * 0.14);
    const d = p.clone().sub(q);
    const m = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, d.length(), 3), cord);
    m.position.copy(p).add(q).multiplyScalar(0.5);
    m.quaternion.setFromUnitVectors(UP, d.normalize());
    sway.add(m);
  }
  root.visible = false;
  let open = 0;
  let fold = 0;
  let wasOn = false;
  let t = Math.random() * 10;
  return {
    root,
    // call every frame: on (wearing it) or not
    update(dt, on) {
      t += dt;
      if (on && !wasOn) fold = 0;
      wasOn = on;
      open = on ? Math.min(1, open + dt * 3.2) : Math.max(0, open - dt * 1.3);
      root.visible = open > 0.01;
      if (!root.visible) return;
      // pops open with a little overshoot, like a bubble
      const pop = on ? 1 + Math.sin(Math.min(1, open) * Math.PI) * 0.12 - (1 - open) ** 2 : open;
      // landed: the canopy sinks and tips over behind you as it folds away
      if (!on) fold = Math.min(1, fold + dt * 1.6);
      const f = fold * fold * (3 - 2 * fold);
      const breathe = 1 + Math.sin(t * 2.4) * 0.025 * (1 - f);
      sway.scale.set(pop * breathe, (0.4 + 0.6 * pop) * (1 - 0.6 * f), pop * breathe);
      sway.rotation.z = Math.sin(t * 1.3) * 0.07 * (1 - f);
      sway.rotation.x = Math.sin(t * 0.9 + 1) * 0.05 * (1 - f) - f * 1.1;
      ribbons.forEach((rb, i) => (rb.rotation.x = 0.35 + Math.sin(t * 5 + i * 2) * 0.25));
    },
  };
}
