// Our willow: a special tree in the middle of the island that grows a little
// every day we've been together, with a heart sign for our anniversaries.
// Both of us can hang decorations on it (saved here, shared live).
import * as THREE from "three";
import { std, glow } from "./world.js";
import { texture, textCanvas, FONT } from "./textures.js";
import { getShared, setShared, onShared } from "./shared.js";

const STORE = "tdd3d.tree";
// 1cm for every day together (a sapling to start, and a sensible top)
const treeHeight = (days) => Math.min(25, Math.max(0.8, days * 0.01));
const DAYS = "tdd3d.days";

export const DECOR = [
  { id: "lights", emoji: "✨", label: "fairy lights" },
  { id: "lantern", emoji: "🏮", label: "lantern" },
  { id: "heart", emoji: "💗", label: "heart" },
  { id: "star", emoji: "⭐", label: "star" },
  { id: "ribbon", emoji: "🎀", label: "ribbon" },
  { id: "flower", emoji: "🌸", label: "blossoms" },
  { id: "note", emoji: "💌", label: "love note" },
  { id: "bird", emoji: "🐦", label: "little bird" },
];
export const DECOR_COLORS = ["#ff8fb1", "#e2557f", "#ffd166", "#fff7f2", "#b79be8", "#8fd3f0", "#8fd3b6", "#ff9a3b"];

const mat = (color, extra = {}) => new THREE.MeshStandardMaterial({ color, flatShading: true, roughness: 0.8, ...extra });
const glowMat = (color) => new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 1.4, flatShading: true });

function heartShape(s = 1) {
  const p = new THREE.Shape();
  p.moveTo(0, -0.9 * s);
  p.bezierCurveTo(0.2 * s, -0.6 * s, 1.0 * s, -0.25 * s, 1.0 * s, 0.25 * s);
  p.bezierCurveTo(1.0 * s, 0.75 * s, 0.4 * s, 0.95 * s, 0, 0.5 * s);
  p.bezierCurveTo(-0.4 * s, 0.95 * s, -1.0 * s, 0.75 * s, -1.0 * s, 0.25 * s);
  p.bezierCurveTo(-1.0 * s, -0.25 * s, -0.2 * s, -0.6 * s, 0, -0.9 * s);
  return p;
}

// the willow stands in the middle of the island, drawn this much bigger than its
// real height (the sign still counts the real centimetres)
const WILLOW_BIG = 1.7;
const SIGN_Z = 7.4; // the heart sign, in front of the planter

export class Willow {
  constructor({ scene, world, pos }) {
    this.scene = scene;
    this.world = world;
    this.pos = pos.clone();
    this.big = WILLOW_BIG;
    this.signZ = SIGN_Z;
    // the decorations are kept in the database (shared.js), for both of us
    const read = (v) => {
      try {
        const list = JSON.parse(v || "[]");
        return Array.isArray(list) ? list : [];
      } catch {
        return [];
      }
    };
    this.items = read(getShared(STORE));
    onShared((key, value) => {
      if (key !== STORE) return;
      this.items = read(value);
      this.renderDecor();
    });
    let cached = 0;
    try {
      cached = Number(localStorage.getItem(DAYS)) || 0;
    } catch {}
    this.days = -1;
    this.root = new THREE.Group();
    this.root.position.copy(this.pos);
    this.root.scale.setScalar(WILLOW_BIG);
    scene.add(this.root);
    this.buildBase();
    this.tree = new THREE.Group();
    this.root.add(this.tree);
    this.buildTree();
    this.decorGroup = new THREE.Group();
    this.tree.add(this.decorGroup);
    this.buildSign();
    this.circle = { x: this.pos.x, z: this.pos.z, r: 0.6 * WILLOW_BIG };
    world.circles.push(this.circle);
    this.setDays(cached || 365);
    this.renderDecor();
  }

  // a round grassy planter with a ring of stones and lanterns
  buildBase() {
    const g = this.root;
    const stone = std("#ffffff", { map: texture("cobble", ["#efe4ec", "#c4b2bc"], 2) });
    const ring = new THREE.Mesh(new THREE.TorusGeometry(3.3, 0.28, 5, 28), stone);
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.12;
    ring.receiveShadow = true;
    g.add(ring);
    const moss = new THREE.Mesh(new THREE.CylinderGeometry(3.2, 3.3, 0.16, 28), mat("#9fd18a"));
    moss.position.y = 0.06;
    moss.receiveShadow = true;
    g.add(moss);
    // little flowers in the moss
    const petal = new THREE.IcosahedronGeometry(0.07, 0);
    const cols = ["#ff8fb1", "#fff7f2", "#ffd166", "#b79be8"];
    for (let i = 0; i < 46; i++) {
      const a = i * 2.39996;
      const r = 1.1 + ((i * 37) % 19) / 10;
      const f = new THREE.Mesh(petal, mat(cols[i % 4]));
      f.position.set(Math.sin(a) * r, 0.17, Math.cos(a) * r);
      g.add(f);
    }
    // lanterns at four corners
    const wood = std("#ffffff", { map: texture("wood", ["#c9a27e", "#a07a58"]) });
    this.lanterns = [];
    for (let k = 0; k < 4; k++) {
      const a = Math.PI / 4 + (k * Math.PI) / 2;
      const post = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.08, 1.4, 6), wood);
      post.position.set(Math.sin(a) * 3.9, 0.7, Math.cos(a) * 3.9);
      post.castShadow = true;
      g.add(post);
      const lamp = new THREE.Mesh(new THREE.IcosahedronGeometry(0.17, 0), glow.warm);
      lamp.position.set(Math.sin(a) * 3.9, 1.52, Math.cos(a) * 3.9);
      g.add(lamp);
      this.world.circles.push({ x: this.pos.x + post.position.x * WILLOW_BIG, z: this.pos.z + post.position.z * WILLOW_BIG, r: 0.15 * WILLOW_BIG });
    }
  }

  // trunk, arching branches and hanging strands (built at a 6m size, then scaled)
  buildTree() {
    const t = this.tree;
    const bark = std("#ffffff", { map: texture("wood", ["#8a6248", "#5e4030"], 1) });
    this.barkMat = bark;
    const tube = (pts, r0, r1, seg = 12, radial = 8) => {
      const curve = new THREE.CatmullRomCurve3(pts);
      const geo = new THREE.TubeGeometry(curve, seg, 1, radial, false);
      const pos = geo.attributes.position;
      const v = new THREE.Vector3();
      // taper from r0 to r1 along the curve
      for (let i = 0; i <= seg; i++) {
        const c = curve.getPointAt(i / seg);
        const r = r0 + (r1 - r0) * (i / seg);
        for (let j = 0; j <= radial; j++) {
          const k = i * (radial + 1) + j;
          v.fromBufferAttribute(pos, k).sub(c).multiplyScalar(r).add(c);
          pos.setXYZ(k, v.x, v.y, v.z);
        }
      }
      geo.computeVertexNormals();
      const m = new THREE.Mesh(geo, bark);
      m.castShadow = true;
      m.receiveShadow = true;
      t.add(m);
      return curve;
    };
    // the trunk leans a little and twists up
    tube([new THREE.Vector3(0, -0.1, 0), new THREE.Vector3(0.15, 1.0, 0.05), new THREE.Vector3(-0.05, 2.0, -0.1), new THREE.Vector3(0.1, 2.7, 0)], 0.55, 0.32, 10, 10);
    // roots that flare into the moss
    for (let k = 0; k < 6; k++) {
      const a = (k / 6) * Math.PI * 2 + 0.4;
      const d = new THREE.Vector3(Math.sin(a), 0, Math.cos(a));
      tube([d.clone().multiplyScalar(0.2).setY(0.5), d.clone().multiplyScalar(0.55).setY(0.18), d.clone().multiplyScalar(1.0).setY(0.02)], 0.22, 0.06, 6, 6);
    }
    // big limbs that rise and arch out under the canopy
    this.anchors = [];
    const limbs = 5;
    for (let b = 0; b < limbs; b++) {
      const a = (b / limbs) * Math.PI * 2 + 0.3;
      const d = new THREE.Vector3(Math.sin(a), 0, Math.cos(a));
      const curve = tube([
        new THREE.Vector3(0.05, 2.5, 0),
        d.clone().multiplyScalar(0.7).setY(3.5),
        d.clone().multiplyScalar(1.6).setY(4.3),
        d.clone().multiplyScalar(2.5).setY(4.6),
      ], 0.26, 0.07, 10, 7);
      void curve;
    }

    // the canopy: an umbrella of soft leaf clumps
    const clumpGeo = new THREE.IcosahedronGeometry(1, 1);
    const crownMat = new THREE.MeshStandardMaterial({ color: "#ffffff", roughness: 0.9, flatShading: true });
    this.crownMat = crownMat;
    const greens = ["#9fd47e", "#b4e08f", "#8cc76a", "#c3e8a0", "#a8d886"].map((c) => new THREE.Color(c));
    const clumps = [];
    const R = 3.3;
    const cy = 2.0;
    for (let ring = 0; ring < 4; ring++) {
      const phi = 0.12 + ring * 0.24; // from the top down to the rim
      const n = ring === 0 ? 4 : 7 + ring * 4;
      for (let i = 0; i < n; i++) {
        const th = (i / n) * Math.PI * 2 + ring * 0.6;
        const r = R * Math.sin(phi) * 1.18;
        const y = cy + R * Math.cos(phi) * 0.95;
        const s = 0.85 - ring * 0.07 + ((i * 7 + ring) % 5) * 0.05;
        clumps.push([Math.sin(th) * r, y, Math.cos(th) * r, s]);
      }
    }
    const crown = new THREE.InstancedMesh(clumpGeo, crownMat, clumps.length);
    const m4 = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    clumps.forEach(([x, y, z, s], i) => {
      q.setFromEuler(new THREE.Euler(i * 0.7, i * 1.3, 0));
      m4.compose(new THREE.Vector3(x, y, z), q, new THREE.Vector3(s * 1.15, s * 0.58, s * 1.15));
      crown.setMatrixAt(i, m4);
      crown.setColorAt(i, greens[i % greens.length]);
    });
    crown.castShadow = true;
    crown.receiveShadow = true;
    t.add(crown);

    // the curtains: long strands of little leaves hanging all round
    const tex = willowStrandTexture();
    this.strandMat = new THREE.MeshStandardMaterial({ map: tex, alphaTest: 0.45, side: THREE.DoubleSide, roughness: 0.9, emissive: "#2c4a1c", emissiveIntensity: 0.35 });
    const plane = new THREE.PlaneGeometry(1.0, 1).translate(0, -0.5, 0).toNonIndexed();
    const cross = plane.clone().rotateY(Math.PI / 2);
    const strandGeo = mergeSimple([plane, cross], true);
    this.strandsAt = [];
    const rings = [
      // radius, how many, top, length, extra length
      [3.25, 46, 3.95, 3.0, 1.0, 0.17],
      [2.6, 34, 4.4, 3.2, 1.0, 0.1],
      [1.8, 20, 4.8, 2.4, 0.8, 0.05],
    ];
    rings.forEach(([rad, n, top, len, spread, tilt], ri) => {
      for (let i = 0; i < n; i++) {
        const a = (i / n) * Math.PI * 2 + ri * 0.37 + ((i * 13) % 7) * 0.02;
        const r = rad + (((i * 31) % 9) / 9 - 0.5) * 0.3;
        const p = new THREE.Vector3(Math.sin(a) * r, top + (((i * 7) % 5) / 5 - 0.5) * 0.2, Math.cos(a) * r);
        const l = len + (((i * 17 + ri) % 11) / 11) * spread;
        this.strandsAt.push({ p, len: l, a, tilt, spin: (i * 0.9) % Math.PI });
      }
    });
    this.strands = new THREE.InstancedMesh(strandGeo, this.strandMat, this.strandsAt.length);
    const tint = ["#b8e898", "#a6dc86", "#c8efaa", "#9cd57c"].map((c) => new THREE.Color(c));
    this.strandsAt.forEach((s, i) => this.strands.setColorAt(i, tint[i % tint.length]));
    t.add(this.strands);
    // decorations hang on the outside of the curtains, where you can see
    // them: three bands all the way round, staggered
    this.anchorAngles = [];
    for (let band = 0; band < 3; band++) {
      const drop = 0.9 + band * 0.75; // how far down the curtain
      const n = 16;
      for (let k = 0; k < n; k++) {
        const a = ((k + (band % 2) * 0.5) / n) * Math.PI * 2;
        const r = 3.25 + Math.sin(0.17) * drop + 0.38;
        this.anchors.push(new THREE.Vector3(Math.sin(a) * r, 3.95 - drop, Math.cos(a) * r));
        this.anchorAngles.push(a);
      }
    }
    // fireflies drifting in the curtains
    this.flies = [];
    for (let k = 0; k < 14; k++) {
      const f = new THREE.Mesh(new THREE.IcosahedronGeometry(0.045, 0), glow.warm);
      f.userData.seed = k * 1.7;
      t.add(f);
      this.flies.push(f);
    }
    this.swayM = new THREE.Matrix4();
    this.swayQ = new THREE.Quaternion();
    this.swayE = new THREE.Euler(0, 0, 0, "XZY");
    this.swayS = new THREE.Vector3();
    this.updateStrands(0);
  }

  updateStrands(t) {
    this.strandsAt.forEach((s, i) => {
      // a breeze that rolls round the tree, in gentle gusts (stronger on the outer curtains)
      const gust = 0.75 + Math.sin(t * 0.23) * 0.25 + Math.max(0, Math.sin(t * 0.61 + 1)) * 0.3;
      const w = (Math.sin(t * 1.1 + i * 0.37) * 0.05 + Math.sin(t * 0.8 + s.a * 1.5) * 0.1 + Math.sin(t * 2.3 + i) * 0.015) * gust * (0.6 + s.tilt * 3);
      this.swayE.set(Math.cos(s.a) * (w - s.tilt), s.spin, Math.sin(s.a) * (s.tilt - w));
      this.swayQ.setFromEuler(this.swayE);
      this.swayS.set(1, s.len, 1);
      this.swayM.compose(s.p, this.swayQ, this.swayS);
      this.strands.setMatrixAt(i, this.swayM);
    });
    this.strands.instanceMatrix.needsUpdate = true;
    for (const f of this.flies || []) {
      const k = f.userData.seed;
      const a = t * 0.25 + k;
      const r = 2.2 + Math.sin(t * 0.4 + k) * 1.2;
      f.position.set(Math.sin(a) * r, 1.2 + Math.sin(t * 0.7 + k * 2) * 0.8 + (k % 3) * 0.5, Math.cos(a) * r);
    }
  }

  // the heart sign: how many anniversaries, and how many days
  buildSign() {
    const g = new THREE.Group();
    // keeps its own size while the tree is drawn bigger
    g.position.set(0, 0, SIGN_Z / WILLOW_BIG);
    g.scale.setScalar(1 / WILLOW_BIG);
    this.root.add(g);
    // a twisted, ribbon-wrapped post with a little flower bed round its foot
    const wood = std("#ffffff", { map: texture("wood", ["#c9a27e", "#a07a58"]) });
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.08, 1.45, 8), wood);
    post.position.y = 0.72;
    post.castShadow = true;
    g.add(post);
    const ribbon = mat("#fff3f8", { roughness: 0.5 });
    for (let k = 0; k < 6; k++) {
      const r = new THREE.Mesh(new THREE.TorusGeometry(0.072, 0.014, 4, 12), ribbon);
      r.position.y = 0.25 + k * 0.2;
      r.rotation.set(Math.PI / 2 + 0.35, 0, 0);
      g.add(r);
    }
    const petals = ["#ff8fb1", "#ffd166", "#fff7f2", "#c7b0f5"];
    for (let k = 0; k < 9; k++) {
      const a = (k / 9) * Math.PI * 2;
      const f = new THREE.Mesh(new THREE.IcosahedronGeometry(0.06, 0), mat(petals[k % 4]));
      f.position.set(Math.sin(a) * 0.28, 0.07, Math.cos(a) * 0.28);
      g.add(f);
      const lf = new THREE.Mesh(new THREE.IcosahedronGeometry(0.07, 0), mat("#7fbf6a"));
      lf.scale.set(1, 0.4, 1.4);
      lf.position.set(Math.sin(a + 0.35) * 0.3, 0.03, Math.cos(a + 0.35) * 0.3);
      lf.rotation.y = a;
      g.add(lf);
    }
    // the heart: a cream rim round a painted face, front and back. It doesn't take the
    // willow's shadow, so it always reads bright
    // the heart, its painted faces and the bow sway together as one
    const swing = new THREE.Group();
    g.add(swing);
    this.signSwing = swing;
    const heartGeo = new THREE.ExtrudeGeometry(heartShape(0.62), { depth: 0.1, bevelEnabled: true, bevelThickness: 0.035, bevelSize: 0.05, bevelSegments: 3, curveSegments: 24 });
    heartGeo.translate(0, 0, -0.05);
    const heart = new THREE.Mesh(heartGeo, mat("#fff1f6", { roughness: 0.45 }));
    heart.position.y = 1.85;
    heart.castShadow = true;
    heart.receiveShadow = false;
    swing.add(heart);
    const face = textCanvas(512, 512);
    this.signFace = face;
    // drawn in the opaque pass (cut out, not blended) so the willow's leaves can't
    // sort in front of it and hide the words
    const faceMat = new THREE.MeshBasicMaterial({ map: face.tex, alphaTest: 0.5, toneMapped: false });
    const plane = new THREE.Mesh(new THREE.PlaneGeometry(1.24, 1.24), faceMat);
    plane.position.set(0, 1.9, 0.092);
    swing.add(plane);
    const back = plane.clone();
    back.rotation.y = Math.PI;
    back.position.z = -0.092;
    swing.add(back);
    // a bow on top, between the two curves
    const bowMat = mat("#ffd166", { roughness: 0.4 });
    for (const sx of [-1, 1]) {
      const loop = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.2, 4), bowMat);
      loop.rotation.z = (sx * Math.PI) / 2;
      loop.position.set(sx * 0.1, 2.18, 0.02);
      swing.add(loop);
      const tail = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.16, 0.02), bowMat);
      tail.position.set(sx * 0.05, 2.08, 0.04);
      tail.rotation.z = sx * 0.4;
      swing.add(tail);
    }
    const knot = new THREE.Mesh(new THREE.IcosahedronGeometry(0.045, 0), bowMat);
    knot.position.set(0, 2.18, 0.04);
    swing.add(knot);
    this.signHeart = heart;
    this.signGroup = g;
    this.world.circles.push({ x: this.pos.x, z: this.pos.z + SIGN_Z, r: 0.25 });
  }

  drawSign() {
    const { ctx, tex } = this.signFace;
    const days = Math.max(0, this.days);
    const years = Math.floor(days / 365.25);
    const cm = Math.round(treeHeight(days) * 100);
    ctx.clearRect(0, 0, 512, 512);
    // the same heart as the sign's shape, in canvas pixels (256 px a unit, centred,
    // 20 px lower because the face sits a touch above the heart's middle)
    const heart = (k) => {
      const X = (u) => 256 + u * 256 * k;
      const Y = (v) => 276.6 - 256 * (v * k + (1 - k) * 0.0);
      ctx.beginPath();
      ctx.moveTo(X(0), Y(-0.9));
      ctx.bezierCurveTo(X(0.2), Y(-0.6), X(1.0), Y(-0.25), X(1.0), Y(0.25));
      ctx.bezierCurveTo(X(1.0), Y(0.75), X(0.4), Y(0.95), X(0), Y(0.5));
      ctx.bezierCurveTo(X(-0.4), Y(0.95), X(-1.0), Y(0.75), X(-1.0), Y(0.25));
      ctx.bezierCurveTo(X(-1.0), Y(-0.25), X(-0.2), Y(-0.6), X(0), Y(-0.9));
      ctx.closePath();
    };
    const grd = ctx.createRadialGradient(200, 170, 20, 256, 260, 300);
    grd.addColorStop(0, "#ff9fc0");
    grd.addColorStop(0.55, "#ec5f8c");
    grd.addColorStop(1, "#c93f6e");
    heart(0.985);
    ctx.fillStyle = grd;
    ctx.fill();
    // a shine on the left curve
    ctx.save();
    heart(0.985);
    ctx.clip();
    ctx.fillStyle = "rgba(255,255,255,0.18)";
    ctx.beginPath();
    ctx.ellipse(150, 150, 70, 34, -0.6, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    // stitching round the inside
    heart(0.86);
    ctx.setLineDash([10, 9]);
    ctx.lineWidth = 4;
    ctx.strokeStyle = "rgba(255,240,246,0.85)";
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.shadowColor = "rgba(120,20,60,0.35)";
    ctx.shadowBlur = 8;
    ctx.fillStyle = "#fff";
    ctx.font = `800 128px ${FONT}`;
    ctx.fillText(String(years), 256, 205);
    ctx.font = `700 34px ${FONT}`;
    ctx.fillText(years === 1 ? "year together" : "years together", 256, 282);
    ctx.shadowBlur = 0;
    ctx.font = `700 28px ${FONT}`;
    ctx.fillStyle = "#fff0f5";
    ctx.fillText(`${days.toLocaleString()} days ♡`, 256, 326);
    ctx.fillText(`our willow: ${cm >= 100 ? `${(cm / 100).toFixed(2)} m` : `${cm} cm`}`, 256, 362);
    tex.needsUpdate = true;
  }

  // the tree grows 1cm every day: 566 days = 5.66m tall
  setDays(days) {
    days = Math.max(0, Math.round(days));
    if (days === this.days) return;
    this.days = days;
    try {
      localStorage.setItem(DAYS, String(days));
    } catch {}
    const height = treeHeight(days);
    // measure the real top of the tree once, so the height is exact
    if (!this.baseHeight) {
      this.tree.scale.setScalar(1);
      this.root.updateMatrixWorld(true);
      const box = new THREE.Box3().setFromObject(this.tree, true);
      this.baseHeight = (box.max.y - this.root.position.y) / WILLOW_BIG || 6;
    }
    const s = height / this.baseHeight;
    // from the tree's own frame out to the world (the root is drawn bigger)
    this.scale = s * WILLOW_BIG;
    this.tree.scale.setScalar(s);
    this.circle.r = (0.5 * s + 0.1) * WILLOW_BIG;
    this.drawSign();
  }

  // ---- decorations ----------------------------------------------------------------
  save() {
    setShared(STORE, JSON.stringify(this.items));
  }
  freeAnchor() {
    const used = new Set(this.items.map((i) => i.a));
    const free = this.anchors.map((_, i) => i).filter((i) => !used.has(i));
    if (!free.length) return Math.floor(Math.random() * this.anchors.length);
    return free[Math.floor(Math.random() * free.length)];
  }
  add(type, color, by, at) {
    const a = Number.isInteger(at) && at >= 0 && at < this.anchors.length ? at : this.freeAnchor();
    const item = { id: `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`, type, color, a, by };
    this.items.push(item);
    if (this.items.length > 80) this.items.shift();
    this.save();
    this.renderDecor();
    return item;
  }
  merge(list) {
    let changed = false;
    for (const it of list || []) {
      if (!it?.id || this.items.some((x) => x.id === it.id)) continue;
      this.items.push(it);
      changed = true;
    }
    if (changed) {
      this.items = this.items.slice(-80);
      this.save();
      this.renderDecor();
    }
    return changed;
  }
  remove(id) {
    const before = this.items.length;
    this.items = this.items.filter((i) => i.id !== id);
    if (this.items.length === before) return false;
    this.save();
    this.renderDecor();
    return true;
  }

  // glowing spots on the willow where a new decoration can go (you tap one)
  showSpots(on) {
    if (this.spotGroup) {
      this.tree.remove(this.spotGroup);
      this.spotGroup = null;
    }
    this.spotMeshes = [];
    if (!on) return 0;
    const used = new Set(this.items.map((i) => i.a % this.anchors.length));
    const g = new THREE.Group();
    const geo = new THREE.IcosahedronGeometry(0.16, 1);
    const hitGeo = new THREE.SphereGeometry(0.45, 8, 6);
    const hitMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
    this.anchors.forEach((p, i) => {
      if (used.has(i)) return;
      const dot = new THREE.Mesh(geo, glow.pink);
      dot.position.copy(p);
      g.add(dot);
      const hit = new THREE.Mesh(hitGeo, hitMat);
      hit.position.copy(p);
      hit.userData.anchor = i;
      g.add(hit);
      this.spotMeshes.push(hit);
    });
    this.spotGroup = g;
    this.tree.add(g);
    return this.spotMeshes.length;
  }

  renderDecor() {
    for (const c of [...this.decorGroup.children]) {
      this.decorGroup.remove(c);
      c.traverse((o) => o.geometry?.dispose());
    }
    this.blinkers = [];
    for (const it of this.items) {
      const at = this.anchors[it.a % this.anchors.length];
      if (!at) continue;
      const g = makeDecor(it.type, it.color || "#ff8fb1");
      g.position.copy(at);
      // facing out, and big enough to read from the path
      g.rotation.y = this.anchorAngles[it.a % this.anchors.length] || 0;
      g.scale.setScalar(1.8);
      g.userData.seed = it.a;
      this.decorGroup.add(g);
      if (g.userData.blink) this.blinkers.push(g.userData.blink);
    }
  }

  update(t) {
    this.updateStrands(t);
    this.decorGroup.children.forEach((g, i) => {
      g.rotation.z = Math.sin(t * 1.4 + i) * 0.08;
    });
    for (const m of this.blinkers || []) m.emissiveIntensity = 1 + Math.sin(t * 3 + m.id) * 0.6;
    this.signSwing.rotation.y = Math.sin(t * 0.8) * 0.12;
    if (this.spotGroup) this.spotGroup.children.forEach((m, i) => {
      if (!m.userData.anchor && m.userData.anchor !== 0) m.scale.setScalar(1 + Math.sin(t * 4 + i) * 0.25);
    });
  }
}

// one decoration, hanging from its anchor (local origin = the branch)
function makeDecor(type, color) {
  const g = new THREE.Group();
  const string = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, 0.35, 3), mat("#fff7f2"));
  const hang = (obj, drop = 0.35) => {
    string.position.y = -drop / 2;
    string.scale.y = drop / 0.35;
    g.add(string);
    obj.position.y = -drop;
    g.add(obj);
    return obj;
  };
  if (type === "lights") {
    // a little loop of glowing bulbs
    const m = glowMat(color);
    g.userData.blink = m;
    for (let k = 0; k < 7; k++) {
      const a = (k / 6) * Math.PI;
      const b = new THREE.Mesh(new THREE.IcosahedronGeometry(0.05, 0), m);
      b.position.set(Math.cos(a) * 0.4 - 0.0, -Math.sin(a) * 0.25, 0);
      g.add(b);
    }
  } else if (type === "lantern") {
    const l = new THREE.Group();
    const m = glowMat(color);
    g.userData.blink = m;
    const body = new THREE.Mesh(new THREE.SphereGeometry(0.14, 8, 6), m);
    body.scale.y = 1.25;
    l.add(body);
    for (const y of [-0.17, 0.17]) {
      const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.04, 8), mat("#8a5a3c"));
      cap.position.y = y;
      l.add(cap);
    }
    hang(l, 0.4);
  } else if (type === "heart") {
    const geo = new THREE.ExtrudeGeometry(heartShape(0.13), { depth: 0.05, bevelEnabled: false });
    geo.translate(0, 0, -0.025);
    hang(new THREE.Mesh(geo, mat(color, { roughness: 0.5 })), 0.35);
  } else if (type === "star") {
    const s = new THREE.Shape();
    for (let k = 0; k < 10; k++) {
      const r = k % 2 ? 0.06 : 0.14;
      const a = (k / 10) * Math.PI * 2;
      k ? s.lineTo(Math.sin(a) * r, Math.cos(a) * r) : s.moveTo(Math.sin(a) * r, Math.cos(a) * r);
    }
    const geo = new THREE.ExtrudeGeometry(s, { depth: 0.04, bevelEnabled: false });
    geo.translate(0, 0, -0.02);
    const m = glowMat(color);
    m.emissiveIntensity = 0.6;
    hang(new THREE.Mesh(geo, m), 0.32);
  } else if (type === "ribbon") {
    const m = mat(color);
    for (const s of [-1, 1]) {
      const lobe = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.16, 4), m);
      lobe.position.x = s * 0.08;
      lobe.rotation.z = (s * Math.PI) / 2;
      g.add(lobe);
      const tail = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.22, 0.01), m);
      tail.position.set(s * 0.04, -0.13, 0);
      tail.rotation.z = s * 0.3;
      g.add(tail);
    }
    g.add(new THREE.Mesh(new THREE.IcosahedronGeometry(0.04, 0), m));
  } else if (type === "flower") {
    const m = mat(color);
    for (let k = 0; k < 6; k++) {
      const a = k * 1.1;
      const p = new THREE.Mesh(new THREE.IcosahedronGeometry(0.07, 0), m);
      p.position.set(Math.sin(a) * 0.12, Math.cos(a) * 0.08 - 0.05, Math.cos(a * 1.7) * 0.06);
      g.add(p);
    }
    const c = new THREE.Mesh(new THREE.IcosahedronGeometry(0.05, 0), mat("#ffd166"));
    c.position.y = -0.04;
    g.add(c);
  } else if (type === "note") {
    const card = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.14, 0.01), mat("#fff7f2"));
    hang(card, 0.3);
    const heart = new THREE.Mesh(new THREE.IcosahedronGeometry(0.03, 0), mat(color));
    heart.position.set(0, -0.3, 0.01);
    g.add(heart);
  } else if (type === "bird") {
    const m = mat(color);
    const body = new THREE.Mesh(new THREE.SphereGeometry(0.09, 7, 5), m);
    body.scale.set(1, 0.9, 1.3);
    body.position.y = 0.08;
    g.add(body);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.06, 7, 5), m);
    head.position.set(0, 0.17, 0.08);
    g.add(head);
    const beak = new THREE.Mesh(new THREE.ConeGeometry(0.02, 0.05, 4), mat("#ffb000"));
    beak.position.set(0, 0.17, 0.15);
    beak.rotation.x = Math.PI / 2;
    g.add(beak);
  }
  g.traverse((o) => {
    if (o.isMesh) o.castShadow = false;
  });
  return g;
}

// merge non-indexed geometries (position + normal, and uv when asked)
function mergeSimple(geos, withUv = false) {
  let count = 0;
  for (const g of geos) count += g.attributes.position.count;
  const pos = new Float32Array(count * 3);
  const nor = new Float32Array(count * 3);
  const uv = withUv ? new Float32Array(count * 2) : null;
  let o = 0;
  for (const g of geos) {
    if (!withUv) g.computeVertexNormals();
    pos.set(g.attributes.position.array, o * 3);
    nor.set(g.attributes.normal.array, o * 3);
    if (uv) uv.set(g.attributes.uv.array, o * 2);
    o += g.attributes.position.count;
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  out.setAttribute("normal", new THREE.BufferAttribute(nor, 3));
  if (uv) out.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
  return out;
}

// a strip of willow: a few thin stems with little leaves, thinning at the tip
let strandTex = null;
function willowStrandTexture() {
  if (strandTex) return strandTex;
  const c = document.createElement("canvas");
  c.width = 128;
  c.height = 512;
  const x = c.getContext("2d");
  let seed = 7;
  const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
  for (let s = 0; s < 7; s++) {
    const x0 = 10 + s * 18 + rnd() * 5;
    const end = 380 + rnd() * 120;
    x.strokeStyle = "rgba(120,150,90,0.9)";
    x.lineWidth = 1.5;
    x.beginPath();
    for (let y = 0; y <= end; y += 8) {
      const xx = x0 + Math.sin(y * 0.018 + s) * 5;
      y ? x.lineTo(xx, y) : x.moveTo(xx, y);
    }
    x.stroke();
    for (let y = 4; y < end; y += 7 + rnd() * 3) {
      const xx = x0 + Math.sin(y * 0.018 + s) * 5;
      const side = rnd() < 0.5 ? -1 : 1;
      const size = 1 - (y / end) * 0.45;
      const l = 236 - Math.round(rnd() * 40);
      x.fillStyle = `rgb(${l - 20},${Math.min(255, l + 15)},${l - 60})`;
      x.save();
      x.translate(xx + side * 3.5 * size, y);
      x.rotate(side * (0.45 + rnd() * 0.3));
      x.beginPath();
      x.ellipse(0, 0, 3.2 * size, 9.5 * size, 0, 0, Math.PI * 2);
      x.fill();
      x.restore();
    }
  }
  strandTex = new THREE.CanvasTexture(c);
  strandTex.colorSpace = THREE.SRGBColorSpace;
  strandTex.anisotropy = 4;
  return strandTex;
}
